window.DL_DATA={"standards": [{"id": "8.PS1.1", "domain": "PS", "title": "Atoms as a system", "idea": "A nucleus of protons and neutrons is surrounded by electrons.", "mnemonic": "PEN: protons, electrons, neutrons"}, {"id": "8.PS1.2", "domain": "PS", "title": "Fusion and starlight", "idea": "Fusion changes nuclei, builds heavier atoms, and releases starlight."}, {"id": "8.PS2.1", "domain": "PS", "title": "Field strength", "idea": "Electric and magnetic forces grow with charge or strength, shrink with distance."}, {"id": "8.PS2.2", "domain": "PS", "title": "Electromagnets", "idea": "Current, coils, and cores change electromagnets, motors, and generators."}, {"id": "8.PS2.3", "domain": "PS", "title": "Gravity", "idea": "Gravity attracts. More mass or less distance means a stronger pull."}, {"id": "8.PS2.4", "domain": "PS", "title": "Relative motion", "idea": "Position and motion depend on the observer's frame of reference."}, {"id": "8.PS2.5", "domain": "PS", "title": "Net force and mass", "idea": "Change in motion depends on net force and mass (a = F/m)."}, {"id": "8.PS2.6", "domain": "PS", "title": "Action and reaction", "idea": "Forces come in equal and opposite pairs on two different objects."}, {"id": "8.PS4.1", "domain": "PS", "title": "Wave properties", "idea": "Waves have amplitude, wavelength, frequency, and speed.", "mnemonic": "A wave's FAWS: frequency, amplitude, wavelength, speed"}, {"id": "8.PS4.2", "domain": "PS", "title": "Mechanical vs EM", "idea": "Mechanical waves need a medium; electromagnetic waves can cross a vacuum."}, {"id": "8.PS4.3", "domain": "PS", "title": "Digital signals", "idea": "Digitized wave pulses are more reliable than analog for sending information."}, {"id": "8.LS4.1", "domain": "LS", "title": "Fossil record", "idea": "Fossils document existence, diversity, extinction, and change over time."}, {"id": "8.LS4.2", "domain": "LS", "title": "Common ancestry", "idea": "Shared anatomy and genetic information link extinct and living species."}, {"id": "8.LS4.3", "domain": "LS", "title": "Variation and survival", "idea": "Heritable variation changes who is more likely to survive and reproduce."}, {"id": "8.LS4.4", "domain": "LS", "title": "Natural selection", "idea": "Environments favor some heritable traits; populations can shift as conditions change."}, {"id": "8.LS4.5", "domain": "LS", "title": "Artificial selection", "idea": "Humans use breeding and biotech to influence inherited traits."}, {"id": "8.ESS1.1", "domain": "ESS", "title": "Big Bang evidence", "idea": "Redshift, CMB, and H/He abundances support a rapidly expanding universe.", "mnemonic": "Red glow, leftover glow, H and He"}, {"id": "8.ESS2.1", "domain": "ESS", "title": "Change and extinction", "idea": "Rapid or gradual geographic change can crash populations and cause extinction."}, {"id": "8.ESS2.2", "domain": "ESS", "title": "Earth's interior", "idea": "Seismic waves model Earth's layers; interior heat powers geology."}, {"id": "8.ESS2.3", "domain": "ESS", "title": "Convection and plates", "idea": "Mantle convection moves plates, builds boundaries, and spreads seafloor."}, {"id": "8.ESS2.4", "domain": "ESS", "title": "Plate evidence", "idea": "Matching fossils and landforms are explained by slow plate tectonics."}, {"id": "8.ESS3.1", "domain": "ESS", "title": "Hazards and forecasts", "idea": "Quakes and volcanoes cluster at plate boundaries and hotspots."}, {"id": "8.ETS1.1", "domain": "ETS", "title": "Electromagnet design", "idea": "Test electromagnet models against criteria and constraints."}, {"id": "8.ETS2.1", "domain": "ETS", "title": "Tools and discovery", "idea": "Telescopes, probes, and seismographs both gather data and improve from science."}], "worlds": [{"id": "matter", "title": "Matter Lab", "blurb": "Atoms, nuclei, and the light of stars", "standards": ["8.PS1.1", "8.PS1.2"], "minutes": 10}, {"id": "fields", "title": "Field Lab", "blurb": "Electric, magnetic, and gravitational forces", "standards": ["8.PS2.1", "8.PS2.2", "8.PS2.3", "8.ETS1.1"], "minutes": 12}, {"id": "motion", "title": "Motion Lab", "blurb": "Observers, net force, and action-reaction", "standards": ["8.PS2.4", "8.PS2.5", "8.PS2.6"], "minutes": 10}, {"id": "waves", "title": "Wave Lab", "blurb": "Properties, media, and digital signals", "standards": ["8.PS4.1", "8.PS4.2", "8.PS4.3"], "minutes": 10}, {"id": "cosmos", "title": "Cosmos Lab", "blurb": "The expanding universe and the tools that map it", "standards": ["8.ESS1.1", "8.ETS2.1"], "minutes": 10}, {"id": "earth", "title": "Earth Lab", "blurb": "Interior heat, plates, and extinction", "standards": ["8.ESS2.1", "8.ESS2.2", "8.ESS2.3", "8.ESS2.4"], "minutes": 12}, {"id": "hazards", "title": "Hazard Lab", "blurb": "Earthquakes, volcanoes, and forecasts", "standards": ["8.ESS3.1"], "minutes": 8}, {"id": "life", "title": "Life Lab", "blurb": "Fossils, ancestry, and selection", "standards": ["8.LS4.1", "8.LS4.2", "8.LS4.3", "8.LS4.4", "8.LS4.5"], "minutes": 12}], "items": [{"id": "8.ESS1.1-r01", "standard": "8.ESS1.1", "kind": "recall", "prompt": "The Big Bang model says the universe began with", "correct": "a hot, dense state that rapidly expanded", "distractors": ["an explosion of matter into already-empty space", "the Sun forming first, then everything else", "a universe that has always stayed the same size"], "why": "The Big Bang is space itself expanding from a hot, dense early state, not an explosion into empty space."}, {"id": "8.ESS1.1-r02", "standard": "8.ESS1.1", "kind": "recall", "prompt": "Redshift in light from a distant galaxy means the galaxy is", "correct": "moving away from us", "distractors": ["moving toward us", "getting hotter", "not moving at all"], "why": "Light from a source moving away is stretched to longer, redder wavelengths."}, {"id": "8.ESS1.1-r03", "standard": "8.ESS1.1", "kind": "recall", "prompt": "Blueshift in light from a star means the star is", "correct": "moving toward us", "distractors": ["moving away from us", "cooling down", "getting larger"], "why": "Light from a source moving closer is squeezed to shorter, bluer wavelengths."}, {"id": "8.ESS1.1-r04", "standard": "8.ESS1.1", "kind": "recall", "prompt": "When light is redshifted, its spectral lines move toward", "correct": "longer wavelengths", "distractors": ["shorter wavelengths", "higher frequencies", "the blue end of the spectrum"], "why": "Red light has longer wavelengths than blue light, so redshift means lines move toward longer wavelengths."}, {"id": "8.ESS1.1-r05", "standard": "8.ESS1.1", "kind": "recall", "prompt": "The cosmic microwave background (CMB) is", "correct": "leftover radiation from the hot early universe", "distractors": ["light from the nearest stars", "radio signals from Earth", "heat from the Sun reflecting off planets"], "why": "The CMB is faint, cooled radiation left over from when the universe was very hot and dense."}, {"id": "8.ESS1.1-r06", "standard": "8.ESS1.1", "kind": "recall", "prompt": "The CMB is detected", "correct": "from every direction in the sky", "distractors": ["only from the direction of the Sun", "only from the center of the Milky Way", "only from one distant galaxy"], "why": "Because it fills all of space, the CMB arrives from every direction."}, {"id": "8.ESS1.1-r07", "standard": "8.ESS1.1", "kind": "recall", "prompt": "The two most abundant elements in the universe are", "correct": "hydrogen and helium", "distractors": ["oxygen and carbon", "iron and nickel", "nitrogen and oxygen"], "why": "Big Bang models predict mostly hydrogen and helium, and that is what we observe."}, {"id": "8.ESS1.1-r08", "standard": "8.ESS1.1", "kind": "recall", "prompt": "Big Bang models predict the amounts of hydrogen and helium that formed in the early universe. Observations show", "correct": "the measured amounts closely match the predictions", "distractors": ["much more helium than hydrogen", "that most hydrogen formed later inside stars", "the amounts do not match, so the model was discarded"], "why": "The match between predicted and measured H/He amounts is one line of evidence for the Big Bang."}, {"id": "8.ESS1.1-r09", "standard": "8.ESS1.1", "kind": "recall", "prompt": "Which is NOT one of the main lines of evidence for the Big Bang?", "correct": "the age of rocks on Earth", "distractors": ["redshift of distant galaxies", "the cosmic microwave background", "the abundance of hydrogen and helium"], "why": "Rock ages tell us about Earth, not about the origin of the universe."}, {"id": "8.ESS1.1-r10", "standard": "8.ESS1.1", "kind": "recall", "prompt": "Most distant galaxies show redshift. This supports the idea that the universe is", "correct": "expanding", "distractors": ["shrinking", "not changing in size", "moving toward a single center point"], "why": "If nearly all distant galaxies move away from us, space is expanding."}, {"id": "8.ESS1.1-r11", "standard": "8.ESS1.1", "kind": "recall", "prompt": "Galaxies that are farther away tend to show", "correct": "more redshift", "distractors": ["less redshift", "no redshift", "blueshift instead"], "why": "More distant galaxies recede faster, so their light is shifted more toward red."}, {"id": "8.ESS1.1-r12", "standard": "8.ESS1.1", "kind": "recall", "prompt": "If galaxies are moving apart now, in the past they were", "correct": "closer together", "distractors": ["farther apart", "in the same places as today", "moving toward each other"], "why": "Running expansion backward means everything was once closer together."}, {"id": "8.ESS1.1-r13", "standard": "8.ESS1.1", "kind": "recall", "prompt": "As the universe expanded, it", "correct": "cooled", "distractors": ["heated up", "stayed the same temperature", "got denser"], "why": "Expanding gas and radiation cool, which is why the CMB is now cold microwaves."}, {"id": "8.ESS1.1-r14", "standard": "8.ESS1.1", "kind": "recall", "prompt": "Scientists trust the Big Bang model because", "correct": "several independent lines of evidence agree", "distractors": ["one famous scientist said it was true", "it has never been questioned", "it was observed directly as it happened"], "why": "Redshift, the CMB, and H/He amounts all point to the same conclusion."}, {"id": "8.ESS1.1-r15", "standard": "8.ESS1.1", "kind": "recall", "prompt": "A spectrum shows", "correct": "the wavelengths of light from an object", "distractors": ["a photo showing the shape of a galaxy", "how far a galaxy is, measured in miles", "only how bright an object looks to us"], "why": "Spectra split light into wavelengths; shifts in the lines show motion."}, {"id": "8.ESS1.1-r16", "standard": "8.ESS1.1", "kind": "recall", "prompt": "The CMB is observed today mainly as", "correct": "microwaves", "distractors": ["visible light", "X-rays", "sound waves"], "why": "Expansion stretched the early universe's light into the microwave range."}, {"id": "8.ESS1.1-r17", "standard": "8.ESS1.1", "kind": "recall", "prompt": "\"The Big Bang happened at one spot, and we are at the center.\" What is wrong with this?", "correct": "There is no center; space expanded everywhere", "distractors": ["Nothing, because Earth is the center", "The Big Bang happened at the edge of the universe", "Galaxies move away from where the explosion started"], "why": "Every galaxy sees others moving away because space itself is expanding everywhere, so there is no edge or starting spot to point to."}, {"id": "8.ESS1.1-r18", "standard": "8.ESS1.1", "kind": "recall", "prompt": "Which observation would most weaken the expanding-universe model?", "correct": "most distant galaxies showing blueshift", "distractors": ["finding more hydrogen than helium", "detecting the CMB in all directions", "nearby stars showing small shifts"], "why": "If most distant galaxies were approaching, that would argue against expansion."}, {"id": "8.ESS1.1-r19", "standard": "8.ESS1.1", "kind": "recall", "prompt": "A nearby star shows slight blueshift. This means", "correct": "that star is moving toward us", "distractors": ["the universe is shrinking", "the star is cooling down", "the star is made of blue gas"], "why": "Nearby stars can move toward us because of gravity. One blueshifted star does not mean the universe is shrinking; distant galaxies still show redshift. Color shift is about motion, not the gas color or temperature."}, {"id": "8.ESS1.1-r20", "standard": "8.ESS1.1", "kind": "recall", "prompt": "Heavier elements like iron mostly formed", "correct": "later, inside stars", "distractors": ["in the first minutes of the universe", "inside Earth's core", "in the CMB"], "why": "The early universe made mostly hydrogen and helium; stars fused heavier elements later."}, {"id": "8.ESS1.1-s01", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "An astronomer measures the spectra of 20 distant galaxies. All 20 show lines shifted toward red, and the farthest show the biggest shifts. Which claim is best supported?", "correct": "The universe is expanding, and more distant galaxies move away faster.", "distractors": ["The galaxies are all moving toward Earth at the same speed.", "The galaxies are getting colder, which makes them look red.", "The galaxies are made of red dust that colors their light."], "why": "Consistent redshift that increases with distance is evidence of expansion."}, {"id": "8.ESS1.1-s02", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "A telescope pointed in any direction picks up a faint, even microwave glow. What does this most likely show?", "correct": "leftover radiation from the hot early universe", "distractors": ["radio noise from cell towers and satellites", "heat given off by the telescope itself", "light from one bright nearby star"], "why": "The CMB is uniform across the sky because it fills all space."}, {"id": "8.ESS1.1-s03", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "A student says, \"The Big Bang is just a guess because no one was there.\" Which reply uses evidence best?", "correct": "Redshift, the CMB, and H/He amounts all match the model.", "distractors": ["Scientists all agreed to believe it long ago.", "It is in our textbook, so it has to be true.", "It does not matter, because it happened so long ago."], "why": "Scientific models are supported by evidence we can measure now, even about the past."}, {"id": "8.ESS1.1-s04", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "A model predicts the early universe made about 75% hydrogen and 25% helium by mass. Measurements of old gas clouds show close to those amounts. This is", "correct": "evidence supporting the Big Bang model", "distractors": ["proof that stars made all the helium", "evidence the universe is shrinking", "unrelated to the Big Bang"], "why": "A correct prediction that matches data supports the model."}, {"id": "8.ESS1.1-s05", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "Galaxy A shows a small redshift. Galaxy B shows a large redshift. Which is most likely true?", "correct": "Galaxy B is farther away and moving away faster.", "distractors": ["Galaxy A is farther away and moving away faster.", "Both galaxies are moving toward us at different speeds.", "Galaxy B is hotter, so its light looks redder."], "why": "Larger redshift goes with greater distance and faster recession."}, {"id": "8.ESS1.1-s06", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "A spectrum of a distant galaxy shows a hydrogen line at a longer wavelength than in a lab on Earth. What can you conclude?", "correct": "The galaxy is moving away from us.", "distractors": ["The galaxy has no hydrogen.", "The galaxy is moving toward us.", "The lab equipment is broken."], "why": "A known line appearing at a longer wavelength is redshift, meaning the source is moving away."}, {"id": "8.ESS1.1-s07", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "A classmate draws the Big Bang as a bomb exploding in a dark room. How should the model be corrected?", "correct": "Show space itself stretching, so galaxies spread apart.", "distractors": ["Make the explosion bigger and brighter in the drawing.", "Put Earth in the center with galaxies flying away.", "Show the galaxies moving back toward one center point."], "why": "The Big Bang was an expansion of space, not an explosion into existing space."}, {"id": "8.ESS1.1-s08", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "Two lines of evidence are listed: (1) the CMB and (2) redshift. Which third line would best complete the case for the Big Bang?", "correct": "measured abundances of hydrogen and helium", "distractors": ["the shape of the Moon's craters", "the age of dinosaur fossils", "the number of planets in our solar system"], "why": "The three key lines are redshift, the CMB, and H/He abundances."}, {"id": "8.ESS1.1-s09", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "A star shows lines shifted toward blue, but almost every distant galaxy shows redshift. How should a scientist interpret this?", "correct": "The star is moving toward us, but distant galaxies still show expansion.", "distractors": ["The universe must be shrinking, since the star shows blueshift.", "Redshift data for all the galaxies must be wrong.", "The star must be much older than the distant galaxies."], "why": "One nearby object approaching does not overturn a pattern seen across many distant galaxies."}, {"id": "8.ESS1.1-s10", "standard": "8.ESS1.1", "kind": "scenario", "prompt": "If the CMB had been found only in one small patch of sky, how would that affect the Big Bang model?", "correct": "It would weaken it, since the model predicts it from every direction.", "distractors": ["It would strengthen it, since the radiation would be easier to find.", "It would have no effect, since the CMB is not evidence.", "It would prove the universe is shrinking, not expanding."], "why": "The Big Bang predicts the CMB fills all space, so it should come from everywhere."}, {"id": "8.ESS2.1-r01", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Which is an example of RAPID geographic change?", "correct": "a volcanic eruption burying a forest", "distractors": ["mountains rising over millions of years", "a river slowly changing its course", "continents drifting apart"], "why": "Eruptions change a habitat in hours to days."}, {"id": "8.ESS2.1-r02", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Which is an example of GRADUAL geographic change?", "correct": "a mountain range rising over millions of years", "distractors": ["an asteroid impact that changes climate in days", "a landslide that buries a valley in minutes", "a volcanic eruption that covers a forest in ash"], "why": "Mountain building happens slowly over geologic time."}, {"id": "8.ESS2.1-r03", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Both rapid and gradual geographic changes can lead to", "correct": "population declines and extinction", "distractors": ["only new species forming, never extinction", "no effect on living things", "changes only in ocean life"], "why": "Either kind of change can remove habitat faster than species can adapt or move."}, {"id": "8.ESS2.1-r04", "standard": "8.ESS2.1", "kind": "recall", "prompt": "The main difference between rapid and gradual change is", "correct": "the timescale over which it happens", "distractors": ["whether it affects living things", "whether it happens on land", "whether scientists can study it"], "why": "Both can cause extinction; they differ in how fast they happen."}, {"id": "8.ESS2.1-r05", "standard": "8.ESS2.1", "kind": "recall", "prompt": "An asteroid impact about 66 million years ago is linked to", "correct": "the extinction of most dinosaurs and many other species", "distractors": ["the formation of the Moon from a giant collision", "the first appearance of life in Earth's oceans", "the breakup of Pangaea into separate continents"], "why": "The impact rapidly changed climate worldwide, causing a mass extinction."}, {"id": "8.ESS2.1-r06", "standard": "8.ESS2.1", "kind": "recall", "prompt": "A mass extinction is when", "correct": "many species die out in a short span of geologic time", "distractors": ["one species moves into a new area over time", "a population grows quickly in a short time", "a single animal dies during a harsh winter"], "why": "Mass extinctions wipe out large numbers of species relatively quickly."}, {"id": "8.ESS2.1-r07", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Drastic population change means", "correct": "a population's numbers rise or fall sharply", "distractors": ["the population stays about the same over time", "one new animal is born into the group", "a species slowly changes its color over time"], "why": "Drastic means a large, sharp change in numbers."}, {"id": "8.ESS2.1-r08", "standard": "8.ESS2.1", "kind": "recall", "prompt": "When ocean floor is lifted to become dry land, the marine organisms there will most likely", "correct": "die out or leave that area", "distractors": ["evolve into land animals immediately", "stay unchanged", "grow lungs within a few years"], "why": "Organisms can't change fast enough to survive losing their whole habitat, so they die out or move away. Evolution takes many generations."}, {"id": "8.ESS2.1-r09", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Evidence that a geographic change caused an extinction would include", "correct": "fossils that disappear at the same layer as the change", "distractors": ["fossils of the animal found in just one layer", "the animal's living relatives found today", "the color of the rock where fossils are found"], "why": "Fossils plus dated rock layers link the change to the extinction."}, {"id": "8.ESS2.1-r10", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Climate cooling over thousands of years during an ice age is a", "correct": "gradual change", "distractors": ["rapid change", "change that cannot affect life", "a change that happens in minutes"], "why": "Thousands of years is gradual compared with an eruption or impact."}, {"id": "8.ESS2.1-r11", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Rising sea level that floods coastal lowlands over centuries can", "correct": "shrink or split land populations", "distractors": ["only increase land habitat", "have no effect on land animals", "create new land everywhere"], "why": "Flooding reduces and divides land habitat."}, {"id": "8.ESS2.1-r12", "standard": "8.ESS2.1", "kind": "recall", "prompt": "A huge volcanic eruption that blocks sunlight for years can cause extinction because", "correct": "plants can't photosynthesize well, so food chains collapse", "distractors": ["the ash poisons all of the ocean water instantly", "animals cannot see well enough to find any food", "ash makes plants grow faster, so animals overeat"], "why": "Less sunlight means less plant growth, which affects everything that depends on plants."}, {"id": "8.ESS2.1-r13", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Which data would best show a drastic population decline?", "correct": "fossil counts that drop sharply between two rock layers", "distractors": ["a single fossil of the animal from one place", "a fossil count from just one rock layer only", "the average body length of one animal species"], "why": "A sharp drop in fossil abundance across layers shows a decline."}, {"id": "8.ESS2.1-r14", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Pollen in lake sediment changing from tree pollen to grass pollen shows", "correct": "the environment changed from forest to grassland", "distractors": ["no change happened", "trees became grass", "the lake dried up and refilled every year"], "why": "Pollen records show which plants lived there over time."}, {"id": "8.ESS2.1-r15", "standard": "8.ESS2.1", "kind": "recall", "prompt": "A habitat that changes slowly gives organisms more chance to", "correct": "move or adapt over generations", "distractors": ["become extinct instantly", "stop reproducing", "change their DNA on purpose"], "why": "Slow change allows migration and natural selection to keep up."}, {"id": "8.ESS2.1-r16", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Habitat loss caused by people, like clearing forests, is a modern example of", "correct": "environmental change stressing populations", "distractors": ["a rapid geologic change like an asteroid", "a change that cannot cause extinction", "seafloor spreading"], "why": "Human changes to land can cause declines and extinctions too."}, {"id": "8.ESS2.1-r17", "standard": "8.ESS2.1", "kind": "recall", "prompt": "Rock layers are useful for this standard because deeper layers are generally", "correct": "older", "distractors": ["younger", "the same age as the surface", "always from the ocean"], "why": "In undisturbed layers, the oldest rock is at the bottom."}, {"id": "8.ESS2.1-r18", "standard": "8.ESS2.1", "kind": "recall", "prompt": "When a land bridge forms between two continents, species can", "correct": "move between them and compete", "distractors": ["never meet, because land bridges block movement", "only go extinct from the cold of the new land", "stop evolving because they have more space"], "why": "New connections let species spread and compete."}, {"id": "8.ESS2.1-r19", "standard": "8.ESS2.1", "kind": "recall", "prompt": "A claim that \"volcanoes caused this extinction\" is strongest when it includes", "correct": "dated ash layers matching where the fossils stop", "distractors": ["a scientist's opinion about what happened", "a picture of a volcano near the fossil site", "the name and size of the extinct animal"], "why": "Data that matches the timing of both events supports the claim."}, {"id": "8.ESS2.1-r20", "standard": "8.ESS2.1", "kind": "recall", "prompt": "A lake slowly filling with sediment over thousands of years is a", "correct": "gradual change", "distractors": ["rapid change", "change with no effect on fish", "mass extinction"], "why": "Thousands of years of filling is gradual."}, {"id": "8.ESS2.1-s01", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "Fossils of a shallow-sea clam are common in rock layers 1 to 5, then absent above layer 5. Layer 6 contains land-plant fossils. What is the best explanation?", "correct": "The area changed from sea to land, and the clams died out there.", "distractors": ["The clams slowly evolved into the land plants.", "The clams moved up and lived among the land plants.", "Fossils above layer 5 were all destroyed by erosion."], "why": "The change in fossils shows a habitat change from sea to land."}, {"id": "8.ESS2.1-s02", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "A thin layer of ash and glassy beads is found worldwide in rocks about 66 million years old. Many fossil species disappear right above it. This supports the claim that", "correct": "a rapid event caused a mass extinction", "distractors": ["extinction was gradual over millions of years", "the ash had no effect on life", "dinosaurs caused the ash layer"], "why": "A worldwide layer at the extinction boundary points to a sudden event like an impact."}, {"id": "8.ESS2.1-s03", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "A graph shows a woolly mammoth population shrinking over several thousand years as the climate warmed and grasslands turned to forest. This is an example of", "correct": "gradual change contributing to population decline", "distractors": ["rapid change caused by an asteroid impact", "population growth caused by more food", "no environmental change during that time"], "why": "Slow climate and habitat change over thousands of years is gradual."}, {"id": "8.ESS2.1-s04", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "After a volcanic eruption, a frog species vanishes from an island's fossil record within a few layers. Which assertion is best supported?", "correct": "A rapid change can cause drastic decline and extinction.", "distractors": ["Only slow climate change can cause extinction.", "Volcanoes cannot affect living things nearby.", "Extinction only happens to species in oceans."], "why": "The timing shows a rapid change followed by extinction."}, {"id": "8.ESS2.1-s05", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "Two islands were once one island. Rising sea level slowly split it. Now each island has a different lizard population. What happened?", "correct": "Gradual sea-level rise divided the population.", "distractors": ["An asteroid split the island in a day.", "The lizards chose to separate.", "Sea level does not affect land animals."], "why": "Slow flooding can split populations, which then change separately."}, {"id": "8.ESS2.1-s06", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "A student says, \"Slow changes can't cause extinction, only disasters can.\" Which evidence best refutes this?", "correct": "Fossils show species dying out as climate slowly cooled.", "distractors": ["An asteroid impact caused a mass extinction.", "Volcanoes erupt and change land very quickly.", "Some animals are able to survive disasters."], "why": "Gradual change can also cause extinction if species cannot adapt or move."}, {"id": "8.ESS2.1-s07", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "Two rock layers have fish fossils below and desert sand above. What two pieces of data would make the \"lake dried up\" claim strongest?", "correct": "the age of each layer and the fossils found in each", "distractors": ["the color and grain size of the sand only", "the name of the scientist who found them", "the amount of rainfall in the area today"], "why": "Dated layers plus the fossil types show when and how the environment changed."}, {"id": "8.ESS2.1-s08", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "A data table shows 40 species in layer A, 38 in layer B, and 6 in layer C. Which statement fits the data?", "correct": "A drastic extinction happened between layers B and C.", "distractors": ["The number of species slowly increased over time.", "Nothing changed between the three rock layers.", "The big extinction happened between A and B."], "why": "The big drop is from 38 to 6, between B and C."}, {"id": "8.ESS2.1-s09", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "A landslide buries a valley in minutes, and a beetle found only there disappears. What kind of change was it, and what was the effect?", "correct": "rapid change causing local extinction", "distractors": ["gradual change causing population growth", "rapid change with no effect", "gradual change causing extinction"], "why": "Minutes is rapid, and the only habitat was lost."}, {"id": "8.ESS2.1-s10", "standard": "8.ESS2.1", "kind": "scenario", "prompt": "A scientist finds tropical fern fossils in rock in Antarctica. Which explanation is MOST complete?", "correct": "It was once warmer there, from climate change or plate motion.", "distractors": ["Ferns can grow on the ice in Antarctica today.", "The fossils were blown there by strong winds from far away.", "Antarctica has always had the same climate as today."], "why": "The fossils show a past environment very different from today's."}, {"id": "8.ESS2.2-r01", "standard": "8.ESS2.2", "kind": "recall", "prompt": "A seismograph records", "correct": "ground motion from seismic waves", "distractors": ["air pressure changes", "ocean tide heights", "the temperature of rocks"], "why": "Seismographs measure vibrations from earthquakes."}, {"id": "8.ESS2.2-r02", "standard": "8.ESS2.2", "kind": "recall", "prompt": "P-waves can travel through", "correct": "solids, liquids, and gases", "distractors": ["solids only, because they are rigid", "liquids only, like water and magma", "empty space as well as solids"], "why": "P-waves are compression waves that pass through any material."}, {"id": "8.ESS2.2-r03", "standard": "8.ESS2.2", "kind": "recall", "prompt": "S-waves can travel through", "correct": "solids but not liquids", "distractors": ["liquids but not solids", "both solids and liquids", "empty space"], "why": "S-waves shake side to side and cannot move through liquids."}, {"id": "8.ESS2.2-r04", "standard": "8.ESS2.2", "kind": "recall", "prompt": "S-waves do not pass through Earth's outer core. This is evidence that the outer core is", "correct": "liquid", "distractors": ["solid", "gas", "hollow"], "why": "Since S-waves cannot travel through liquids, their shadow shows a liquid outer core."}, {"id": "8.ESS2.2-r05", "standard": "8.ESS2.2", "kind": "recall", "prompt": "Earth's inner core is modeled as", "correct": "solid metal, mostly iron and nickel", "distractors": ["liquid rock, like magma in the mantle", "hollow space filled with hot gas", "mostly water held under high pressure"], "why": "Extreme pressure keeps the very hot inner core solid."}, {"id": "8.ESS2.2-r06", "standard": "8.ESS2.2", "kind": "recall", "prompt": "Which layer is the thinnest?", "correct": "the crust", "distractors": ["the mantle", "the outer core", "the inner core"], "why": "The crust is a thin outer layer compared with the thick mantle and core."}, {"id": "8.ESS2.2-r07", "standard": "8.ESS2.2", "kind": "recall", "prompt": "The thickest layer of Earth is the", "correct": "mantle", "distractors": ["crust", "outer core", "inner core"], "why": "The mantle is about 2,900 km thick."}, {"id": "8.ESS2.2-r08", "standard": "8.ESS2.2", "kind": "recall", "prompt": "Order Earth's layers from the surface inward.", "correct": "crust, mantle, outer core, inner core", "distractors": ["mantle, crust, inner core, outer core", "crust, outer core, mantle, inner core", "inner core, outer core, mantle, crust"], "why": "The crust is outermost and the inner core is at the center."}, {"id": "8.ESS2.2-r09", "standard": "8.ESS2.2", "kind": "recall", "prompt": "As you go deeper into Earth, temperature and pressure", "correct": "both increase", "distractors": ["both decrease", "temperature increases but pressure decreases", "both stay the same"], "why": "Deeper material is hotter and under more weight."}, {"id": "8.ESS2.2-r10", "standard": "8.ESS2.2", "kind": "recall", "prompt": "Earth's interior heat comes mainly from", "correct": "heat from Earth's formation and radioactive decay", "distractors": ["the Sun heating the ground from above", "friction from ocean waves on the seafloor", "burning fossil fuels deep underground"], "why": "Heat from formation and decay of radioactive elements powers the interior."}, {"id": "8.ESS2.2-r11", "standard": "8.ESS2.2", "kind": "recall", "prompt": "Seismic waves change speed and direction (refract) when they", "correct": "enter a layer with different properties", "distractors": ["travel through the same material", "reach the surface only", "are recorded by a seismograph"], "why": "Changes in density and state bend waves, which reveals layer boundaries."}, {"id": "8.ESS2.2-r12", "standard": "8.ESS2.2", "kind": "recall", "prompt": "Which wave arrives at a seismograph first?", "correct": "P-wave", "distractors": ["S-wave", "surface wave", "all arrive together"], "why": "P-waves are the fastest seismic waves."}, {"id": "8.ESS2.2-r13", "standard": "8.ESS2.2", "kind": "recall", "prompt": "Scientists know about Earth's deep interior mainly from", "correct": "how seismic waves travel through it", "distractors": ["drilling to the core", "photos from inside Earth", "samples of the inner core"], "why": "No one has drilled through the crust; seismic waves give the evidence."}, {"id": "8.ESS2.2-r14", "standard": "8.ESS2.2", "kind": "recall", "prompt": "The S-wave shadow zone is", "correct": "a zone over about 104° from the quake with no direct S-waves", "distractors": ["the place on the surface right above the quake", "a zone on the far side where P-waves are strongest", "a layer of rock deep inside that absorbs all waves"], "why": "The liquid outer core blocks S-waves, so seismographs more than about 104° from the quake record no direct S-waves. It is not above the quake, and P-waves still arrive in much of that area."}, {"id": "8.ESS2.2-r15", "standard": "8.ESS2.2", "kind": "recall", "prompt": "Interior heat drives", "correct": "mantle convection, volcanoes, and plate motion", "distractors": ["ocean tides that rise and fall each day", "the changing seasons through the year", "wind patterns that move across the land"], "why": "Interior energy powers geologic processes."}, {"id": "8.ESS2.2-r16", "standard": "8.ESS2.2", "kind": "recall", "prompt": "The outer core's liquid iron moving around helps create", "correct": "Earth's magnetic field", "distractors": ["earthquakes in the crust", "heat that reaches the surface", "ocean currents"], "why": "Moving molten metal generates Earth's magnetic field."}, {"id": "8.ESS2.2-r17", "standard": "8.ESS2.2", "kind": "recall", "prompt": "The mantle is best described as", "correct": "hot solid rock that can flow very slowly", "distractors": ["completely liquid magma", "hollow space", "hard, brittle rock like the crust"], "why": "Most of the mantle is solid but flows over long times."}, {"id": "8.ESS2.2-r18", "standard": "8.ESS2.2", "kind": "recall", "prompt": "Why can't scientists sample the core directly?", "correct": "It is thousands of kilometers deep and far too hot to reach", "distractors": ["It is made of liquid that would leak out if drilled", "Volcanoes already bring up samples of the core", "It is made of gas that would escape into the air"], "why": "The deepest drill hole is only about 12 km."}, {"id": "8.ESS2.2-r19", "standard": "8.ESS2.2", "kind": "recall", "prompt": "P-waves slow down when they enter the outer core because", "correct": "they move from solid into liquid", "distractors": ["they move from liquid into solid", "they stop being waves", "the core is empty"], "why": "P-waves travel slower in liquids, which supports a liquid outer core."}, {"id": "8.ESS2.2-r20", "standard": "8.ESS2.2", "kind": "recall", "prompt": "A model of Earth's interior is useful because it", "correct": "explains the seismic data we observe", "distractors": ["shows exactly what each rock looks like", "is a photograph", "never needs to change"], "why": "Models explain data and are revised when new evidence appears."}, {"id": "8.ESS2.2-s01", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "Seismographs on the far side of Earth from a large earthquake record P-waves but no S-waves. What does this support?", "correct": "Earth has a liquid outer core that blocks S-waves.", "distractors": ["Earth is solid rock all the way through.", "Earth has no core at all, only mantle.", "The seismographs there were not working."], "why": "Missing S-waves mean they hit a liquid layer they cannot cross."}, {"id": "8.ESS2.2-s02", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "P-waves speed up sharply at a depth of about 5,150 km. What is the best explanation?", "correct": "They pass from liquid outer core to solid inner core.", "distractors": ["They reach the crust and travel along the surface.", "They leave Earth's interior and travel into space.", "They turn into S-waves when they reach the core."], "why": "P-waves travel faster in solids than in liquids, so the jump shows the change from the liquid outer core to the solid inner core. They do not leave Earth or turn into S-waves there."}, {"id": "8.ESS2.2-s03", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "A student models Earth as a uniform solid ball. Which observation conflicts with this model?", "correct": "S-waves are missing in a shadow zone on Earth's far side.", "distractors": ["P-waves arrive at seismographs before S-waves.", "Earthquakes happen mostly at plate boundaries.", "The crust is thin compared with the mantle."], "why": "A uniform solid would let S-waves through everywhere."}, {"id": "8.ESS2.2-s04", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "Two seismographs record the same quake. Station A records the S-wave 2 minutes after the P-wave; Station B records it 6 minutes after. Which is true?", "correct": "Station B is farther from the earthquake.", "distractors": ["Station A is farther from the earthquake.", "Both are the same distance.", "Station B recorded a different earthquake."], "why": "The gap between P and S arrivals grows with distance."}, {"id": "8.ESS2.2-s05", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "Lava from a volcano is about 1,200 °C, and deep mines get hotter the deeper they go. What does this evidence support?", "correct": "The interior is very hot, and heat rises with depth.", "distractors": ["Earth's interior is cold, and only lava is hot.", "Heat in the mines comes from the Sun shining in.", "Only the crust near volcanoes is hot."], "why": "Both observations point to a hot interior."}, {"id": "8.ESS2.2-s06", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "A scientist wants to know if a layer deep in Earth is liquid. Which test is best?", "correct": "Check whether S-waves travel through that layer.", "distractors": ["Drill a hole all the way down to the layer.", "Measure the air temperature above that layer.", "Count the earthquakes that happen in the area."], "why": "S-waves only pass through solids, so they test for liquid."}, {"id": "8.ESS2.2-s07", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "Seismic waves bend as they pass deeper into the mantle. What does that tell scientists?", "correct": "Rock properties like density change with depth.", "distractors": ["The mantle is hollow.", "The waves are being bent by the Moon.", "The mantle is the same everywhere."], "why": "Bending (refraction) shows changing properties."}, {"id": "8.ESS2.2-s08", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "A compass points north because of Earth's magnetic field. Which part of the interior model explains the field?", "correct": "moving liquid iron in the outer core", "distractors": ["the solid rock of the crust", "ocean water moving in currents", "the atmosphere around Earth"], "why": "Flowing molten metal acts like a giant generator."}, {"id": "8.ESS2.2-s09", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "A classmate says the mantle is a sea of liquid magma. Which evidence shows this is wrong?", "correct": "S-waves pass through the mantle, so it is mostly solid.", "distractors": ["Volcanoes erupt magma that comes from the mantle.", "The mantle is very hot, so it must be melted.", "P-waves can travel through the whole mantle."], "why": "S-waves cross the mantle, so it is mostly solid even though it flows slowly."}, {"id": "8.ESS2.2-s10", "standard": "8.ESS2.2", "kind": "scenario", "prompt": "Without interior heat, which would most likely happen over a very long time?", "correct": "Volcanoes and plate motion would slow and stop.", "distractors": ["More earthquakes would occur.", "The crust would get thicker in a day.", "The magnetic field would get stronger."], "why": "Interior heat powers geologic activity."}, {"id": "8.ESS2.3-r01", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Convection currents in the mantle happen because", "correct": "warm material rises and cool material sinks", "distractors": ["cooler material rises and hotter material sinks", "wind blows across the top of the mantle", "the Moon's gravity pulls the mantle around"], "why": "Density differences from heating drive convection."}, {"id": "8.ESS2.3-r02", "standard": "8.ESS2.3", "kind": "recall", "prompt": "The lithosphere is made of", "correct": "the crust and the rigid upper mantle", "distractors": ["the crust only", "the asthenosphere", "the crust and the outer core"], "why": "The lithosphere is the rigid outer shell broken into plates."}, {"id": "8.ESS2.3-r03", "standard": "8.ESS2.3", "kind": "recall", "prompt": "The lithosphere's plates move over the", "correct": "asthenosphere", "distractors": ["inner core", "outer core", "atmosphere"], "why": "The asthenosphere is a soft, slowly flowing layer of the upper mantle."}, {"id": "8.ESS2.3-r04", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Plate tectonics is the theory that", "correct": "Earth's lithosphere is broken into moving plates", "distractors": ["continents stay in fixed places on Earth", "Earth is slowly shrinking as it cools", "only the oceans move while continents stay"], "why": "Plates move a few centimeters each year."}, {"id": "8.ESS2.3-r05", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Plates usually move about", "correct": "a few centimeters per year", "distractors": ["a few kilometers per day", "a few meters per second", "not at all"], "why": "That is about as fast as fingernails grow."}, {"id": "8.ESS2.3-r06", "standard": "8.ESS2.3", "kind": "recall", "prompt": "At a divergent boundary, plates", "correct": "move apart", "distractors": ["move toward each other", "slide past each other", "do not move"], "why": "Divergent means spreading apart."}, {"id": "8.ESS2.3-r07", "standard": "8.ESS2.3", "kind": "recall", "prompt": "At a convergent boundary, plates", "correct": "move toward each other", "distractors": ["move apart", "slide past each other", "stay still"], "why": "Convergent means coming together."}, {"id": "8.ESS2.3-r08", "standard": "8.ESS2.3", "kind": "recall", "prompt": "At a transform boundary, plates", "correct": "slide past each other", "distractors": ["move apart", "move toward each other", "sink into the core"], "why": "Transform boundaries move sideways, like the San Andreas Fault."}, {"id": "8.ESS2.3-r09", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Mid-ocean ridges form at", "correct": "divergent boundaries", "distractors": ["convergent boundaries", "transform boundaries", "the centers of plates"], "why": "Magma rises where plates spread apart, building ridges."}, {"id": "8.ESS2.3-r10", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Seafloor spreading is when", "correct": "new oceanic crust forms at a ridge and moves away", "distractors": ["old crust forms at a ridge and stays there", "the ocean gets deeper as rain fills it", "continents sink into the ocean over time"], "why": "Magma rising at ridges adds new crust."}, {"id": "8.ESS2.3-r11", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Subduction happens when", "correct": "a denser oceanic plate sinks beneath another plate", "distractors": ["two plates move apart", "a less dense continental plate sinks beneath an oceanic plate", "a plate melts in place at a ridge"], "why": "Denser oceanic lithosphere sinks into the mantle."}, {"id": "8.ESS2.3-r12", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Deep ocean trenches form where", "correct": "one plate subducts beneath another", "distractors": ["plates spread apart", "plates slide past each other", "there are no plates"], "why": "Trenches mark where a plate bends down."}, {"id": "8.ESS2.3-r13", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Rocks on the seafloor are youngest", "correct": "at the mid-ocean ridge", "distractors": ["at the deepest trench", "near the continents", "in the middle of every plate equally"], "why": "New crust forms at ridges, then moves outward."}, {"id": "8.ESS2.3-r14", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Magnetic stripes on the seafloor are symmetric on both sides of a ridge. This supports", "correct": "seafloor spreading", "distractors": ["a shrinking Earth", "the ocean floor being fixed", "continents being stationary"], "why": "The same pattern forms on both sides as new crust moves away."}, {"id": "8.ESS2.3-r15", "standard": "8.ESS2.3", "kind": "recall", "prompt": "The energy that drives mantle convection comes from", "correct": "Earth's hot interior", "distractors": ["the Sun", "ocean waves", "the Moon"], "why": "Interior heat warms the bottom of the mantle."}, {"id": "8.ESS2.3-r16", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Oceanic crust compared to continental crust is", "correct": "thinner and denser", "distractors": ["thicker and less dense", "the same", "thinner and less dense"], "why": "Denser oceanic crust is why it subducts."}, {"id": "8.ESS2.3-r17", "standard": "8.ESS2.3", "kind": "recall", "prompt": "When two continental plates collide,", "correct": "tall mountain ranges form", "distractors": ["deep trenches always form", "new seafloor forms", "nothing happens"], "why": "Neither sinks easily, so crust crumples upward, as in the Himalayas."}, {"id": "8.ESS2.3-r18", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Ridge push and slab pull are forces that", "correct": "help move plates", "distractors": ["heat the mantle", "create Earth's magnetic field", "keep plates from moving"], "why": "Gravity pulls sinking slabs and pushes plates off high ridges."}, {"id": "8.ESS2.3-r19", "standard": "8.ESS2.3", "kind": "recall", "prompt": "A lava lamp is a model of convection because", "correct": "warm blobs rise, cool, and sink", "distractors": ["cool blobs rise and warm blobs sink", "the blobs move because the lamp is shaken", "the light pushes the blobs upward"], "why": "Rising and sinking from heating models mantle flow."}, {"id": "8.ESS2.3-r20", "standard": "8.ESS2.3", "kind": "recall", "prompt": "Most of the action at Earth's surface, like quakes and volcanoes, is concentrated at", "correct": "plate boundaries", "distractors": ["the centers of plates", "where the crust is thickest", "places with the most people"], "why": "Plate interactions happen at boundaries."}, {"id": "8.ESS2.3-s01", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "Rock samples near a mid-ocean ridge are 1 million years old. Samples 100 km away are 5 million years old. What does this show?", "correct": "New crust forms at the ridge and moves outward.", "distractors": ["The ridge is the oldest part of the ocean floor.", "Crust is being destroyed and recycled at the ridge.", "The ocean floor does not move at all over time."], "why": "Age increasing with distance from the ridge is evidence for spreading."}, {"id": "8.ESS2.3-s02", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "A pot of soup is heated from the bottom. Soup rises in the middle and sinks at the sides. This best models", "correct": "mantle convection that moves plates", "distractors": ["earthquakes that happen along faults", "the Moon's orbit around Earth", "ocean tides that rise and fall"], "why": "Heating from below causes circulating currents, like the mantle."}, {"id": "8.ESS2.3-s03", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "A map shows a deep trench next to a line of volcanoes on land. What is happening there?", "correct": "An oceanic plate is subducting under another plate.", "distractors": ["Two plates are moving apart.", "Two plates are sliding past each other.", "Nothing, because it is the middle of a plate."], "why": "Trench plus volcanic arc marks subduction."}, {"id": "8.ESS2.3-s04", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "The Atlantic Ocean is getting wider by about 2.5 cm per year. Which process explains this?", "correct": "seafloor spreading at the Mid-Atlantic Ridge", "distractors": ["subduction in the middle of the Atlantic", "wind pushing the water", "sea level rise"], "why": "Spreading at the ridge pushes the plates apart."}, {"id": "8.ESS2.3-s05", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "A student claims plates move because of ocean currents. Which evidence best shows that interior heat drives the motion instead?", "correct": "Heat flow is highest at ridges where hot mantle rises.", "distractors": ["Plates move fastest under the strongest ocean currents.", "Ocean currents are strongest near the coasts.", "Plates on land move faster than ocean plates."], "why": "Plate motion is linked to interior heat, not surface water."}, {"id": "8.ESS2.3-s06", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "Which pair is matched correctly?", "correct": "divergent boundary: mid-ocean ridge", "distractors": ["transform boundary: deep trench", "divergent boundary: Himalayan mountains", "convergent boundary: rift that pulls apart"], "why": "Ridges form where plates spread apart."}, {"id": "8.ESS2.3-s07", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "Earthquakes get deeper and deeper the farther you go inland from a trench. What does this pattern show?", "correct": "a plate sinking at an angle into the mantle", "distractors": ["a plate spreading apart from a ridge", "a transform fault sliding sideways", "quakes happening at random places"], "why": "Deepening quakes trace the subducting slab."}, {"id": "8.ESS2.3-s08", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "If Earth's interior cooled completely, what would happen to plate motion?", "correct": "It would slow and stop, because convection would stop.", "distractors": ["It would speed up as the planet cools down.", "It would reverse direction and move backward.", "It would not change, since plates move by themselves."], "why": "No heat means no convection to drive plates."}, {"id": "8.ESS2.3-s09", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "Two oceanic plates collide. One is older and colder. Which plate will most likely subduct?", "correct": "the older, colder, denser plate", "distractors": ["the younger, hotter plate", "neither plate", "both plates go up"], "why": "Colder, older oceanic plate is denser, so it sinks."}, {"id": "8.ESS2.3-s10", "standard": "8.ESS2.3", "kind": "scenario", "prompt": "Iceland sits on a ridge and has many volcanoes and cracks that are slowly widening. What type of boundary runs through Iceland?", "correct": "divergent", "distractors": ["convergent", "transform", "none"], "why": "Iceland is being pulled apart at the Mid-Atlantic Ridge."}, {"id": "8.ESS2.4-r01", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Mesosaurus fossils found in both South America and Africa support that these continents were", "correct": "once joined", "distractors": ["always in their current places", "connected by a land bridge that later sank", "home to Mesosaurus because it swam the ocean"], "why": "Mesosaurus lived in fresh water and could not swim across an ocean."}, {"id": "8.ESS2.4-r02", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Pangaea was", "correct": "a supercontinent made of all the major landmasses", "distractors": ["an ancient ocean that covered most of Earth", "a type of rock found on many continents", "a fossil animal found in Africa and South America"], "why": "About 300 to 200 million years ago, the continents formed one landmass."}, {"id": "8.ESS2.4-r03", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Alfred Wegener's continental drift idea was not widely accepted at first because he", "correct": "could not explain what force moved the continents", "distractors": ["had no fossil evidence to support his idea", "said that the continents had never moved", "only studied oceans and not the continents"], "why": "Plate tectonics later supplied the mechanism: mantle convection."}, {"id": "8.ESS2.4-r04", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Plate tectonics improved on continental drift by explaining", "correct": "how and why plates move", "distractors": ["why fossils are found at all", "why continents have the shapes they do", "what continents are made of"], "why": "Seafloor spreading and convection gave the mechanism."}, {"id": "8.ESS2.4-r05", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Mountains like the Himalayas form when", "correct": "two continental plates collide", "distractors": ["two plates move apart", "a plate slides sideways", "a hotspot erupts"], "why": "Colliding continents crumple and push crust up."}, {"id": "8.ESS2.4-r06", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Deep ocean trenches form at", "correct": "subduction zones", "distractors": ["mid-ocean ridges", "transform faults on land", "the centers of plates"], "why": "Trenches form where one plate bends down beneath another."}, {"id": "8.ESS2.4-r07", "standard": "8.ESS2.4", "kind": "recall", "prompt": "A fault is", "correct": "a break in rock where the rock on each side moved", "distractors": ["a type of volcano that forms along coasts", "a fossil layer found between rock layers", "the highest point at the top of a mountain"], "why": "Faults are fractures with movement."}, {"id": "8.ESS2.4-r08", "standard": "8.ESS2.4", "kind": "recall", "prompt": "The San Andreas Fault is an example of a", "correct": "transform boundary", "distractors": ["divergent boundary", "subduction zone", "hotspot"], "why": "The Pacific and North American plates slide past each other there."}, {"id": "8.ESS2.4-r09", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Matching rock layers and mountain ranges on separate continents suggest", "correct": "the continents were once connected", "distractors": ["they formed separately by coincidence", "rocks traveled across the ocean", "the ocean made the rocks"], "why": "Matching geology lines up when continents are fit together."}, {"id": "8.ESS2.4-r10", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Fossils of warm-climate plants are found in rock on an island near the Arctic today. Which explanation fits plate tectonics?", "correct": "the land was once nearer the equator and has moved", "distractors": ["plants can grow in the Arctic ice today", "the fossils were carried there by glaciers", "warm ocean currents once let those plants grow there"], "why": "Plates carry land to new latitudes over millions of years. Glaciers do not carry plant fossils from the tropics, and these plants cannot grow in Arctic cold."}, {"id": "8.ESS2.4-r11", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Glacial scratches in rocks of now-tropical Africa and India are evidence that", "correct": "these lands were once together near the South Pole", "distractors": ["glaciers form in hot deserts today", "the rocks were scratched by large animals", "the Sun was much colder in the past"], "why": "Glacial evidence lines up when continents are rejoined near the pole."}, {"id": "8.ESS2.4-r12", "standard": "8.ESS2.4", "kind": "recall", "prompt": "The shapes of South America and Africa fit together, which is", "correct": "one clue that, with fossils and rocks, supports drift", "distractors": ["proof all by itself that they were joined", "a coincidence that tells us nothing at all", "evidence that they are moving toward each other"], "why": "Shape fit alone is weak; combined evidence is strong."}, {"id": "8.ESS2.4-r13", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Plate tectonics is a gradual process, meaning features form over", "correct": "millions of years", "distractors": ["a few days", "a few years", "a single earthquake"], "why": "Plates move centimeters per year, so big features take millions of years."}, {"id": "8.ESS2.4-r14", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Oceans can open and close over geologic time because", "correct": "plates move apart and together", "distractors": ["sea level rises and falls each day", "ocean currents carve them", "rain fills them"], "why": "Divergence opens oceans; convergence and subduction close them."}, {"id": "8.ESS2.4-r15", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Rift valleys like the East African Rift form where", "correct": "a continent is being pulled apart", "distractors": ["two plates collide", "a plate subducts", "a hotspot is in the ocean"], "why": "Rifts are early divergent boundaries on land."}, {"id": "8.ESS2.4-r16", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Which landform is NOT mainly formed by plate motion?", "correct": "a sand dune", "distractors": ["a mid-ocean ridge", "an ocean trench", "a fold mountain range"], "why": "Wind forms sand dunes."}, {"id": "8.ESS2.4-r17", "standard": "8.ESS2.4", "kind": "recall", "prompt": "Volcanoes are commonly found", "correct": "at subduction zones, ridges, and hotspots", "distractors": ["evenly spread everywhere on Earth", "only at transform faults like the San Andreas", "only near the equator where it is hot"], "why": "Magma reaches the surface where plates spread, subduct, or sit over hotspots."}, {"id": "8.ESS2.4-r18", "standard": "8.ESS2.4", "kind": "recall", "prompt": "The Andes Mountains formed mainly by", "correct": "an oceanic plate subducting under South America", "distractors": ["two continents colliding with each other", "a hotspot under the middle of the plate", "a transform fault sliding sideways"], "why": "Subduction caused uplift and volcanoes along the coast."}, {"id": "8.ESS2.4-r19", "standard": "8.ESS2.4", "kind": "recall", "prompt": "If plates did not move, matching fossils on continents separated by oceans would be", "correct": "very hard to explain", "distractors": ["easier to explain", "expected", "explained by animals swimming between continents"], "why": "Plate motion explains how one population became split."}, {"id": "8.ESS2.4-r20", "standard": "8.ESS2.4", "kind": "recall", "prompt": "The best explanation of the distribution of fossils, rocks, and landforms uses", "correct": "fossil, rock, landform, and seafloor data", "distractors": ["only the fit of the two coastlines", "only the fossils of a single species", "only the ranges of modern animals"], "why": "A strong explanation connects several kinds of data."}, {"id": "8.ESS2.4-s01", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "Fossils of Glossopteris, a seed fern, are found in South America, Africa, India, Antarctica, and Australia. Its seeds were too heavy to blow across oceans. What is the best explanation?", "correct": "The continents were joined, so the plant spread across them.", "distractors": ["Birds carried the heavy seeds across the ocean.", "The plants evolved separately on each continent.", "Ocean currents moved the seeds between continents."], "why": "One connected landmass explains the fossil spread."}, {"id": "8.ESS2.4-s02", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "Mesosaurus fossils appear in South America and Africa, and the coasts fit like puzzle pieces. Which explanation is best?", "correct": "The continents were joined and slowly moved apart.", "distractors": ["Mesosaurus swam across the Atlantic Ocean.", "Fossils were planted on both continents by people.", "Mesosaurus lived everywhere on Earth at that time."], "why": "Multiple clues point to past connection."}, {"id": "8.ESS2.4-s03", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "A map shows a mountain range in eastern North America that lines up with mountains in Scotland and Norway when the Atlantic is closed. What does this support?", "correct": "The ranges formed together and split when the Atlantic opened.", "distractors": ["They formed at different times, and the match is chance.", "Mountains can slowly move across oceans on their own.", "Scotland was always attached to North America."], "why": "Matching ranges indicate a shared origin."}, {"id": "8.ESS2.4-s04", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "Marine fossils such as shells are found high in the Himalayas. Which explanation fits plate tectonics?", "correct": "Seafloor rock was pushed up when India hit Asia.", "distractors": ["Sea level was once higher than Mount Everest.", "Birds dropped the shells high on the mountains.", "The shells grew on the mountain over time."], "why": "Collision uplifted ancient seafloor."}, {"id": "8.ESS2.4-s05", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "A student says the continents moved quickly, like boats in a storm. What evidence shows motion is gradual?", "correct": "GPS shows plates moving a few centimeters per year.", "distractors": ["Earthquakes happen suddenly, in a few seconds.", "Continents are very large and very heavy.", "Continents are made of light rock that floats fast."], "why": "Measured rates are slow, so big changes take millions of years."}, {"id": "8.ESS2.4-s06", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "The Red Sea is slowly widening between Africa and Arabia. In millions of years, what will most likely happen?", "correct": "It may become a wider ocean as the plates keep spreading.", "distractors": ["It will close and form tall mountains next year.", "It will dry up and turn into a desert soon.", "Nothing will change, because plates have stopped."], "why": "Continuing divergence widens the sea."}, {"id": "8.ESS2.4-s07", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "Coal, which forms in warm swamps, is found under ice in Antarctica. What two explanations should a scientist consider?", "correct": "Antarctica moved from a warmer latitude, and climate changed.", "distractors": ["Coal forms in cold, icy places like Antarctica.", "Ocean currents carried the coal from the tropics.", "Coal formed there recently from frozen plants."], "why": "Plate motion and climate change can both explain it."}, {"id": "8.ESS2.4-s08", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "Map A shows earthquakes; Map B shows volcanoes; Map C shows mountain ranges. Many of the features line up in the same bands. What do the bands mostly outline?", "correct": "plate boundaries", "distractors": ["the equator", "country borders", "areas with the most rain"], "why": "Features cluster where plates interact."}, {"id": "8.ESS2.4-s09", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "Which set of evidence is MOST convincing that two continents were once joined?", "correct": "matching fossils, rocks, and glacial scratches", "distractors": ["only the shapes of the two facing coastlines", "only the fossils of one species", "only modern animals that look alike"], "why": "Several independent lines of evidence are stronger together."}, {"id": "8.ESS2.4-s10", "standard": "8.ESS2.4", "kind": "scenario", "prompt": "A transform fault offsets a stream so its two halves are now 100 m apart. If the fault moves 2 cm per year, about how long did this take?", "correct": "about 5,000 years", "distractors": ["about 50 years", "about 5 years", "about 5 million years"], "why": "100 m = 10,000 cm; 10,000 ÷ 2 = 5,000 years."}, {"id": "8.ESS3.1-r01", "standard": "8.ESS3.1", "kind": "recall", "prompt": "Most earthquakes happen near", "correct": "plate boundaries", "distractors": ["the middles of plates", "the centers of continents", "places with the most people"], "why": "Plates interact at boundaries, building stress that is released as quakes."}, {"id": "8.ESS3.1-r02", "standard": "8.ESS3.1", "kind": "recall", "prompt": "Most volcanoes are found", "correct": "at plate boundaries or over hotspots", "distractors": ["evenly spread across all land", "only in hot deserts", "only near the equator"], "why": "Magma reaches the surface where plates spread, subduct, or sit over hotspots."}, {"id": "8.ESS3.1-r03", "standard": "8.ESS3.1", "kind": "recall", "prompt": "A hotspot volcano like Hawaii forms", "correct": "over a plume of hot mantle, far from a plate boundary", "distractors": ["at a transform boundary where plates slide", "where two continental plates collide", "only at mid-ocean ridges where plates spread"], "why": "Hawaii sits in the Pacific plate, far from any plate boundary, above a plume of hot mantle. It is not at a transform or collision boundary."}, {"id": "8.ESS3.1-r04", "standard": "8.ESS3.1", "kind": "recall", "prompt": "The Ring of Fire is", "correct": "a belt of earthquakes and volcanoes around the Pacific Ocean", "distractors": ["a ring of hotspots in the middle of the Pacific plate", "a mid-ocean ridge in the Atlantic", "a belt of volcanoes around the Atlantic Ocean"], "why": "Subduction zones surround much of the Pacific."}, {"id": "8.ESS3.1-r05", "standard": "8.ESS3.1", "kind": "recall", "prompt": "A forecast of natural hazards gives", "correct": "the likelihood an event will happen in an area over time", "distractors": ["the exact day and minute of the next earthquake", "a guarantee that nothing will happen there", "the cause of every earthquake in an area"], "why": "Scientists forecast probabilities, not exact predictions."}, {"id": "8.ESS3.1-r06", "standard": "8.ESS3.1", "kind": "recall", "prompt": "Scientists can forecast where earthquakes are likely by", "correct": "mapping where earthquakes have happened before", "distractors": ["counting the clouds over an area", "checking animal behavior and nothing else", "looking at the phases of the Moon"], "why": "Past patterns show where stress builds."}, {"id": "8.ESS3.1-r07", "standard": "8.ESS3.1", "kind": "recall", "prompt": "A transform boundary usually has", "correct": "earthquakes but few volcanoes", "distractors": ["many volcanoes and no earthquakes", "no hazards", "only tsunamis"], "why": "Sliding plates cause quakes but do not create much magma."}, {"id": "8.ESS3.1-r08", "standard": "8.ESS3.1", "kind": "recall", "prompt": "Subduction zones can produce", "correct": "strong earthquakes, volcanoes, and tsunamis", "distractors": ["only small earthquakes that cause no damage", "no hazards, because plates move slowly", "only mountains, with no earthquakes"], "why": "Subduction zones have the largest quakes and explosive volcanoes."}, {"id": "8.ESS3.1-r09", "standard": "8.ESS3.1", "kind": "recall", "prompt": "A chain of volcanic islands that gets older in one direction shows", "correct": "a plate moving over a hotspot", "distractors": ["the hotspot moving quickly", "islands floating", "random eruptions"], "why": "The plate carries older volcanoes away from the plume."}, {"id": "8.ESS3.1-r10", "standard": "8.ESS3.1", "kind": "recall", "prompt": "Volcano monitoring includes measuring", "correct": "gas, ground swelling, and small earthquakes", "distractors": ["ocean temperature far from the volcano", "the color of old cooled lava", "wind speed at the top of the volcano"], "why": "These signs can show magma moving and allow warnings."}, {"id": "8.ESS3.1-r11", "standard": "8.ESS3.1", "kind": "recall", "prompt": "A seismograph network helps scientists", "correct": "detect and locate earthquakes", "distractors": ["stop earthquakes", "move plates", "cause small quakes to release stress"], "why": "Many stations together pinpoint where a quake happened."}, {"id": "8.ESS3.1-r12", "standard": "8.ESS3.1", "kind": "recall", "prompt": "A tsunami is most often caused by", "correct": "an undersea earthquake that moves the seafloor", "distractors": ["strong wind blowing over the ocean", "the Moon's gravity pulling on the water", "a hurricane moving onto the coast"], "why": "Sudden seafloor movement pushes huge volumes of water."}, {"id": "8.ESS3.1-r13", "standard": "8.ESS3.1", "kind": "recall", "prompt": "The New Madrid Seismic Zone near Memphis is unusual because it is", "correct": "far from any plate boundary", "distractors": ["at the boundary of two plates", "at a mid-ocean ridge", "a hotspot volcano"], "why": "Most quakes happen at plate boundaries, but some, like New Madrid near Memphis, happen far from any plate boundary."}, {"id": "8.ESS3.1-r14", "standard": "8.ESS3.1", "kind": "recall", "prompt": "\"No big earthquake has hit here in 100 years, so one never will.\" What is wrong with this?", "correct": "Long quiet periods happen between big quakes, so risk remains.", "distractors": ["Nothing, because big quakes never return to a place.", "Earthquakes happen every single year everywhere.", "Only volcanoes are dangerous in quiet places."], "why": "Some faults go centuries between big quakes."}, {"id": "8.ESS3.1-r15", "standard": "8.ESS3.1", "kind": "recall", "prompt": "Forecasts help people", "correct": "plan, build safer buildings, and prepare", "distractors": ["prevent all earthquakes", "know the exact date of the next quake", "stop volcanoes"], "why": "Knowing the risk reduces harm."}, {"id": "8.ESS3.1-r16", "standard": "8.ESS3.1", "kind": "recall", "prompt": "Earthquakes at mid-ocean ridges are usually", "correct": "shallow", "distractors": ["deeper than any other quakes", "very rare", "always the strongest"], "why": "Thin, hot crust at ridges breaks near the surface."}, {"id": "8.ESS3.1-r17", "standard": "8.ESS3.1", "kind": "recall", "prompt": "The deepest earthquakes happen", "correct": "in subducting plates", "distractors": ["at mid-ocean ridges", "at hotspots", "in the middle of continents"], "why": "Sinking slabs carry quakes down to about 700 km."}, {"id": "8.ESS3.1-r18", "standard": "8.ESS3.1", "kind": "recall", "prompt": "A map where earthquake dots form long, narrow bands across Earth is", "correct": "pattern evidence that quakes cluster at plate boundaries", "distractors": ["evidence that earthquakes happen only on land", "proof that the plates there do not move at all", "evidence that quakes are spread evenly everywhere"], "why": "Patterns in mapped data support the claim."}, {"id": "8.ESS3.1-r19", "standard": "8.ESS3.1", "kind": "recall", "prompt": "A building code that requires stronger buildings in high-risk areas is an example of", "correct": "using hazard forecasts to reduce harm", "distractors": ["predicting the exact time of a quake", "preventing earthquakes", "moving plates"], "why": "Forecasts guide decisions that protect people."}, {"id": "8.ESS3.1-r20", "standard": "8.ESS3.1", "kind": "recall", "prompt": "Which place would have the HIGHEST earthquake risk?", "correct": "a city next to a subduction zone", "distractors": ["a city in the middle of a quiet plate far from any boundary", "a city on a stable continental interior with no faults", "a city far inland with no history of quakes"], "why": "Subduction zones have frequent and powerful earthquakes."}, {"id": "8.ESS3.1-s01", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "A map shows most of a country's earthquakes along a curved ocean trench. Where is a future quake more likely?", "correct": "near the trench, where plates interact", "distractors": ["in the middle of the plate, far from the trench", "farther inland, where no quakes have been recorded", "anywhere, with no pattern"], "why": "Past patterns at the plate boundary suggest future risk there."}, {"id": "8.ESS3.1-s02", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "Island A is 5 million years old, island B is 3 million, and island C is 1 million and still has active volcanoes. Where is the hotspot most likely now?", "correct": "near island C", "distractors": ["under island A", "under island B", "between A and B"], "why": "The youngest, active island sits over the hotspot."}, {"id": "8.ESS3.1-s03", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "A volcano starts swelling, releasing more gas, and having many small quakes. What should scientists do?", "correct": "Issue a warning, because magma may be rising.", "distractors": ["Ignore it, because volcanoes are unpredictable.", "Announce the exact minute of the eruption.", "Assume the volcano is going dormant now."], "why": "These signals often come before eruptions."}, {"id": "8.ESS3.1-s04", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "USGS data show 300 small quakes in the past 10 years in a region, with most along one fault line. A family is choosing where to build. Which advice is best?", "correct": "Build farther from the fault and use earthquake-resistant design.", "distractors": ["Build right on the fault since quakes already happened.", "Risk is the same everywhere.", "Quakes there are impossible now."], "why": "Distance from active faults and good design lower risk."}, {"id": "8.ESS3.1-s05", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "Region X had 5 magnitude-6 quakes in 50 years. Region Y had 1 in 50 years. Which forecast is best?", "correct": "Region X is more likely to have one in the next 50 years.", "distractors": ["Region Y will definitely have a quake next year.", "Region X will have a quake on a certain date.", "Both regions have exactly the same risk."], "why": "Frequency of past events helps estimate likelihood."}, {"id": "8.ESS3.1-s06", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "A classmate says, \"Scientists can predict the exact day of the next New Madrid quake.\" How should you respond?", "correct": "Scientists give probabilities, not exact dates.", "distractors": ["Yes, they announce the date every year.", "No, because no one studies New Madrid.", "No, because quakes can't happen near Memphis."], "why": "Earthquake science forecasts likelihood, not exact timing."}, {"id": "8.ESS3.1-s07", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "A strong quake happens under the ocean near a coast. Which hazard should coastal towns prepare for in the next hour?", "correct": "a tsunami", "distractors": ["a volcanic eruption on the coast", "a drought", "a blizzard"], "why": "Undersea quakes can move the seafloor and create tsunamis."}, {"id": "8.ESS3.1-s08", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "Along the San Andreas Fault, there are many earthquakes but no chain of volcanoes. Why?", "correct": "It is a transform boundary, so little magma forms.", "distractors": ["It is a subduction zone with no volcanoes.", "It is a hotspot that has gone quiet.", "The earthquake data must be wrong."], "why": "Transform boundaries make quakes but little magma."}, {"id": "8.ESS3.1-s09", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "Two cities are equally close to a fault. City A has older brick buildings; City B uses earthquake-resistant designs. Which statement is true?", "correct": "City A has higher risk of damage from a similar hazard.", "distractors": ["City B will have more earthquakes than City A.", "Both cities have the same risk of damage.", "City A has no risk because quakes are rare."], "why": "Risk depends on both the hazard and how prepared a place is."}, {"id": "8.ESS3.1-s10", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "A student maps 100 recent quakes and finds 92 near plate boundaries and 8 far from any plate boundary, like New Madrid. What is the best conclusion?", "correct": "Most quakes happen at plate boundaries, but some don't.", "distractors": ["All earthquakes happen at plate boundaries.", "Earthquakes happen at random, with no pattern.", "Most quakes happen far from any plate boundary."], "why": "The data show a strong pattern with some exceptions."}, {"id": "8.ESS3.1-s11", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "A town on a subduction zone wants to reduce harm from future hazards. Which plan uses the forecast best?", "correct": "Build escape routes, strengthen buildings, and hold drills.", "distractors": ["Wait until scientists give an exact date for the quake.", "Do nothing, because big quakes there are rare.", "Build only on the beach so people can see a tsunami."], "why": "Forecasts help communities prepare in advance."}, {"id": "8.ESS3.1-s12", "standard": "8.ESS3.1", "kind": "scenario", "prompt": "Over 30 years, three volcanoes show these eruptions: V1 erupted 12 times, V2 erupted 1 time, V3 erupted 0 times but sits over an active hotspot. Which statement is the best forecast?", "correct": "V1 is most likely to erupt, but V3 should be monitored.", "distractors": ["V3 can never erupt because it has been quiet.", "V2 is most likely to erupt in the next year.", "All three are equally likely to erupt soon."], "why": "Past activity shows likelihood, but hotspots stay a risk."}, {"id": "8.ETS1.1-r01", "standard": "8.ETS1.1", "kind": "recall", "prompt": "In engineering, criteria are", "correct": "the goals a design must meet", "distractors": ["the limits on a design", "the materials used", "the final product"], "why": "Criteria say what success looks like. Constraints are the limits, like cost or size."}, {"id": "8.ETS1.1-r02", "standard": "8.ETS1.1", "kind": "recall", "prompt": "In engineering, constraints are", "correct": "limits such as cost, time, or materials", "distractors": ["the goals that a design must meet", "the results from testing the design", "the people who will use the design"], "why": "Constraints restrict what the solution can be."}, {"id": "8.ETS1.1-r03", "standard": "8.ETS1.1", "kind": "recall", "prompt": "A team must build an electromagnet that lifts 10 paper clips. The \"lift 10 clips\" goal is a", "correct": "criterion", "distractors": ["constraint", "variable", "hypothesis"], "why": "It describes what the design must achieve."}, {"id": "8.ETS1.1-r04", "standard": "8.ETS1.1", "kind": "recall", "prompt": "The team may only use one 1.5-volt battery. This is a", "correct": "constraint", "distractors": ["criterion", "result", "conclusion"], "why": "It limits the design rather than stating a goal."}, {"id": "8.ETS1.1-r05", "standard": "8.ETS1.1", "kind": "recall", "prompt": "Engineers test a prototype to", "correct": "see whether it meets the criteria", "distractors": ["avoid needing to collect any data", "prove that it is already perfect", "skip the step of improving it"], "why": "Testing shows whether the design works and what to improve."}, {"id": "8.ETS1.1-r06", "standard": "8.ETS1.1", "kind": "recall", "prompt": "In a fair test of electromagnets, you should change", "correct": "only one variable at a time", "distractors": ["all the variables at once", "nothing at all", "the way you measure each time"], "why": "Changing one variable shows its effect."}, {"id": "8.ETS1.1-r07", "standard": "8.ETS1.1", "kind": "recall", "prompt": "A team tests coil turns and holds current and core the same. Coil turns is the", "correct": "independent variable", "distractors": ["dependent variable", "controlled variable", "constraint"], "why": "The variable you change on purpose is independent."}, {"id": "8.ETS1.1-r08", "standard": "8.ETS1.1", "kind": "recall", "prompt": "In that test, the number of paper clips lifted is the", "correct": "dependent variable", "distractors": ["independent variable", "controlled variable", "criterion"], "why": "It's what you measure in response."}, {"id": "8.ETS1.1-r09", "standard": "8.ETS1.1", "kind": "recall", "prompt": "Keeping the battery and nail the same in every trial makes them", "correct": "controlled variables", "distractors": ["independent variables", "dependent variables", "criteria"], "why": "Controls keep the test fair."}, {"id": "8.ETS1.1-r10", "standard": "8.ETS1.1", "kind": "recall", "prompt": "Why should engineers run several trials of each design?", "correct": "to make results more reliable", "distractors": ["to get a different answer each time", "to waste fewer materials", "to use up the battery faster"], "why": "Repeated trials reduce the effect of errors."}, {"id": "8.ETS1.1-r11", "standard": "8.ETS1.1", "kind": "recall", "prompt": "A design that lifts the most clips but uses too much battery power", "correct": "may fail a constraint", "distractors": ["always wins", "meets every criterion", "is a controlled variable"], "why": "A good design must meet criteria within constraints."}, {"id": "8.ETS1.1-r12", "standard": "8.ETS1.1", "kind": "recall", "prompt": "Iterating a design means", "correct": "testing, improving, and testing again", "distractors": ["giving up after one test", "keeping the first idea no matter what", "changing all variables at once"], "why": "Engineering is a cycle of test and improve."}, {"id": "8.ETS1.1-r13", "standard": "8.ETS1.1", "kind": "recall", "prompt": "A trade-off in design is", "correct": "giving up one benefit to gain another", "distractors": ["a test with no results", "a constraint that doesn't matter", "always choosing the cheapest option"], "why": "For example, more coils add strength but also add weight and cost."}, {"id": "8.ETS1.1-r14", "standard": "8.ETS1.1", "kind": "recall", "prompt": "A model in engineering is useful because it", "correct": "lets you test ideas before the final build", "distractors": ["is always the same as the final product", "never needs to be tested or checked", "cannot be changed once it is built"], "why": "Models and prototypes help find problems early."}, {"id": "8.ETS1.1-r15", "standard": "8.ETS1.1", "kind": "recall", "prompt": "To compare two electromagnet designs, the best data to collect is", "correct": "clips lifted by each, over several trials", "distractors": ["the color and thickness of the wire", "which design looks nicer to the team", "the time of day each test was done"], "why": "Measurable data related to the criteria."}, {"id": "8.ETS1.1-r16", "standard": "8.ETS1.1", "kind": "recall", "prompt": "A design meets all criteria but goes over the budget. The best next step is", "correct": "revise the design to reduce cost", "distractors": ["ignore the budget, since it works", "stop the project and start over", "add more materials to make it stronger"], "why": "Constraints still matter, so the design must be improved."}, {"id": "8.ETS1.1-r17", "standard": "8.ETS1.1", "kind": "recall", "prompt": "Which is a criterion for an electromagnet crane?", "correct": "It can lift a 1 kg load", "distractors": ["It must cost under $20", "It must fit in a 10 cm box", "It must use only one battery"], "why": "Lifting a load is a performance goal. The others are limits (constraints)."}, {"id": "8.ETS1.1-r18", "standard": "8.ETS1.1", "kind": "recall", "prompt": "Which is a constraint for an electromagnet crane?", "correct": "It must cost under $20", "distractors": ["It lifts a 1 kg load", "It drops the load when switched off", "It holds the load for 30 seconds"], "why": "Cost is a limit. The others describe performance goals."}, {"id": "8.ETS1.1-r19", "standard": "8.ETS1.1", "kind": "recall", "prompt": "An engineer's data table shows Design A lifted 8, 9, 8 clips and Design B lifted 12, 3, 11. Which design is more consistent?", "correct": "Design A", "distractors": ["Design B", "Both are equally consistent", "Neither, since both averages are close"], "why": "A's results are close together; B's vary a lot."}, {"id": "8.ETS1.1-r20", "standard": "8.ETS1.1", "kind": "recall", "prompt": "The best way to decide which design is best is to", "correct": "compare test data with the criteria and constraints", "distractors": ["pick the first idea the team came up with", "choose the design with the most parts", "vote on a favorite without testing"], "why": "Evidence from tests, measured against the goals and limits."}, {"id": "8.ETS1.1-s01", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "Team A's electromagnet lifts 15 clips using 4 batteries. Team B's lifts 12 clips using 1 battery. The limit is 2 batteries, and the goal is 10 clips. Which design meets both?", "correct": "Team B", "distractors": ["Team A", "Both teams", "Neither team"], "why": "B meets the goal (12 ≥ 10) and the limit (1 ≤ 2). A breaks the battery constraint."}, {"id": "8.ETS1.1-s02", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "A student changes the number of coils AND the battery at the same time and lifts more clips. What is the problem with this test?", "correct": "You can't tell which change caused the result.", "distractors": ["Too few paper clips were used in the test.", "The battery was too strong for the coil.", "There is no problem with how it was tested."], "why": "Changing two variables at once makes the cause unclear."}, {"id": "8.ETS1.1-s03", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "Data: 10 coils = 4 clips, 20 coils = 8 clips, 30 coils = 12 clips (same battery and nail). What would 40 coils most likely lift?", "correct": "about 16 clips", "distractors": ["about 12 clips", "about 4 clips", "about 40 clips"], "why": "The pattern adds about 4 clips per 10 coils."}, {"id": "8.ETS1.1-s04", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "An electromagnet design lifts 20 clips but gets too hot to touch after 1 minute. A criterion is \"safe to hold.\" What should the team do?", "correct": "Revise the design to reduce heat, then retest.", "distractors": ["Keep it because it lifts the most clips.", "Remove the safety criterion.", "Stop testing completely."], "why": "A design must meet all criteria. Iterate to fix the problem."}, {"id": "8.ETS1.1-s05", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "Two designs lift the same number of clips. Design X costs $3; Design Y costs $9. The budget is $10. Which is the better choice and why?", "correct": "X, it meets the goal at lower cost.", "distractors": ["Y, it costs more so it's better.", "Y, it is closer to the budget limit.", "Neither, they're equal in every way."], "why": "Both meet criteria and constraints, but X does it more efficiently."}, {"id": "8.ETS1.1-s06", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "A team's electromagnet lifted 5, 6, and 14 clips in three trials. What should they do with the 14?", "correct": "Check for an error and repeat the trial.", "distractors": ["Use only the 14 as the result.", "Ignore the 5 and 6.", "Report 14 as the average."], "why": "An outlier may mean a mistake, so investigate and retest."}, {"id": "8.ETS1.1-s07", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "A crane magnet must drop its load on command. Which design meets this criterion best?", "correct": "an electromagnet with a switch", "distractors": ["a strong permanent magnet", "a magnet glued to the load", "a magnet with no current control"], "why": "Turning off the current turns off the field and drops the load."}, {"id": "8.ETS1.1-s08", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "A team must build a crane magnet that fits in a 5 cm tube. Their best design is 7 cm long. What should they do?", "correct": "Redesign to fit the size limit, then retest.", "distractors": ["Ignore the size limit, since it works well.", "Make the tube bigger so the design fits.", "Give up on the project and start over."], "why": "Constraints must be met. Revise and test again."}, {"id": "8.ETS1.1-s09", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "A student claims, \"Adding an iron core always makes a better design.\" Which test would check this claim fairly?", "correct": "Test with and without a core, same coils and battery.", "distractors": ["Test with a core and more coils at the same time.", "Test without a core and with a new battery.", "Test only once with the core and compare."], "why": "Only change the core to see its effect."}, {"id": "8.ETS1.1-s10", "standard": "8.ETS1.1", "kind": "scenario", "prompt": "After testing, Design 1 meets all criteria but is heavy. Design 2 is light but lifts fewer clips than required. Which is the best decision?", "correct": "Choose Design 1 or improve it to reduce weight.", "distractors": ["Choose Design 2 because it is lighter.", "Mix both without testing.", "Choose neither and stop."], "why": "Design 2 fails a criterion. Design 1 works and can be improved."}, {"id": "8.ETS2.1-r01", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Telescopes helped scientists discover", "correct": "moons and objects too far away to see with eyes alone", "distractors": ["the solid inner core at the center of Earth", "the tiny structure inside of atoms", "the shape of DNA inside living cells"], "why": "Telescopes extend our vision to distant objects in space."}, {"id": "8.ETS2.1-r02", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Seismographs help scientists learn about", "correct": "Earth's interior layers", "distractors": ["distant galaxies", "the Moon's craters", "the ocean's tides"], "why": "Seismic data show how waves travel through Earth's layers."}, {"id": "8.ETS2.1-r03", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Space probes like Voyager have", "correct": "gathered data from places humans can't reach", "distractors": ["replaced the need for all telescopes", "been used to study Earth's inner core", "only taken photos of Earth's Moon"], "why": "Probes travel to other planets and send back data."}, {"id": "8.ETS2.1-r04", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Science and technology are related because", "correct": "new tools lead to discoveries and better tools", "distractors": ["they are not connected to each other at all", "technology only comes from art and design", "science never uses tools to collect data"], "why": "They drive each other forward."}, {"id": "8.ETS2.1-r05", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Before the telescope, people could not see", "correct": "Jupiter's moons", "distractors": ["the Moon", "the Sun", "bright stars"], "why": "Galileo used a telescope to discover Jupiter's moons in 1610."}, {"id": "8.ETS2.1-r06", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Satellite images help scientists", "correct": "track weather, ice, and land changes", "distractors": ["study the inner core directly", "count atoms in rocks", "hear sounds in space"], "why": "Satellites observe Earth from above."}, {"id": "8.ETS2.1-r07", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Improvements in telescope mirrors and lenses led to", "correct": "clearer, more detailed views of space", "distractors": ["planets that look smaller than before", "the end of astronomy as a science", "less data about objects in space"], "why": "Better tools gave better data."}, {"id": "8.ETS2.1-r08", "standard": "8.ETS2.1", "kind": "recall", "prompt": "The Hubble Space Telescope sees more clearly than ground telescopes because", "correct": "it is above Earth's blurring atmosphere", "distractors": ["it is closer to the stars", "it uses sound", "it is larger than every ground telescope"], "why": "Earth's air distorts light. Hubble avoids that."}, {"id": "8.ETS2.1-r09", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Why do scientists send rovers to Mars?", "correct": "To collect data about its surface and rocks", "distractors": ["To look for oil to bring back to Earth", "To study the oceans on Earth from far away", "To build a city where people can live"], "why": "Rovers analyze soil, rocks, and conditions on Mars."}, {"id": "8.ETS2.1-r10", "standard": "8.ETS2.1", "kind": "recall", "prompt": "GPS satellites have helped geologists", "correct": "measure how fast plates move", "distractors": ["predict the exact date of earthquakes", "measure the depth of the outer core", "find dinosaur bones directly"], "why": "GPS can detect plate movements of a few centimeters per year."}, {"id": "8.ETS2.1-r11", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Radio telescopes detect", "correct": "radio waves from objects in space", "distractors": ["sound waves traveling through space", "only the visible light we can see", "earthquakes that happen on Earth"], "why": "Many objects give off radio waves that our eyes can't see."}, {"id": "8.ETS2.1-r12", "standard": "8.ETS2.1", "kind": "recall", "prompt": "New technology often leads to", "correct": "new questions and discoveries in science", "distractors": ["the end of all science questions", "less information about the world", "fewer experiments for scientists"], "why": "Each new tool reveals things we didn't know, leading to more questions."}, {"id": "8.ETS2.1-r13", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Sonar on ships helped scientists map", "correct": "the ocean floor and its ridges", "distractors": ["the planets in our solar system", "the surface of the Moon", "the inner core of Earth"], "why": "Sound pulses echo off the seafloor, revealing its shape."}, {"id": "8.ETS2.1-r14", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Spectroscopes split light into colors and helped scientists learn", "correct": "what stars are made of", "distractors": ["how deep the ocean is", "the age of fossils", "the speed of plates"], "why": "Spectra show which elements are in stars."}, {"id": "8.ETS2.1-r15", "standard": "8.ETS2.1", "kind": "recall", "prompt": "A network of seismographs around the world allows scientists to", "correct": "locate where earthquakes happen", "distractors": ["stop earthquakes", "predict the exact time of quakes", "measure the temperature of space"], "why": "Combining data from many stations pinpoints quake locations."}, {"id": "8.ETS2.1-r16", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Which discovery depended on a new technology?", "correct": "seafloor spreading, found using sonar", "distractors": ["that rocks form in layers, seen in cliffs", "that fossils show past life, seen by digging", "that the Moon has phases, seen by eye"], "why": "Sonar mapped the ridges, and towed magnetometers found the seafloor's magnetic stripes. Rock layers, fossils, and Moon phases were found by plain observation, without new tools."}, {"id": "8.ETS2.1-r17", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Science helps improve technology when", "correct": "new knowledge is used to design better tools", "distractors": ["tools are never changed or improved", "scientists stop asking new questions", "no one shares data with others"], "why": "Understanding light, for example, led to better lenses."}, {"id": "8.ETS2.1-r18", "standard": "8.ETS2.1", "kind": "recall", "prompt": "The James Webb Space Telescope detects mostly infrared light. This helps it", "correct": "see very distant galaxies and through dust", "distractors": ["see only the nearby planets clearly", "hear sounds from distant stars", "study Earth's inner core"], "why": "Infrared passes through dust, and light from far galaxies is stretched into infrared."}, {"id": "8.ETS2.1-r19", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Ice cores drilled from glaciers give scientists data about", "correct": "past climates", "distractors": ["distant galaxies", "Earth's inner core", "the Moon's surface"], "why": "Air bubbles in ice record past atmosphere and temperature."}, {"id": "8.ETS2.1-r20", "standard": "8.ETS2.1", "kind": "recall", "prompt": "Why are many types of telescopes used instead of just one?", "correct": "Each type detects different kinds of light", "distractors": ["Only one type of telescope works well", "They all detect sound from space", "They all see exactly the same things"], "why": "Radio, infrared, visible, and X-ray telescopes reveal different information."}, {"id": "8.ETS2.1-s01", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "Galileo pointed a telescope at Jupiter and saw four moons orbiting it. Why was this important?", "correct": "It showed not everything orbits Earth.", "distractors": ["It proved the Moon is made of rock.", "It showed Earth has four moons.", "It discovered Earth's layers."], "why": "New technology gave evidence that changed ideas about the solar system."}, {"id": "8.ETS2.1-s02", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "Before sonar, maps of the ocean floor were mostly guesses. After sonar, scientists found long underwater mountain ranges. What does this show?", "correct": "New tools can lead to new discoveries.", "distractors": ["Sonar created the mountain ranges.", "The ocean floor is flat.", "Maps don't need tools."], "why": "Better technology led to seeing features that were always there."}, {"id": "8.ETS2.1-s03", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "A seismograph network records an earthquake in Japan. Scientists in the U.S. study the waves. What can they learn?", "correct": "about Earth's interior, from the waves' paths", "distractors": ["the exact time the next quake will hit Japan", "the temperature of the air in Japan", "the age of the rocks at the epicenter"], "why": "Waves passing through Earth carry information about its layers."}, {"id": "8.ETS2.1-s04", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "A telescope on a mountain gives blurry images. Engineers build one in space instead. What problem does this solve?", "correct": "Earth's atmosphere blurring the light", "distractors": ["telescopes being too heavy to build", "stars being too close to see well", "the need to collect any data"], "why": "Space telescopes avoid atmospheric distortion."}, {"id": "8.ETS2.1-s05", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "Scientists studying light from stars developed better cameras, which then found new planets. What does this cycle show?", "correct": "Science and technology improve each other.", "distractors": ["Technology does not depend on science.", "Science does not need tools.", "Planets can't be found with tools."], "why": "Knowledge leads to tools, and tools lead to new knowledge."}, {"id": "8.ETS2.1-s06", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "A rover on Mars finds rocks that formed in water. Without the rover, scientists would have to", "correct": "rely on less detailed data from far away", "distractors": ["move to Mars to look at the rocks", "guess with no evidence at all", "use a seismograph on Earth instead"], "why": "Probes and rovers collect data that can't be gathered from Earth."}, {"id": "8.ETS2.1-s07", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "GPS shows a station in Iceland moving 2 cm farther from a station in Greenland each year. What does this data support?", "correct": "The plates are spreading apart at the ridge.", "distractors": ["The plates there are not moving at all.", "GPS is broken in very cold places.", "Iceland is shrinking as it cools down."], "why": "Precise technology measures slow plate motions."}, {"id": "8.ETS2.1-s08", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "Weather satellites track a hurricane days before it reaches land. How does this technology help people?", "correct": "They can plan and evacuate in time.", "distractors": ["It stops the hurricane.", "It changes the hurricane's path.", "It lets the hurricane skip the coast."], "why": "Better data lets people prepare."}, {"id": "8.ETS2.1-s09", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "A student says, \"Technology just makes life easier; it doesn't help science.\" Which example disproves this?", "correct": "The telescope led to finding Jupiter's moons.", "distractors": ["A phone can send text messages quickly.", "A car moves people faster than walking.", "A microwave heats food in a few minutes."], "why": "The telescope shows technology directly enabling scientific discovery."}, {"id": "8.ETS2.1-s10", "standard": "8.ETS2.1", "kind": "scenario", "prompt": "Scientists discovered that seismic S-waves don't pass through the outer core. What technology made this discovery possible?", "correct": "a worldwide network of seismographs", "distractors": ["telescopes orbiting in space", "the microscope used in labs", "radio broadcasts around the world"], "why": "Seismographs in many places recorded where S-waves were missing."}, {"id": "8.LS4.1-r01", "standard": "8.LS4.1", "kind": "recall", "prompt": "The fossil record is", "correct": "all fossils and what they show about past life", "distractors": ["a list of the animals living today", "a map of today's habitats and biomes", "a record of human history only"], "why": "Fossils documented together show what lived, when, and how life changed."}, {"id": "8.LS4.1-r02", "standard": "8.LS4.1", "kind": "recall", "prompt": "In undisturbed rock layers, the oldest fossils are usually", "correct": "in the bottom layers", "distractors": ["in the top layers", "in the middle layers", "spread evenly everywhere"], "why": "Layers build up over time, so deeper layers are older."}, {"id": "8.LS4.1-r03", "standard": "8.LS4.1", "kind": "recall", "prompt": "Fossils show that many species that once lived are now", "correct": "extinct", "distractors": ["still living unchanged", "living only in oceans", "still living in the same places"], "why": "Most species that ever lived are extinct, according to the fossil record."}, {"id": "8.LS4.1-r04", "standard": "8.LS4.1", "kind": "recall", "prompt": "Fossils in deeper rock layers tend to be", "correct": "less like modern species", "distractors": ["more like today's species", "always larger", "always smaller"], "why": "Older layers usually hold organisms that differ more from living species. Older life was not always simpler, and evolution is not a ladder."}, {"id": "8.LS4.1-r05", "standard": "8.LS4.1", "kind": "recall", "prompt": "A fossil is", "correct": "preserved remains or traces of old life", "distractors": ["any rock that is very, very old", "a living organism frozen in ice today", "a crystal that formed in a cave"], "why": "Fossils include bones, shells, imprints, and tracks."}, {"id": "8.LS4.1-r06", "standard": "8.LS4.1", "kind": "recall", "prompt": "Footprints preserved in rock are called", "correct": "trace fossils", "distractors": ["body fossils", "minerals", "crystals"], "why": "Trace fossils show activity, like tracks or burrows, rather than body parts."}, {"id": "8.LS4.1-r07", "standard": "8.LS4.1", "kind": "recall", "prompt": "Most fossils form in", "correct": "sedimentary rock", "distractors": ["igneous rock", "lava", "deep in the mantle"], "why": "Sediment buries remains, and layers harden into rock."}, {"id": "8.LS4.1-r08", "standard": "8.LS4.1", "kind": "recall", "prompt": "The fossil record is incomplete because", "correct": "most organisms decay before they fossilize", "distractors": ["fossils only form in hot, dry deserts", "scientists have stopped looking for them", "all fossils are destroyed by erosion"], "why": "Fossilization needs quick burial and special conditions, so most organisms leave no fossil."}, {"id": "8.LS4.1-r09", "standard": "8.LS4.1", "kind": "recall", "prompt": "Fossils that show gradual change in a group over millions of years support the idea that", "correct": "species change over time", "distractors": ["species never change", "all species appeared at once", "fossils are not useful evidence"], "why": "Gradual changes through the layers show change over time."}, {"id": "8.LS4.1-r10", "standard": "8.LS4.1", "kind": "recall", "prompt": "An index fossil is useful because it", "correct": "lived for a short time but over a wide area", "distractors": ["lived everywhere for billions of years", "is always very large", "is found only in one layer worldwide by chance"], "why": "Short-lived, widespread species help match the ages of layers in different places."}, {"id": "8.LS4.1-r11", "standard": "8.LS4.1", "kind": "recall", "prompt": "Diversity in the fossil record refers to", "correct": "the variety of different organisms", "distractors": ["the size of one species", "the number of rock layers", "the depth of the ocean"], "why": "Diversity is the variety of life forms in a time period."}, {"id": "8.LS4.1-r12", "standard": "8.LS4.1", "kind": "recall", "prompt": "A sudden drop in many fossil species between two layers suggests", "correct": "a mass extinction", "distractors": ["a gradual increase in species", "that fossils were moved", "that layers were mixed"], "why": "Many species disappearing at once marks a mass extinction."}, {"id": "8.LS4.1-r13", "standard": "8.LS4.1", "kind": "recall", "prompt": "Whale fossils with small back legs suggest that", "correct": "whale ancestors lived on land", "distractors": ["whales always had legs", "whales came from fish only", "legs help whales swim today"], "why": "Transitional fossils show whales' ancestors had legs and lived on land."}, {"id": "8.LS4.1-r14", "standard": "8.LS4.1", "kind": "recall", "prompt": "A transitional fossil shows", "correct": "features of both an older group and a newer group", "distractors": ["only features of modern species", "no features at all", "features of plants and animals together"], "why": "Fossils like Tiktaalik show traits between fish and land animals."}, {"id": "8.LS4.1-r15", "standard": "8.LS4.1", "kind": "recall", "prompt": "Relative dating tells", "correct": "which layer or fossil is older or younger", "distractors": ["the exact age of a fossil in years", "how much the fossil weighs", "the original color of the fossil"], "why": "Relative dating orders events. Absolute dating gives ages in years."}, {"id": "8.LS4.1-r16", "standard": "8.LS4.1", "kind": "recall", "prompt": "Fossils of the same species found in matching layers far apart suggest those layers are", "correct": "about the same age", "distractors": ["older wherever the rock is thicker", "both from today", "formed millions of years apart"], "why": "Matching fossils help correlate layers."}, {"id": "8.LS4.1-r17", "standard": "8.LS4.1", "kind": "recall", "prompt": "If a rock layer cuts through other layers, the cutting layer is", "correct": "younger than the layers it cuts", "distractors": ["older than the layers it cuts", "the same age", "always the oldest layer"], "why": "A layer must exist before something can cut through it."}, {"id": "8.LS4.1-r18", "standard": "8.LS4.1", "kind": "recall", "prompt": "The fossil record shows that life on Earth has", "correct": "changed a lot over billions of years", "distractors": ["stayed the same since it began", "only existed for a few thousand years", "always included humans"], "why": "Fossils show early simple life, then much more varied life over time."}, {"id": "8.LS4.1-r19", "standard": "8.LS4.1", "kind": "recall", "prompt": "A fern fossil found where no ferns grow today tells us", "correct": "the environment there has changed", "distractors": ["ferns live there now", "fossils move by themselves", "plants never change"], "why": "Fossils show past environments that may differ from today."}, {"id": "8.LS4.1-r20", "standard": "8.LS4.1", "kind": "recall", "prompt": "Dinosaur fossils are not found in the same layers as human fossils. This shows", "correct": "non-bird dinosaurs died out long before humans", "distractors": ["humans and dinosaurs lived at the same time", "fossils in rock layers are always mixed up", "dinosaurs lived after the first humans"], "why": "The layers show a large time gap between dinosaurs and humans."}, {"id": "8.LS4.1-s01", "standard": "8.LS4.1", "kind": "scenario", "prompt": "Layer 1 (bottom) has trilobite fossils. Layer 3 (top) has mammal fossils. Layer 2 has neither. What is the best conclusion?", "correct": "Trilobites lived before the mammals here.", "distractors": ["Mammals lived before trilobites here.", "They lived at the same time.", "Layer 2 is the oldest layer."], "why": "Lower layers are older, so trilobites came first."}, {"id": "8.LS4.1-s02", "standard": "8.LS4.1", "kind": "scenario", "prompt": "A scientist finds a fossil with feathers, teeth, and a long bony tail. What is the best interpretation?", "correct": "It links dinosaurs and birds (a transitional form).", "distractors": ["It is a modern bird that had an injury.", "It is a fish that had feathers and teeth.", "It shows that feathers evolved in mammals."], "why": "Archaeopteryx-like fossils mix reptile and bird traits, showing a link between groups."}, {"id": "8.LS4.1-s03", "standard": "8.LS4.1", "kind": "scenario", "prompt": "Two cliffs 300 km apart both contain the same short-lived ammonite fossil in one layer. What can you infer?", "correct": "Those layers formed at about the same time.", "distractors": ["The ammonites traveled between cliffs.", "The layers are very different ages.", "The fossils were placed by people."], "why": "Index fossils let geologists match layers of the same age."}, {"id": "8.LS4.1-s04", "standard": "8.LS4.1", "kind": "scenario", "prompt": "A student says, \"No fossils means nothing lived there.\" Which reply is most accurate?", "correct": "Fossils need special conditions, so many organisms leave none.", "distractors": ["Correct, because every living thing becomes a fossil.", "Correct, because fossils always form when things die.", "Fossils only form from bones, so it depends on bones."], "why": "The record is incomplete. Most organisms decay without fossilizing."}, {"id": "8.LS4.1-s05", "standard": "8.LS4.1", "kind": "scenario", "prompt": "Fossils in a series of layers show horses getting larger and having fewer toes over time. What does this pattern support?", "correct": "Horses changed gradually over millions of years.", "distractors": ["Horses have always looked the same.", "All horse species lived at the same time.", "Toes grew back over time."], "why": "The sequence documents gradual change in a lineage."}, {"id": "8.LS4.1-s06", "standard": "8.LS4.1", "kind": "scenario", "prompt": "A layer of shell fossils is found high in a mountain. Which is the best explanation?", "correct": "The area was once underwater and later uplifted.", "distractors": ["Shells can grow on mountains over time.", "Birds dropped the shells there long ago.", "Sea level was once higher than the mountain."], "why": "Marine fossils on land show the environment changed and rock was raised."}, {"id": "8.LS4.1-s07", "standard": "8.LS4.1", "kind": "scenario", "prompt": "In one area, the bottom layers have 5 species, middle layers have 40 species, and top layers have 12 species. What does this show?", "correct": "Diversity rose, then fell, maybe from extinction.", "distractors": ["Diversity stayed the same in every layer.", "Diversity only increased over time.", "The top layers are the oldest layers."], "why": "Changes in species counts show changing diversity, with a drop suggesting extinctions."}, {"id": "8.LS4.1-s08", "standard": "8.LS4.1", "kind": "scenario", "prompt": "An igneous dike cuts through layers A, B, and C. Which is youngest?", "correct": "the dike", "distractors": ["layer A", "layer B", "layer C"], "why": "Something that cuts through layers must be younger than all of them."}, {"id": "8.LS4.1-s09", "standard": "8.LS4.1", "kind": "scenario", "prompt": "Fossil fish are found in a desert. Which interpretation is best supported?", "correct": "A lake or sea once covered the area.", "distractors": ["Fish lived in the sand.", "The fossils blew there from the ocean.", "Deserts have always been wet."], "why": "Fossils reveal past environments that differed from today."}, {"id": "8.LS4.1-s10", "standard": "8.LS4.1", "kind": "scenario", "prompt": "A scientist wants to show that life has changed over time. Which evidence is strongest?", "correct": "A series of fossils in layers showing gradual change.", "distractors": ["One fossil of a very large animal.", "A painting of what a dinosaur looked like.", "A list of the animals that are alive today."], "why": "A dated sequence of fossils shows change through time."}, {"id": "8.LS4.2-r01", "standard": "8.LS4.2", "kind": "recall", "prompt": "Homologous structures are", "correct": "body parts with similar structure from a common ancestor", "distractors": ["body parts that look different and have different origins", "parts with the same use but no shared ancestry", "parts that no longer exist"], "why": "Same bone plan, possibly different uses, shows common ancestry."}, {"id": "8.LS4.2-r02", "standard": "8.LS4.2", "kind": "recall", "prompt": "A human arm, a bat wing, and a whale flipper have similar bones. This suggests", "correct": "they share a common ancestor", "distractors": ["they do the same job", "they are the same species", "bones never change"], "why": "Similar bone patterns point to descent from a shared ancestor, even with different uses."}, {"id": "8.LS4.2-r03", "standard": "8.LS4.2", "kind": "recall", "prompt": "Analogous structures, like bird wings and insect wings,", "correct": "have similar uses but different origins", "distractors": ["show close common ancestry", "have identical bone structures", "are always vestigial"], "why": "Similar function does not mean shared ancestry."}, {"id": "8.LS4.2-r04", "standard": "8.LS4.2", "kind": "recall", "prompt": "A vestigial structure is", "correct": "a reduced body part with little or no use now", "distractors": ["a fully working organ that is very important", "a brand new body part that just evolved", "a fossil of a body part only"], "why": "Vestigial structures, like the human tailbone, hint at ancestors in which the part was useful."}, {"id": "8.LS4.2-r05", "standard": "8.LS4.2", "kind": "recall", "prompt": "Which is an example of a vestigial structure?", "correct": "leg bones inside some snakes", "distractors": ["a bird's wing used for flying", "a fish's gills used for breathing", "a human's heart used for pumping"], "why": "Some snakes have tiny hip and leg bones they don't use for walking."}, {"id": "8.LS4.2-r06", "standard": "8.LS4.2", "kind": "recall", "prompt": "Embryos of fish, chickens, and humans look similar at early stages. This suggests", "correct": "they share a common ancestor", "distractors": ["they will grow into the same animal", "they live in the same habitat", "they eat the same food"], "why": "Early similarities in development point to shared ancestry."}, {"id": "8.LS4.2-r07", "standard": "8.LS4.2", "kind": "recall", "prompt": "The more similar the DNA of two species,", "correct": "the more closely related they probably are", "distractors": ["the less related the two species are", "the bigger the two species are", "the older the two species are"], "why": "DNA similarity is strong evidence of how recently species shared an ancestor."}, {"id": "8.LS4.2-r08", "standard": "8.LS4.2", "kind": "recall", "prompt": "Humans and chimpanzees share about 98% of their DNA. This suggests they", "correct": "share a recent common ancestor", "distractors": ["are the same species", "do not share an ancestor", "evolved from modern chimps"], "why": "Shared DNA shows a common ancestor, not that humans came from today's chimps."}, {"id": "8.LS4.2-r09", "standard": "8.LS4.2", "kind": "recall", "prompt": "A cladogram shows", "correct": "how species are related by ancestry", "distractors": ["the size of each species in a group", "where each species lives on Earth", "what each species eats to survive"], "why": "Branches show shared ancestors and relationships."}, {"id": "8.LS4.2-r10", "standard": "8.LS4.2", "kind": "recall", "prompt": "In a cladogram, species that branch from a more recent point are", "correct": "more closely related", "distractors": ["less closely related", "unrelated", "the oldest species"], "why": "A more recent branch point means a more recent shared ancestor."}, {"id": "8.LS4.2-r11", "standard": "8.LS4.2", "kind": "recall", "prompt": "Comparing a fossil's bones to a living animal's bones can show", "correct": "whether they share ancestry", "distractors": ["the fossil's exact color", "how the fossil died", "what the fossil ate last"], "why": "Anatomical similarities link extinct and living organisms."}, {"id": "8.LS4.2-r12", "standard": "8.LS4.2", "kind": "recall", "prompt": "Genetic information used to show common ancestry includes", "correct": "DNA and protein sequences", "distractors": ["hair color only", "body size only", "habitat type"], "why": "Molecular data compare sequences across species."}, {"id": "8.LS4.2-r13", "standard": "8.LS4.2", "kind": "recall", "prompt": "A fossil with features of both whales and land mammals supports", "correct": "common ancestry between them", "distractors": ["whales and land mammals being unrelated", "whales evolving from fish recently", "fossils being unreliable"], "why": "Shared features link living whales to land ancestors."}, {"id": "8.LS4.2-r14", "standard": "8.LS4.2", "kind": "recall", "prompt": "The bones in a cat's leg and a horse's leg are arranged similarly. These are", "correct": "homologous structures", "distractors": ["analogous structures", "vestigial structures", "unrelated structures"], "why": "Same basic bone pattern from a common ancestor."}, {"id": "8.LS4.2-r15", "standard": "8.LS4.2", "kind": "recall", "prompt": "The wing of a butterfly and the wing of a bat are", "correct": "analogous structures", "distractors": ["homologous structures", "vestigial structures", "identical structures"], "why": "They do the same job but have very different structures and origins."}, {"id": "8.LS4.2-r16", "standard": "8.LS4.2", "kind": "recall", "prompt": "A common ancestor is", "correct": "a species from which two or more species came", "distractors": ["the oldest species that is alive today", "the largest species in a group", "a species that has never changed"], "why": "Lines of descent split from a shared ancestor."}, {"id": "8.LS4.2-r17", "standard": "8.LS4.2", "kind": "recall", "prompt": "Why do scientists use both anatomy and DNA to study ancestry?", "correct": "Several kinds of evidence are stronger together", "distractors": ["DNA is never useful for ancestry", "Anatomy is always wrong about ancestry", "Only one kind of evidence is allowed"], "why": "When different evidence agrees, the conclusion is more reliable."}, {"id": "8.LS4.2-r18", "standard": "8.LS4.2", "kind": "recall", "prompt": "Two species with very different DNA but similar shapes are most likely", "correct": "not closely related", "distractors": ["very closely related", "the same species", "descended from the same recent ancestor"], "why": "Similar shape can come from similar environments (analogous), not shared ancestry."}, {"id": "8.LS4.2-r19", "standard": "8.LS4.2", "kind": "recall", "prompt": "Whale hip bones and the human tailbone are examples of", "correct": "vestigial structures", "distractors": ["homologous structures with new uses", "analogous structures", "structures from recent mutations"], "why": "Vestigial means reduced from an ancestor's form, not useless. Whale hips and our tailbone are small versions of parts ancestors used for legs and tails."}, {"id": "8.LS4.2-r20", "standard": "8.LS4.2", "kind": "recall", "prompt": "Comparing patterns of similarity between living and fossil species helps scientists", "correct": "infer evolutionary relationships", "distractors": ["find exact ages of species", "change species' DNA", "stop extinction"], "why": "Patterns of similarity reveal who is related to whom."}, {"id": "8.LS4.2-s01", "standard": "8.LS4.2", "kind": "scenario", "prompt": "DNA data: Species A and B share 95%, A and C share 80%, B and C share 81%. Which two are most closely related?", "correct": "A and B", "distractors": ["A and C", "B and C", "All are equally related"], "why": "The highest DNA similarity suggests the most recent common ancestor."}, {"id": "8.LS4.2-s02", "standard": "8.LS4.2", "kind": "scenario", "prompt": "A bird wing, human arm, and dolphin flipper are used for flying, grabbing, and swimming. Each has the same bones. Which explanation is best?", "correct": "They share a common ancestor and adapted to different uses.", "distractors": ["They were each designed separately for the same job.", "They are analogous structures with different origins.", "Their similarity is only a coincidence of nature."], "why": "Same structure, different functions = homologous structures from a shared ancestor."}, {"id": "8.LS4.2-s03", "standard": "8.LS4.2", "kind": "scenario", "prompt": "A shark and a dolphin have similar body shapes, but a dolphin has lungs and a shark has gills. What best explains their shape?", "correct": "Similar environments led to similar body shapes.", "distractors": ["They are closely related species of fish.", "Sharks evolved from dolphins long ago.", "Dolphins evolved from sharks long ago."], "why": "Similar shapes from similar needs (analogous), not close ancestry. Dolphins are mammals."}, {"id": "8.LS4.2-s04", "standard": "8.LS4.2", "kind": "scenario", "prompt": "A cladogram shows lizards and birds sharing a branch point more recent than their branch with frogs. What does this mean?", "correct": "Lizards and birds are more closely related.", "distractors": ["Frogs and birds are the most closely related.", "Lizards evolved from birds long ago.", "All three animals are equally related."], "why": "A more recent shared branch point means closer relationship."}, {"id": "8.LS4.2-s05", "standard": "8.LS4.2", "kind": "scenario", "prompt": "A fossil of an extinct animal has a skull like a modern dog's and a wolf's. What does this best support?", "correct": "It likely shares ancestry with dogs and wolves.", "distractors": ["It is a modern dog that died long ago.", "It is unrelated to either dogs or wolves.", "It evolved from wolves living today."], "why": "Similar anatomy links extinct and living species through common ancestry."}, {"id": "8.LS4.2-s06", "standard": "8.LS4.2", "kind": "scenario", "prompt": "Early embryos of a fish, chicken, and human all have tail-like structures and gill-like folds. What does this show?", "correct": "They share a common ancestor.", "distractors": ["They all become fish.", "Humans have gills as adults.", "Embryos don't show ancestry."], "why": "Shared early developmental features suggest common ancestry."}, {"id": "8.LS4.2-s07", "standard": "8.LS4.2", "kind": "scenario", "prompt": "A student says, \"Humans evolved from chimpanzees.\" What is the most accurate correction?", "correct": "Humans and chimps share a common ancestor.", "distractors": ["Correct, humans came from modern chimps.", "Humans and chimps are unrelated.", "Chimps evolved from humans."], "why": "Neither evolved from the other. Both descended from an earlier shared ancestor."}, {"id": "8.LS4.2-s08", "standard": "8.LS4.2", "kind": "scenario", "prompt": "Scientists compare a protein in four species. Species W and X differ by 2 amino acids; W and Y by 10; W and Z by 25. Which is most distantly related to W?", "correct": "Z", "distractors": ["X", "Y", "All are equally related"], "why": "More differences mean a more distant relationship."}, {"id": "8.LS4.2-s09", "standard": "8.LS4.2", "kind": "scenario", "prompt": "A python has tiny hip bones that it does not use for walking. Which is the best explanation?", "correct": "Its ancestors had legs that were used for walking.", "distractors": ["The bones will grow into legs later.", "Pythons use hips to swim.", "The bones are a mistake with no history."], "why": "Vestigial structures are leftovers from ancestors where they were useful."}, {"id": "8.LS4.2-s10", "standard": "8.LS4.2", "kind": "scenario", "prompt": "Two lizard species look almost identical but have very different DNA. A third species looks different but has very similar DNA to the first. Which conclusion is best?", "correct": "DNA suggests the third species is more closely related.", "distractors": ["Appearance is always the best evidence of ancestry.", "All three species are equally related to each other.", "DNA tells nothing useful about ancestry."], "why": "DNA similarity is often more reliable than appearance for relationships."}, {"id": "8.LS4.3-r01", "standard": "8.LS4.3", "kind": "recall", "prompt": "Variation in a population means", "correct": "individuals have differences in traits", "distractors": ["all individuals are exactly identical", "traits never change over generations", "only one trait exists in each species"], "why": "Differences such as color, size, or speed exist among individuals."}, {"id": "8.LS4.3-r02", "standard": "8.LS4.3", "kind": "recall", "prompt": "A heritable trait is one that", "correct": "can be passed from parents to offspring", "distractors": ["is learned during an animal's life", "is caused by an injury or accident", "cannot affect an animal's survival"], "why": "Heritable traits are coded in genes and passed on."}, {"id": "8.LS4.3-r03", "standard": "8.LS4.3", "kind": "recall", "prompt": "Which is a heritable trait?", "correct": "fur color in rabbits", "distractors": ["a scar from an injury", "a dog learning tricks", "a haircut"], "why": "Fur color is genetic. Scars, haircuts, and tricks are acquired, not inherited."}, {"id": "8.LS4.3-r04", "standard": "8.LS4.3", "kind": "recall", "prompt": "Some individuals survive and reproduce more because", "correct": "their traits suit the environment better", "distractors": ["they want to survive more than others", "they are always the largest animals", "they try harder than the others"], "why": "Traits that help in a given environment raise the chance of survival and reproduction."}, {"id": "8.LS4.3-r05", "standard": "8.LS4.3", "kind": "recall", "prompt": "An adaptation is", "correct": "an inherited trait that helps survival", "distractors": ["a change an animal makes on purpose", "any trait at all, helpful or not", "a trait learned from its parents"], "why": "Adaptations are inherited traits that help in an environment."}, {"id": "8.LS4.3-r06", "standard": "8.LS4.3", "kind": "recall", "prompt": "In a population of moths, light moths are easily seen on dark trees. Most likely,", "correct": "fewer light moths will survive to reproduce", "distractors": ["light moths will turn dark to hide", "all moths will survive equally well", "dark moths will turn light over time"], "why": "Predators catch the visible moths more often. Individuals don't change color on purpose."}, {"id": "8.LS4.3-r07", "standard": "8.LS4.3", "kind": "recall", "prompt": "Variation in traits in a population mostly comes from", "correct": "differences in genes", "distractors": ["choices animals make", "the weather on one day", "exercise"], "why": "Genetic differences, from mutation and sexual reproduction, create variation."}, {"id": "8.LS4.3-r08", "standard": "8.LS4.3", "kind": "recall", "prompt": "Probability of survival means", "correct": "the chance an individual will survive", "distractors": ["a guarantee of survival", "how long a species has existed", "how fast an animal grows"], "why": "Traits change the odds, not guarantee survival."}, {"id": "8.LS4.3-r09", "standard": "8.LS4.3", "kind": "recall", "prompt": "A trait that helps in one environment may", "correct": "be harmful in another", "distractors": ["always help everywhere", "never matter", "always be harmful"], "why": "White fur hides a rabbit in snow but stands out on brown ground."}, {"id": "8.LS4.3-r10", "standard": "8.LS4.3", "kind": "recall", "prompt": "Which helps a population survive environmental change?", "correct": "having a lot of variation", "distractors": ["having no variation", "all individuals being identical", "having fewer offspring"], "why": "More variation means some individuals may have traits that fit new conditions."}, {"id": "8.LS4.3-r11", "standard": "8.LS4.3", "kind": "recall", "prompt": "Cacti with thick, waxy skin survive dry deserts better because the skin", "correct": "reduces water loss", "distractors": ["attracts more rain", "soaks up rain through the skin", "stops animals from eating them"], "why": "The trait fits the dry environment."}, {"id": "8.LS4.3-r12", "standard": "8.LS4.3", "kind": "recall", "prompt": "Mutations are", "correct": "changes in DNA that can create new variation", "distractors": ["always harmful changes to an organism", "changes caused only by an animal's choices", "learned behaviors passed to offspring"], "why": "Mutations can be harmful, helpful, or neutral, and they create new variation."}, {"id": "8.LS4.3-r13", "standard": "8.LS4.3", "kind": "recall", "prompt": "Animals pass on", "correct": "traits coded in their genes", "distractors": ["skills they learned", "injuries they got", "body changes from exercise"], "why": "Only genetic traits are inherited."}, {"id": "8.LS4.3-r14", "standard": "8.LS4.3", "kind": "recall", "prompt": "In a population of beetles, some can survive on less water. During a drought, they will likely", "correct": "survive and reproduce more", "distractors": ["die out first", "change into a new color", "stop reproducing"], "why": "The trait improves survival in a drought."}, {"id": "8.LS4.3-r15", "standard": "8.LS4.3", "kind": "recall", "prompt": "A population with little genetic variation is at risk because", "correct": "a disease or change could affect them all", "distractors": ["they always grow too fast", "they have too many traits", "they can't be seen by predators"], "why": "With little variation, fewer individuals may be able to survive a new threat."}, {"id": "8.LS4.3-r16", "standard": "8.LS4.3", "kind": "recall", "prompt": "Which describes how traits affect survival?", "correct": "Some traits make survival more likely in an environment", "distractors": ["All traits help survival equally in every place", "Traits never affect whether an animal survives", "Only learned traits affect an animal's survival"], "why": "Survival probability depends on how traits fit the environment."}, {"id": "8.LS4.3-r17", "standard": "8.LS4.3", "kind": "recall", "prompt": "Giraffes with longer necks reach more leaves in a drought. Over generations,", "correct": "long-neck traits become more common", "distractors": ["giraffes stretch their necks longer", "all giraffes get short necks", "necks stay the same"], "why": "Those with long necks survive and reproduce more. Stretching does not get passed on."}, {"id": "8.LS4.3-r18", "standard": "8.LS4.3", "kind": "recall", "prompt": "Offspring from two parents usually", "correct": "have a mix of traits from both", "distractors": ["are identical copies of one parent", "have no traits from parents", "always look like grandparents"], "why": "Sexual reproduction mixes genes, adding variation."}, {"id": "8.LS4.3-r19", "standard": "8.LS4.3", "kind": "recall", "prompt": "Antibiotic resistance spreads in bacteria because", "correct": "resistant bacteria survive and reproduce", "distractors": ["antibiotics make bacteria stronger on purpose", "bacteria learn to resist", "all bacteria die"], "why": "Resistant individuals already existed, survived the drug, and multiplied."}, {"id": "8.LS4.3-r20", "standard": "8.LS4.3", "kind": "recall", "prompt": "Which is NOT a source of genetic variation?", "correct": "learning a new behavior", "distractors": ["mutations in DNA", "mixing genes from two parents", "new gene combinations in offspring"], "why": "Learned behaviors are not in the genes, so they are not inherited. Mutations and sexual reproduction create genetic variation."}, {"id": "8.LS4.3-s01", "standard": "8.LS4.3", "kind": "scenario", "prompt": "A population of mice has brown and white fur. After snow covers the ground for many years, most mice are white. Which explanation is best?", "correct": "White mice were seen less by predators and survived.", "distractors": ["Brown mice turned their fur white to hide.", "The snow changed the genes of the mice.", "White mice tried harder to survive."], "why": "White fur was already in the population and increased the chance of survival."}, {"id": "8.LS4.3-s02", "standard": "8.LS4.3", "kind": "scenario", "prompt": "Rabbits in a cold area vary in fur thickness. A very cold winter hits. Which rabbits are most likely to have offspring next spring?", "correct": "those with the thickest fur", "distractors": ["those with the thinnest fur", "all rabbits equally", "those that ate the most"], "why": "Thicker fur, a heritable trait, raises survival in extreme cold."}, {"id": "8.LS4.3-s03", "standard": "8.LS4.3", "kind": "scenario", "prompt": "A student says, \"Giraffes got long necks because they stretched them.\" What is the best correction?", "correct": "Giraffes with longer necks survived and passed it on.", "distractors": ["Stretching makes necks longer in their babies.", "Giraffes chose to have long necks to reach food.", "Necks grow longer from eating more leaves."], "why": "Traits acquired by stretching are not inherited. Variation plus survival explains the change."}, {"id": "8.LS4.3-s04", "standard": "8.LS4.3", "kind": "scenario", "prompt": "A field of identical cloned wheat is hit by a new disease, and all plants die. A nearby field of mixed varieties loses only some plants. Why?", "correct": "Variation meant some plants had resistance.", "distractors": ["The mixed field had better weather.", "Clones are always stronger.", "The disease only infects mixed fields."], "why": "Genetic variation increases the chance some individuals survive a new threat."}, {"id": "8.LS4.3-s05", "standard": "8.LS4.3", "kind": "scenario", "prompt": "Data show a beetle population was 50% green and 50% brown. Birds eat more green beetles on brown bark. After 10 generations, what is likely?", "correct": "More brown beetles than green.", "distractors": ["More green beetles than brown.", "Still 50% green and 50% brown.", "All beetles become a new color."], "why": "Brown beetles survive better and reproduce more, so brown becomes more common."}, {"id": "8.LS4.3-s06", "standard": "8.LS4.3", "kind": "scenario", "prompt": "A lizard with a mutation for longer toes climbs trees better and escapes predators. What will most likely happen over generations?", "correct": "The long-toe trait will become more common.", "distractors": ["All lizards will lose their toes.", "The mutation will disappear right away.", "Lizards will choose to grow longer toes."], "why": "A heritable trait that improves survival tends to increase in frequency."}, {"id": "8.LS4.3-s07", "standard": "8.LS4.3", "kind": "scenario", "prompt": "A bacteria population is treated with an antibiotic. 99% die, but 1% survive. What happens next?", "correct": "Survivors reproduce, so resistance becomes common.", "distractors": ["The bacteria will all die off within a day.", "The survivors teach the others to resist.", "The antibiotic makes all the bacteria weaker."], "why": "The resistant few multiply, so the new population is mostly resistant."}, {"id": "8.LS4.3-s08", "standard": "8.LS4.3", "kind": "scenario", "prompt": "Two populations of the same snail species: one has high variation in shell color, one has almost none. A new predator arrives. Which is more likely to survive long-term?", "correct": "the population with high variation", "distractors": ["the population with little variation", "both equally", "neither"], "why": "More variation means a better chance some snails have traits that help."}, {"id": "8.LS4.3-s09", "standard": "8.LS4.3", "kind": "scenario", "prompt": "A scientist notes that larger-beaked finches survive a drought with only hard seeds. What is the best claim?", "correct": "Beak size affects survival when the food changes.", "distractors": ["Finches grew larger beaks during the drought.", "Beak size never matters for a finch's survival.", "All finches will die in any long drought."], "why": "A heritable trait changed survival odds when the environment changed."}, {"id": "8.LS4.3-s10", "standard": "8.LS4.3", "kind": "scenario", "prompt": "A student exercises and builds big muscles. Will her future children be born with big muscles because of this?", "correct": "No, acquired traits aren't inherited.", "distractors": ["Yes, exercise changes her genes.", "Yes, but only her sons.", "Only if she exercises more."], "why": "Traits gained during life are not passed on through genes."}, {"id": "8.LS4.4-r01", "standard": "8.LS4.4", "kind": "recall", "prompt": "Natural selection is", "correct": "helpful inherited traits leading to more survival and offspring", "distractors": ["animals changing their bodies on purpose to survive", "humans choosing which animals will breed", "traits appearing because the animals need them"], "why": "The environment \"selects\" which existing traits get passed on. It is not choice or need."}, {"id": "8.LS4.4-r02", "standard": "8.LS4.4", "kind": "recall", "prompt": "For natural selection to happen, a population must have", "correct": "variation in heritable traits", "distractors": ["identical individuals", "no predators", "unlimited food"], "why": "Without differences, there is nothing for the environment to favor."}, {"id": "8.LS4.4-r03", "standard": "8.LS4.4", "kind": "recall", "prompt": "Over many generations, natural selection can cause", "correct": "helpful traits to become more common", "distractors": ["all traits to disappear", "individuals to change during their lifetime", "populations to stop reproducing"], "why": "Populations change as favored traits are passed on more often."}, {"id": "8.LS4.4-r04", "standard": "8.LS4.4", "kind": "recall", "prompt": "Natural selection acts on", "correct": "individuals, but the population changes over time", "distractors": ["only one individual during its lifetime", "only behaviors that animals learn", "only plants, and not animals"], "why": "An individual's traits affect its survival, but evolution is a change in the population."}, {"id": "8.LS4.4-r05", "standard": "8.LS4.4", "kind": "recall", "prompt": "An adaptation becomes common in a population because", "correct": "individuals with it leave more offspring", "distractors": ["individuals decide they need it", "the environment creates it on demand", "it was learned by parents"], "why": "More offspring with the trait means more of the next generation has it."}, {"id": "8.LS4.4-r06", "standard": "8.LS4.4", "kind": "recall", "prompt": "Overproduction means organisms", "correct": "produce more offspring than can survive", "distractors": ["only produce one offspring at a time", "never compete for food or space", "always survive to become adults"], "why": "More offspring than resources leads to competition."}, {"id": "8.LS4.4-r07", "standard": "8.LS4.4", "kind": "recall", "prompt": "Competition for food, water, and space leads to", "correct": "some individuals surviving better than others", "distractors": ["all individuals surviving equally", "no change in the population", "everyone getting the same resources"], "why": "Limited resources mean those with better-suited traits do better."}, {"id": "8.LS4.4-r08", "standard": "8.LS4.4", "kind": "recall", "prompt": "If an environment changes, a trait that was once helpful can", "correct": "become harmful", "distractors": ["always stay helpful", "turn into a new trait instantly", "never change in value"], "why": "Fitness depends on the environment, which can change."}, {"id": "8.LS4.4-r09", "standard": "8.LS4.4", "kind": "recall", "prompt": "The peppered moth population got darker during the Industrial Revolution because", "correct": "dark moths were harder to see on sooty trees", "distractors": ["soot from factories dyed the moths dark", "moths chose to be dark to stay safe", "light moths moved away on purpose"], "why": "Dark moths already existed and survived better on sooty bark."}, {"id": "8.LS4.4-r10", "standard": "8.LS4.4", "kind": "recall", "prompt": "Evolution by natural selection usually happens over", "correct": "many generations", "distractors": ["one generation", "a single day", "an individual's lifetime"], "why": "Population changes take many generations."}, {"id": "8.LS4.4-r11", "standard": "8.LS4.4", "kind": "recall", "prompt": "A population of insects is sprayed with pesticide every year. Over time, the population becomes", "correct": "more resistant to the pesticide", "distractors": ["weaker to the pesticide", "extinct every year", "unchanged"], "why": "Resistant insects survive and pass on resistance."}, {"id": "8.LS4.4-r12", "standard": "8.LS4.4", "kind": "recall", "prompt": "Which is NOT required for natural selection?", "correct": "individuals choosing their traits", "distractors": ["variation in traits", "traits that can be inherited", "more offspring than can survive"], "why": "Organisms don't choose traits. Variation, inheritance, and overproduction are required."}, {"id": "8.LS4.4-r13", "standard": "8.LS4.4", "kind": "recall", "prompt": "\"Survival of the fittest\" means the individuals that", "correct": "survive and reproduce most in their environment", "distractors": ["are the strongest and biggest in the group", "exercise the most and build muscle", "live the longest of any in the group"], "why": "Fitness means leaving offspring, not being strongest."}, {"id": "8.LS4.4-r14", "standard": "8.LS4.4", "kind": "recall", "prompt": "When a population's environment stays the same for a long time, the population", "correct": "may change little", "distractors": ["must change rapidly", "always goes extinct", "loses all variation"], "why": "If conditions don't change, the traits that already fit may stay common."}, {"id": "8.LS4.4-r15", "standard": "8.LS4.4", "kind": "recall", "prompt": "Natural selection can lead to new species when", "correct": "groups are separated and adapt to different places", "distractors": ["one animal changes a lot in its lifetime", "animals choose to change into new forms", "humans breed them for certain traits"], "why": "Separated populations face different pressures and may become different species."}, {"id": "8.LS4.4-r16", "standard": "8.LS4.4", "kind": "recall", "prompt": "Birds with beaks that crack hard seeds survive a drought better. The next generation will likely have", "correct": "more birds with seed-cracking beaks", "distractors": ["smaller beaks overall", "no change in beaks", "beaks that grew during the drought"], "why": "Birds with helpful beaks leave more offspring with that trait."}, {"id": "8.LS4.4-r17", "standard": "8.LS4.4", "kind": "recall", "prompt": "Camouflage helps an animal survive because", "correct": "predators have a harder time finding it", "distractors": ["it makes the animal faster", "it makes the animal larger", "it gives the animal more food"], "why": "Blending in lowers the chance of being caught."}, {"id": "8.LS4.4-r18", "standard": "8.LS4.4", "kind": "recall", "prompt": "Bacteria develop resistance to antibiotics because", "correct": "resistant bacteria survive and reproduce", "distractors": ["antibiotics teach bacteria to resist", "bacteria choose to resist", "all bacteria are already resistant"], "why": "Selection favors the few resistant ones."}, {"id": "8.LS4.4-r19", "standard": "8.LS4.4", "kind": "recall", "prompt": "An organism's fitness is best measured by", "correct": "how many surviving offspring it leaves", "distractors": ["how strong it is compared to others", "how big it grows as an adult", "how fast it can run from predators"], "why": "Fitness is reproductive success in an environment."}, {"id": "8.LS4.4-r20", "standard": "8.LS4.4", "kind": "recall", "prompt": "Which statement best describes natural selection?", "correct": "The environment favors traits that already exist", "distractors": ["Organisms get the new traits they need", "Traits appear when the environment changes", "Animals pass on traits they practice"], "why": "Selection works on existing variation, not on need."}, {"id": "8.LS4.4-s01", "standard": "8.LS4.4", "kind": "scenario", "prompt": "In a beetle population, 60% are green and 40% brown. Birds eat green beetles more often on brown bark. Predict the population after many years.", "correct": "Brown beetles will become more common.", "distractors": ["Green beetles will become more common.", "The beetles will turn yellow.", "The beetle colors will stay the same."], "why": "Brown beetles survive more and pass on brown color more often."}, {"id": "8.LS4.4-s02", "standard": "8.LS4.4", "kind": "scenario", "prompt": "After a forest fire, the bark of trees becomes black. A moth population had mostly light moths with a few dark ones. What would most likely happen?", "correct": "Dark moths would become more common.", "distractors": ["Light moths would turn dark.", "All moths would die.", "Light moths would stay more common."], "why": "Dark moths are hidden on burned bark and survive to reproduce more."}, {"id": "8.LS4.4-s03", "standard": "8.LS4.4", "kind": "scenario", "prompt": "A student says, \"Fish in a dark cave lost their eyes because they didn't need them.\" Which revision is better?", "correct": "Eyes gave no advantage, so eyeless fish did as well.", "distractors": ["The fish chose not to grow eyes in the dark.", "Their eyes fell off from not being used.", "The darkness slowly destroyed their eyes."], "why": "Traits don't vanish because of need. In the dark, eyes give no advantage, so fish without them could do as well or better."}, {"id": "8.LS4.4-s04", "standard": "8.LS4.4", "kind": "scenario", "prompt": "A farmer uses the same weed killer for 10 years. It now kills only 20% of the weeds. Why?", "correct": "Resistant weeds survived and reproduced over time.", "distractors": ["The weeds learned to avoid the weed killer.", "The weed killer got weaker every year.", "The weeds grew stronger from exercise."], "why": "Resistant weeds were selected, so the population changed."}, {"id": "8.LS4.4-s05", "standard": "8.LS4.4", "kind": "scenario", "prompt": "Island lizards are blown to a new island with tall, thin branches. Over many generations, lizards there have shorter legs. Which explanation is best?", "correct": "Short-legged lizards gripped better and left more young.", "distractors": ["The lizards' legs shrank from all the climbing.", "The lizards decided to have shorter legs.", "The new island changed their genes directly."], "why": "Short legs were already in the population and helped survival."}, {"id": "8.LS4.4-s06", "standard": "8.LS4.4", "kind": "scenario", "prompt": "Rabbits with white fur are common in snowy areas. Climate change shortens snowy seasons. What might happen over generations?", "correct": "Brown-furred rabbits may become more common.", "distractors": ["White rabbits will change color each year.", "All rabbits will die out right away.", "Nothing will change."], "why": "If brown is better camouflage without snow, brown rabbits survive more."}, {"id": "8.LS4.4-s07", "standard": "8.LS4.4", "kind": "scenario", "prompt": "Finches on two islands have different beak shapes. One island has big, hard seeds; the other has small insects. Which explains the difference?", "correct": "Different food sources favored different beak traits.", "distractors": ["The birds chose different beaks.", "The birds stretched their beaks to fit food.", "The islands' weather made the beaks."], "why": "Each environment favored the beak shape that helped get food."}, {"id": "8.LS4.4-s08", "standard": "8.LS4.4", "kind": "scenario", "prompt": "A population has no variation in fur color. A new predator that hunts by sight arrives. What is likely?", "correct": "With no variation, fur color can't be selected.", "distractors": ["Fur color will quickly change to hide them.", "The predator will leave to find other food.", "All the animals will develop camouflage."], "why": "Natural selection needs variation to act on."}, {"id": "8.LS4.4-s09", "standard": "8.LS4.4", "kind": "scenario", "prompt": "Graph: Over 30 years, the average beak depth of a finch population rose after droughts. What is the best explanation?", "correct": "Deeper-beaked finches survived and had more young.", "distractors": ["Finches grew deeper beaks during their lives.", "Droughts made the beaks deeper directly.", "The finches chose to have deeper beaks."], "why": "Natural selection increased the frequency of deeper beaks."}, {"id": "8.LS4.4-s10", "standard": "8.LS4.4", "kind": "scenario", "prompt": "A new disease kills most of a rabbit population. A few rabbits survive and have offspring. The next generation will most likely", "correct": "have more resistance to the disease", "distractors": ["be more likely to get the disease", "have no resistance at all", "be exactly the same as before"], "why": "Survivors pass on resistance, so it increases in the population."}, {"id": "8.LS4.5-r01", "standard": "8.LS4.5", "kind": "recall", "prompt": "Artificial selection is when", "correct": "humans choose which organisms breed", "distractors": ["nature selects the best traits without people", "animals choose their own mates in the wild", "traits change on their own with no reason"], "why": "Humans, not nature, pick the parents."}, {"id": "8.LS4.5-r02", "standard": "8.LS4.5", "kind": "recall", "prompt": "Dog breeds like poodles and bulldogs are the result of", "correct": "artificial selection by humans", "distractors": ["natural selection in the wild", "genetic engineering only", "random chance"], "why": "People bred dogs with chosen traits over many generations."}, {"id": "8.LS4.5-r03", "standard": "8.LS4.5", "kind": "recall", "prompt": "Corn today has much bigger ears than its wild ancestor because", "correct": "farmers bred plants with bigger ears", "distractors": ["corn grew bigger by itself in the wild", "corn was made in a lab from scratch", "the climate made the corn grow bigger"], "why": "Selective breeding over thousands of years changed corn."}, {"id": "8.LS4.5-r04", "standard": "8.LS4.5", "kind": "recall", "prompt": "Selective breeding is another name for", "correct": "artificial selection", "distractors": ["natural selection", "genetic mutation", "cloning"], "why": "Breeders select parents with desired traits."}, {"id": "8.LS4.5-r05", "standard": "8.LS4.5", "kind": "recall", "prompt": "Genetic engineering is", "correct": "changing an organism's DNA directly", "distractors": ["choosing which animals mate", "letting nature select traits", "feeding animals more"], "why": "Scientists can add, remove, or change genes."}, {"id": "8.LS4.5-r06", "standard": "8.LS4.5", "kind": "recall", "prompt": "Insect-resistant crops made by inserting a gene are an example of", "correct": "genetic engineering", "distractors": ["natural selection", "breeding wild animals", "mutations from the Sun"], "why": "A gene is put into the plant's DNA directly."}, {"id": "8.LS4.5-r07", "standard": "8.LS4.5", "kind": "recall", "prompt": "Gene therapy is used to", "correct": "treat genetic disorders", "distractors": ["make crop plants grow taller", "breed new types of dogs", "clone farm animals for food"], "why": "Gene therapy replaces or repairs faulty genes in a patient."}, {"id": "8.LS4.5-r08", "standard": "8.LS4.5", "kind": "recall", "prompt": "A clone is", "correct": "an organism with the same DNA as another", "distractors": ["a new species made by mixing two", "any offspring of two parents", "a mutated organism"], "why": "Clones are genetically identical."}, {"id": "8.LS4.5-r09", "standard": "8.LS4.5", "kind": "recall", "prompt": "Compared with natural selection, artificial selection usually changes traits", "correct": "faster and toward traits humans want", "distractors": ["slower and toward random traits", "only in wild animals", "only in bacteria"], "why": "Humans pick strong selection, so change happens faster."}, {"id": "8.LS4.5-r10", "standard": "8.LS4.5", "kind": "recall", "prompt": "Broccoli, cabbage, and kale all came from one wild mustard plant through", "correct": "selective breeding", "distractors": ["genetic engineering", "natural selection only", "cloning"], "why": "Farmers selected different parts of the same plant to enlarge."}, {"id": "8.LS4.5-r11", "standard": "8.LS4.5", "kind": "recall", "prompt": "One concern about genetically engineered crops is", "correct": "possible effects on ecosystems", "distractors": ["they always cause allergies in everyone", "they make the soil radioactive", "they are always clones"], "why": "People debate effects on wild plants, insects, and biodiversity."}, {"id": "8.LS4.5-r12", "standard": "8.LS4.5", "kind": "recall", "prompt": "A risk of breeding for only one trait is", "correct": "loss of genetic variation", "distractors": ["too much variation", "faster natural selection", "making animals extinct immediately"], "why": "Breeding the same lines can reduce variation, making disease more dangerous."}, {"id": "8.LS4.5-r13", "standard": "8.LS4.5", "kind": "recall", "prompt": "Bacteria engineered to make human insulin show that", "correct": "genes can be moved between species", "distractors": ["bacteria naturally make human insulin", "insulin can only come from pigs", "cloning is the same as breeding"], "why": "The human insulin gene is inserted into bacteria, which then produce insulin."}, {"id": "8.LS4.5-r14", "standard": "8.LS4.5", "kind": "recall", "prompt": "Which is an example of artificial selection?", "correct": "breeding cows that give more milk", "distractors": ["a moth becoming camouflaged in a forest", "bacteria surviving antibiotics", "finch beaks changing after a drought"], "why": "Humans choosing parent cows is artificial. The others are natural selection."}, {"id": "8.LS4.5-r15", "standard": "8.LS4.5", "kind": "recall", "prompt": "Breeders choose parent plants because", "correct": "offspring inherit traits from parents", "distractors": ["plants learn traits from the farmers", "traits come from the soil they grow in", "offspring never resemble their parents"], "why": "Traits are inherited, so choosing parents shapes the offspring."}, {"id": "8.LS4.5-r16", "standard": "8.LS4.5", "kind": "recall", "prompt": "Golden rice was engineered to contain more vitamin A. This shows genetic engineering can", "correct": "add useful traits to crops", "distractors": ["only be used for animals", "make crops smaller", "cause natural selection"], "why": "A gene for vitamin A production was added."}, {"id": "8.LS4.5-r17", "standard": "8.LS4.5", "kind": "recall", "prompt": "Many dog breeds have health problems because", "correct": "breeding for looks reduced variation", "distractors": ["they live in the wild", "natural selection removed their health", "they are clones"], "why": "Selecting for looks, often from close relatives, can spread harmful genes."}, {"id": "8.LS4.5-r18", "standard": "8.LS4.5", "kind": "recall", "prompt": "A key difference between selective breeding and genetic engineering is that engineering", "correct": "changes DNA directly in a lab", "distractors": ["takes many more generations", "uses only wild animals", "cannot affect traits"], "why": "Breeding works over generations; engineering edits DNA directly."}, {"id": "8.LS4.5-r19", "standard": "8.LS4.5", "kind": "recall", "prompt": "Humans have used artificial selection for", "correct": "thousands of years", "distractors": ["only the last ten years", "only since computers", "only since the 1900s"], "why": "People have bred crops and animals since early farming."}, {"id": "8.LS4.5-r20", "standard": "8.LS4.5", "kind": "recall", "prompt": "Which trait would a farmer most likely select for in wheat?", "correct": "high grain yield", "distractors": ["small seeds", "weak stems", "low disease resistance"], "why": "Farmers breed for useful traits like high yield."}, {"id": "8.LS4.5-s01", "standard": "8.LS4.5", "kind": "scenario", "prompt": "A farmer breeds only the cows that give the most milk for 20 generations. What is the most likely result?", "correct": "The herd gives more milk on average.", "distractors": ["The herd gives less milk.", "The cows stop giving milk.", "Nothing changes."], "why": "Selecting high-milk parents passes the trait to more offspring."}, {"id": "8.LS4.5-s02", "standard": "8.LS4.5", "kind": "scenario", "prompt": "Scientists put a gene from a bacterium into corn so it makes its own insecticide. Which process is this?", "correct": "genetic engineering", "distractors": ["artificial selection", "natural selection", "cloning"], "why": "Inserting a gene from another species is genetic engineering."}, {"id": "8.LS4.5-s03", "standard": "8.LS4.5", "kind": "scenario", "prompt": "A student says breeding dogs and engineering bacteria are the same process. Which correction is best?", "correct": "Breeding picks parents; engineering edits DNA.", "distractors": ["They are exactly the same process.", "Breeding changes DNA directly in a lab.", "Engineering only works on dogs, not bacteria."], "why": "Both change inherited traits, but by different methods."}, {"id": "8.LS4.5-s04", "standard": "8.LS4.5", "kind": "scenario", "prompt": "A farm grows only one cloned variety of banana. A fungus spreads. Why is this a big risk?", "correct": "All the plants have the same weakness.", "distractors": ["Clones are immune to all fungi.", "The fungus only attacks wild bananas.", "Clones grow too fast for fungi."], "why": "With no genetic variation, one disease can wipe out the whole crop."}, {"id": "8.LS4.5-s05", "standard": "8.LS4.5", "kind": "scenario", "prompt": "Wild tomatoes are small. A gardener wants larger tomatoes. Which plan uses artificial selection?", "correct": "Save seeds from the largest tomatoes each year.", "distractors": ["Plant seeds from the smallest tomatoes.", "Water the plants more.", "Let insects choose the seeds."], "why": "Choosing large-fruit parents over generations leads to bigger tomatoes."}, {"id": "8.LS4.5-s06", "standard": "8.LS4.5", "kind": "scenario", "prompt": "A scientist edits a gene in a mosquito so it cannot carry malaria. What is one possible concern?", "correct": "Effects on ecosystems if the mosquitoes spread.", "distractors": ["It would make the mosquitoes much bigger.", "It would make humans immune to malaria.", "It would change the genes of people they bite."], "why": "Releasing engineered organisms may have unexpected effects on ecosystems."}, {"id": "8.LS4.5-s07", "standard": "8.LS4.5", "kind": "scenario", "prompt": "Pugs have short noses and often have breathing problems. Which explains this?", "correct": "Breeders chose short noses despite health effects.", "distractors": ["Natural selection in the wild made pugs this way.", "Pugs chose to have short noses.", "Pug noses got shorter from exercise."], "why": "Humans selected for a look, which brought health problems."}, {"id": "8.LS4.5-s08", "standard": "8.LS4.5", "kind": "scenario", "prompt": "A patient with a genetic disorder is treated by inserting a working copy of a gene into their cells. What is this?", "correct": "gene therapy", "distractors": ["selective breeding", "natural selection", "cloning a whole organism"], "why": "Gene therapy fixes or replaces faulty genes in a person."}, {"id": "8.LS4.5-s09", "standard": "8.LS4.5", "kind": "scenario", "prompt": "Two farmers want drought-tolerant corn. Farmer A breeds the plants that survive dry years. Farmer B adds a drought-tolerance gene. Which is true?", "correct": "A uses selective breeding; B uses genetic engineering.", "distractors": ["Both farmers are using natural selection.", "A uses engineering, and B uses selective breeding.", "Neither method will change the corn."], "why": "Breeding selects parents; engineering inserts a gene."}, {"id": "8.LS4.5-s10", "standard": "8.LS4.5", "kind": "scenario", "prompt": "Wild cabbage was bred into broccoli, cauliflower, and kale. What does this show?", "correct": "Artificial selection can make very different forms.", "distractors": ["These vegetables were different species from the start.", "Natural selection in the wild made each one.", "They were all made by cloning one plant."], "why": "Humans selected different traits to produce varied crops."}, {"id": "8.PS1.1-r01", "standard": "8.PS1.1", "kind": "recall", "prompt": "Where are protons and neutrons found in an atom?", "correct": "in the nucleus at the center", "distractors": ["in the electron cloud outside", "spread evenly through the atom", "orbiting in rings around the edge"], "why": "Protons and neutrons are packed in the tiny nucleus. Electrons, not protons, are found in the cloud outside."}, {"id": "8.PS1.1-r02", "standard": "8.PS1.1", "kind": "recall", "prompt": "Which particle has a negative charge?", "correct": "electron", "distractors": ["proton", "neutron", "nucleus"], "why": "Electrons are negative. Protons are positive, and neutrons have no charge, so the nucleus is positive overall."}, {"id": "8.PS1.1-r03", "standard": "8.PS1.1", "kind": "recall", "prompt": "Which particle has no electric charge?", "correct": "neutron", "distractors": ["proton", "electron", "ion"], "why": "Neutrons are neutral. An ion is a whole atom with a charge, not a particle with zero charge."}, {"id": "8.PS1.1-r04", "standard": "8.PS1.1", "kind": "recall", "prompt": "The atomic number of an element is the number of", "correct": "protons in the nucleus", "distractors": ["neutrons in the nucleus", "protons plus neutrons", "electrons plus neutrons"], "why": "Atomic number = protons. Protons plus neutrons is the mass number, not the atomic number."}, {"id": "8.PS1.1-r05", "standard": "8.PS1.1", "kind": "recall", "prompt": "The mass number of an atom equals", "correct": "protons plus neutrons", "distractors": ["protons plus electrons", "neutrons only", "electrons plus neutrons"], "why": "Electrons have almost no mass, so mass number counts the protons and neutrons in the nucleus."}, {"id": "8.PS1.1-r06", "standard": "8.PS1.1", "kind": "recall", "prompt": "Almost all of an atom's mass is in its", "correct": "nucleus", "distractors": ["electron cloud", "outer shell", "empty space"], "why": "Protons and neutrons are about 1,800 times heavier than electrons, so the nucleus holds nearly all the mass even though it is tiny."}, {"id": "8.PS1.1-r07", "standard": "8.PS1.1", "kind": "recall", "prompt": "Most of the volume of an atom is", "correct": "mostly empty space around the nucleus", "distractors": ["filled by the protons and neutrons", "filled solid with electrons", "filled with neutrons"], "why": "The nucleus is tiny. Electrons move through a much larger region, so most of an atom is empty space."}, {"id": "8.PS1.1-r08", "standard": "8.PS1.1", "kind": "recall", "prompt": "A neutral atom has", "correct": "equal numbers of protons and electrons", "distractors": ["equal numbers of protons and neutrons", "more electrons than protons", "no electrons at all"], "why": "Neutral means the positive and negative charges cancel. Neutron count does not affect charge."}, {"id": "8.PS1.1-r09", "standard": "8.PS1.1", "kind": "recall", "prompt": "An atom with 8 protons is always", "correct": "oxygen", "distractors": ["carbon", "nitrogen", "neon"], "why": "The number of protons identifies the element. Oxygen's atomic number is 8."}, {"id": "8.PS1.1-r10", "standard": "8.PS1.1", "kind": "recall", "prompt": "If an atom gains an electron, it becomes", "correct": "a negative ion", "distractors": ["a positive ion", "a different element", "a heavier element"], "why": "Gaining a negative electron makes the overall charge negative. The element only changes if the proton count changes."}, {"id": "8.PS1.1-r11", "standard": "8.PS1.1", "kind": "recall", "prompt": "If an atom loses an electron, it becomes", "correct": "a positive ion", "distractors": ["a negative ion", "a new element", "a neutral atom"], "why": "Losing a negative charge leaves more protons than electrons, so the charge becomes positive."}, {"id": "8.PS1.1-r12", "standard": "8.PS1.1", "kind": "recall", "prompt": "Atoms of the same element with different numbers of neutrons are called", "correct": "isotopes", "distractors": ["ions", "molecules", "compounds"], "why": "Isotopes differ in neutron count. Ions differ in electron count."}, {"id": "8.PS1.1-r13", "standard": "8.PS1.1", "kind": "recall", "prompt": "Which change would make an atom a DIFFERENT element?", "correct": "changing the number of protons", "distractors": ["changing the number of neutrons", "changing the number of electrons", "changing its temperature"], "why": "Only the proton count sets the element. Changing neutrons makes an isotope, and changing electrons makes an ion."}, {"id": "8.PS1.1-r14", "standard": "8.PS1.1", "kind": "recall", "prompt": "In the atomic model, electrons are found", "correct": "in a cloud around the nucleus", "distractors": ["inside the nucleus with protons", "stuck to the neutrons", "in a single fixed ring"], "why": "Today's model shows electrons in regions (a cloud) around the nucleus, not inside it."}, {"id": "8.PS1.1-r15", "standard": "8.PS1.1", "kind": "recall", "prompt": "Protons and electrons attract each other because they", "correct": "have opposite charges", "distractors": ["have the same charge", "have the same mass", "are both in the nucleus"], "why": "Opposite charges attract. Electrons are outside the nucleus, held by attraction to the positive protons."}, {"id": "8.PS1.1-r16", "standard": "8.PS1.1", "kind": "recall", "prompt": "Carbon-12 has 6 protons. How many neutrons does it have?", "correct": "6", "distractors": ["12", "18", "0"], "why": "Mass number 12 minus 6 protons = 6 neutrons."}, {"id": "8.PS1.1-r17", "standard": "8.PS1.1", "kind": "recall", "prompt": "An atom has 11 protons, 12 neutrons, and 11 electrons. Its mass number is", "correct": "23", "distractors": ["11", "22", "34"], "why": "Mass number = protons + neutrons = 11 + 12 = 23. Electrons are not counted."}, {"id": "8.PS1.1-r18", "standard": "8.PS1.1", "kind": "recall", "prompt": "An atom has 17 protons and 18 electrons. Its charge is", "correct": "−1", "distractors": ["+1", "0", "−18"], "why": "17 positive and 18 negative leaves one extra negative charge, so −1."}, {"id": "8.PS1.1-r19", "standard": "8.PS1.1", "kind": "recall", "prompt": "A scientific model of an atom is useful because it", "correct": "explains what we observe about atoms", "distractors": ["shows exactly what an atom looks like", "never needs to change", "is a photograph of an atom"], "why": "Models explain evidence and get revised. No one has a regular photo showing electrons orbiting."}, {"id": "8.PS1.1-r20", "standard": "8.PS1.1", "kind": "recall", "prompt": "Hydrogen-1 is the simplest atom. It has", "correct": "1 proton and 1 electron", "distractors": ["1 proton and 1 neutron", "2 protons and 1 electron", "1 neutron and 1 electron"], "why": "Hydrogen-1 has one proton, one electron, and no neutrons."}, {"id": "8.PS1.1-s01", "standard": "8.PS1.1", "kind": "scenario", "prompt": "A model shows 3 protons, 4 neutrons, and 2 electrons. What does the model show?", "correct": "a lithium ion with a +1 charge", "distractors": ["a neutral lithium atom", "a beryllium atom", "a lithium ion with a −1 charge"], "why": "3 protons means lithium. 3 positive minus 2 negative = +1. A neutral atom would need 3 electrons."}, {"id": "8.PS1.1-s02", "standard": "8.PS1.1", "kind": "scenario", "prompt": "Two atoms both have 6 protons. One has 6 neutrons, the other has 8. What are they?", "correct": "two isotopes of carbon", "distractors": ["two different elements", "a carbon atom and a carbon ion", "two isotopes of oxygen"], "why": "Same proton count means same element (carbon). Different neutrons means isotopes. Ions differ in electrons, not neutrons."}, {"id": "8.PS1.1-s03", "standard": "8.PS1.1", "kind": "scenario", "prompt": "A student says, \"Adding a neutron to an atom will change its charge.\" Which response is correct?", "correct": "No, neutrons have no charge, so only mass changes.", "distractors": ["Yes, the charge becomes +1 with the neutron.", "Yes, the charge becomes −1 with the neutron.", "No, but adding it changes the element."], "why": "Neutrons are neutral. Adding one raises the mass number but keeps the charge and the element the same."}, {"id": "8.PS1.1-s04", "standard": "8.PS1.1", "kind": "scenario", "prompt": "A student builds an atom model with protons orbiting outside and electrons in the center. What is the error?", "correct": "Protons belong in the nucleus and electrons outside.", "distractors": ["Neutrons should be outside with the protons.", "Electrons and protons should both be outside.", "There is no error in this model."], "why": "The nucleus holds protons and neutrons. Electrons are found in the cloud around it."}, {"id": "8.PS1.1-s05", "standard": "8.PS1.1", "kind": "scenario", "prompt": "Atom X has 9 protons and 10 neutrons. Atom Y has 10 protons and 9 neutrons. Which is true?", "correct": "They are different elements.", "distractors": ["They are isotopes of one element.", "They are the same element and ion.", "They have different mass numbers."], "why": "Proton count differs (9 vs 10), so they are different elements. Both have mass number 19."}, {"id": "8.PS1.1-s06", "standard": "8.PS1.1", "kind": "scenario", "prompt": "An atom's mass number is 40 and its atomic number is 20. How many neutrons does it have?", "correct": "20", "distractors": ["40", "60", "10"], "why": "Neutrons = mass number − atomic number = 40 − 20 = 20."}, {"id": "8.PS1.1-s07", "standard": "8.PS1.1", "kind": "scenario", "prompt": "Sodium has 11 protons. A sodium particle has 10 electrons. What best describes it?", "correct": "a sodium ion with a +1 charge", "distractors": ["a sodium ion with a −1 charge", "a neon atom with 10 electrons", "a neutral sodium atom"], "why": "It still has 11 protons, so it is sodium. One fewer electron than protons gives a +1 charge."}, {"id": "8.PS1.1-s08", "standard": "8.PS1.1", "kind": "scenario", "prompt": "A balloon of helium-4 atoms is weighed. Which particles contribute most of the mass?", "correct": "protons and neutrons", "distractors": ["electrons only", "electrons and protons equally", "the empty space in each atom"], "why": "Protons and neutrons are much heavier than electrons, so they make up nearly all the mass."}, {"id": "8.PS1.1-s09", "standard": "8.PS1.1", "kind": "scenario", "prompt": "Scientists once modeled the atom as a solid ball. Experiments showed most particles shot at gold foil passed straight through. What did this show?", "correct": "Atoms are mostly empty space with a tiny nucleus.", "distractors": ["Atoms are solid all the way through, like tiny balls.", "Atoms have no nucleus at all.", "Electrons are bigger than the nucleus."], "why": "Most particles passing through means mostly empty space. The few that bounced back hit a tiny, dense nucleus."}, {"id": "8.PS1.1-s10", "standard": "8.PS1.1", "kind": "scenario", "prompt": "A student says an atom with 2 protons, 2 neutrons, and 3 electrons is neutral helium. What is wrong?", "correct": "It has an extra electron, so it is a −1 ion.", "distractors": ["It should have 3 protons to be helium.", "It should have 4 neutrons to be neutral.", "Nothing is wrong with the claim."], "why": "2 protons is helium, but 3 electrons gives a −1 charge. Neutrons do not affect charge."}, {"id": "8.PS1.2-r01", "standard": "8.PS1.2", "kind": "recall", "prompt": "Stars produce energy mainly by", "correct": "nuclear fusion in their cores", "distractors": ["chemical burning like a fire", "nuclear fission of heavy atoms", "reflecting light from other stars"], "why": "Stars fuse light nuclei. It is not chemical burning, which only rearranges atoms and could not power a star for billions of years."}, {"id": "8.PS1.2-r02", "standard": "8.PS1.2", "kind": "recall", "prompt": "In nuclear fusion,", "correct": "light nuclei join to form a heavier nucleus", "distractors": ["a heavy nucleus splits into smaller ones", "atoms share electrons to form molecules", "electrons jump between atoms"], "why": "Fusion joins nuclei. Splitting heavy nuclei is fission, which powers nuclear plants on Earth."}, {"id": "8.PS1.2-r03", "standard": "8.PS1.2", "kind": "recall", "prompt": "In the Sun's core, hydrogen nuclei fuse to form", "correct": "helium", "distractors": ["carbon", "iron", "oxygen"], "why": "The main fusion process in the Sun turns hydrogen into helium."}, {"id": "8.PS1.2-r04", "standard": "8.PS1.2", "kind": "recall", "prompt": "Fusion is different from a chemical reaction because fusion", "correct": "changes the nuclei of atoms", "distractors": ["only rearranges electrons", "cannot release energy", "happens at low temperature"], "why": "Chemical reactions rearrange electrons and bonds. Fusion changes the nucleus, so new elements form."}, {"id": "8.PS1.2-r05", "standard": "8.PS1.2", "kind": "recall", "prompt": "Fusion requires extremely high", "correct": "temperature and pressure", "distractors": ["oxygen levels", "amounts of water", "light from other stars"], "why": "Nuclei are positive and repel. Huge heat and pressure push them close enough to fuse. No oxygen is needed, unlike fire."}, {"id": "8.PS1.2-r06", "standard": "8.PS1.2", "kind": "recall", "prompt": "When nuclei fuse, energy is released mostly as", "correct": "light and heat", "distractors": ["sound waves", "new electrons", "chemical bonds"], "why": "The energy released by fusion leaves the star as light and heat (electromagnetic radiation)."}, {"id": "8.PS1.2-r07", "standard": "8.PS1.2", "kind": "recall", "prompt": "Starlight we see is energy that came from", "correct": "fusion in the star's core", "distractors": ["the star burning wood-like fuel", "light reflected from the Moon", "electricity inside the star"], "why": "Energy from fusion travels outward and leaves the star as light."}, {"id": "8.PS1.2-r08", "standard": "8.PS1.2", "kind": "recall", "prompt": "Elements heavier than helium, like carbon and oxygen, are mostly made", "correct": "by fusion inside stars", "distractors": ["in the first seconds after the Big Bang", "by chemical reactions on planets", "by fission inside planets"], "why": "The early universe made mostly hydrogen and helium. Stars fused heavier elements later."}, {"id": "8.PS1.2-r09", "standard": "8.PS1.2", "kind": "recall", "prompt": "When a fusion reaction makes a new nucleus with more protons,", "correct": "a new element forms", "distractors": ["the same element forms", "the atom becomes an ion", "only electrons are added"], "why": "Proton count sets the element, so fusion that adds protons makes a different element."}, {"id": "8.PS1.2-r10", "standard": "8.PS1.2", "kind": "recall", "prompt": "Why must nuclei be pushed very hard to fuse?", "correct": "Their positive charges repel each other", "distractors": ["Their negative charges repel each other", "Neutrons push nuclei apart", "Electrons block them from touching"], "why": "Nuclei contain positive protons, and like charges repel."}, {"id": "8.PS1.2-r11", "standard": "8.PS1.2", "kind": "recall", "prompt": "Massive stars can fuse elements up to about", "correct": "iron", "distractors": ["helium only", "hydrogen only", "uranium"], "why": "Large stars build heavier elements in layers up to iron. Fusing iron does not release energy."}, {"id": "8.PS1.2-r12", "standard": "8.PS1.2", "kind": "recall", "prompt": "The heaviest elements, like gold, are mostly made", "correct": "in supernovas and star collisions", "distractors": ["in the Sun's core today", "by heat in Earth's core", "in ordinary fires on Earth"], "why": "Elements heavier than iron form in extreme events like supernovae and neutron star collisions."}, {"id": "8.PS1.2-r13", "standard": "8.PS1.2", "kind": "recall", "prompt": "A main-sequence star like the Sun mostly fuses", "correct": "hydrogen into helium", "distractors": ["helium into hydrogen", "carbon into hydrogen", "iron into helium"], "why": "Most of a star's life is spent fusing hydrogen into helium."}, {"id": "8.PS1.2-r14", "standard": "8.PS1.2", "kind": "recall", "prompt": "When hydrogen nuclei fuse into helium, the total mass afterward is", "correct": "slightly less; the lost mass becomes energy", "distractors": ["exactly the same as before fusion", "much greater than before fusion", "zero, because all mass is used up"], "why": "A tiny amount of mass turns into a large amount of energy during fusion."}, {"id": "8.PS1.2-r15", "standard": "8.PS1.2", "kind": "recall", "prompt": "Fusion in stars is best described as a change in", "correct": "atomic nuclei", "distractors": ["electron bonds between atoms", "the state of matter only", "the color of the gas"], "why": "Fusion is a nuclear change. Melting or color are not nuclear changes."}, {"id": "8.PS1.2-r16", "standard": "8.PS1.2", "kind": "recall", "prompt": "Which statement about fission and fusion is correct?", "correct": "Fusion joins nuclei and fission splits them", "distractors": ["Fusion splits nuclei and fission joins them", "Both only rearrange electrons", "Both happen only on Earth"], "why": "Fusion = joining (stars). Fission = splitting (nuclear power plants)."}, {"id": "8.PS1.2-r17", "standard": "8.PS1.2", "kind": "recall", "prompt": "A star's spectrum can show which elements it contains because", "correct": "each element gives its own light pattern", "distractors": ["all elements give off the same color", "stars are made only of hydrogen gas", "light can only show a star's size"], "why": "Each element has a unique spectral \"fingerprint.\""}, {"id": "8.PS1.2-r18", "standard": "8.PS1.2", "kind": "recall", "prompt": "Why does the Sun not run out of fuel quickly?", "correct": "It has lots of hydrogen to fuse", "distractors": ["It burns oxygen it pulls from space", "It burns slowly, like a candle", "It gets new fuel from comets"], "why": "The Sun has enough hydrogen to keep fusing for billions of years. It does not burn oxygen."}, {"id": "8.PS1.2-r19", "standard": "8.PS1.2", "kind": "recall", "prompt": "The carbon atoms in your body were most likely formed", "correct": "inside stars long ago", "distractors": ["in Earth's oceans", "during photosynthesis", "in Earth's core"], "why": "Carbon nuclei were fused in older stars and spread when those stars died."}, {"id": "8.PS1.2-r20", "standard": "8.PS1.2", "kind": "recall", "prompt": "Fusion is the main energy source for", "correct": "stars", "distractors": ["coal power plants", "volcanoes", "batteries"], "why": "Coal is chemical energy, volcanoes use Earth's interior heat, and batteries are chemical. Stars run on fusion."}, {"id": "8.PS1.2-s01", "standard": "8.PS1.2", "kind": "scenario", "prompt": "Two hydrogen nuclei are moving toward each other but bounce apart before touching. What would most likely help them fuse?", "correct": "higher temperature and pressure", "distractors": ["more oxygen in the area", "lower temperature", "adding more electrons"], "why": "More heat and pressure give nuclei enough speed to overcome their repulsion. Fusion does not need oxygen."}, {"id": "8.PS1.2-s02", "standard": "8.PS1.2", "kind": "scenario", "prompt": "A student says, \"The Sun is a giant ball of fire burning fuel.\" Which correction is best?", "correct": "The Sun fuses nuclei. It is not chemical burning.", "distractors": ["The Sun is correct, it burns oxygen.", "The Sun splits heavy atoms like a reactor.", "The Sun only reflects light from space."], "why": "Fire is a chemical reaction that needs oxygen. The Sun's energy comes from fusion in its core."}, {"id": "8.PS1.2-s03", "standard": "8.PS1.2", "kind": "scenario", "prompt": "A young star's spectrum shows more carbon and oxygen than a very old star's. What best explains this?", "correct": "It formed from gas enriched by earlier stars.", "distractors": ["It fused that carbon in its core this year.", "Carbon and oxygen fell in from its planets.", "Old stars burn away carbon like a fire."], "why": "A spectrum shows a star's outer gas, not its core. Earlier stars made heavy elements and spread them into space, so younger stars form from richer gas. Fusion is not chemical burning."}, {"id": "8.PS1.2-s04", "standard": "8.PS1.2", "kind": "scenario", "prompt": "A nucleus with 1 proton and 1 neutron fuses with a nucleus with 1 proton. How many protons does the new nucleus have, and what element is it?", "correct": "2 protons, so it is helium", "distractors": ["1 proton, so it is still hydrogen", "3 protons, so it is lithium", "0 protons, so it is a neutron"], "why": "1 + 1 = 2 protons, and an element with 2 protons is helium. Neutrons do not change which element it is."}, {"id": "8.PS1.2-s05", "standard": "8.PS1.2", "kind": "scenario", "prompt": "Scientists build fusion reactors on Earth that must reach millions of degrees. Why?", "correct": "Nuclei must move fast to overcome repulsion.", "distractors": ["Fusion needs fire to start the burning.", "Heat is needed to add more electrons.", "High heat turns hydrogen into oxygen."], "why": "The positive nuclei repel. Only extreme temperatures make them collide hard enough to fuse."}, {"id": "8.PS1.2-s06", "standard": "8.PS1.2", "kind": "scenario", "prompt": "A model shows two light nuclei joining and a burst of light. What does the burst stand for?", "correct": "energy released when the nuclei fuse", "distractors": ["electrons leaving the atoms", "a chemical bond forming", "the nuclei splitting apart"], "why": "Fusion releases energy that leaves as light and heat. Splitting would be fission."}, {"id": "8.PS1.2-s07", "standard": "8.PS1.2", "kind": "scenario", "prompt": "After fusion, the new nucleus has slightly less mass than the two starting nuclei. Where did the mass go?", "correct": "It changed into released energy.", "distractors": ["It turned into electrons.", "It was destroyed and lost.", "It became a new nucleus somewhere else."], "why": "Mass can be converted into energy. That released energy is what makes stars shine."}, {"id": "8.PS1.2-s08", "standard": "8.PS1.2", "kind": "scenario", "prompt": "A classmate says gold in jewelry was made in the Sun. Which evidence-based reply fits best?", "correct": "Gold forms in supernovas or star collisions.", "distractors": ["Yes, the Sun makes all of the elements.", "Gold forms in Earth's core from iron.", "Gold is made by chemical burning in stars."], "why": "Ordinary stars fuse up to iron at most. The Sun fuses mostly hydrogen into helium."}, {"id": "8.PS1.2-s09", "standard": "8.PS1.2", "kind": "scenario", "prompt": "A star has used up the hydrogen in its core. What is the next likely fuel for fusion?", "correct": "helium, fused into carbon", "distractors": ["oxygen, burned like a fire", "iron, fused into hydrogen", "nothing, since all stars stop at once"], "why": "Once core hydrogen runs low, a star can fuse helium into heavier elements like carbon."}, {"id": "8.PS1.2-s10", "standard": "8.PS1.2", "kind": "scenario", "prompt": "Which observation shows fusion is a nuclear change, not a chemical one?", "correct": "New elements appear that were not there before.", "distractors": ["The gas changes color as it heats up.", "The gas gets hotter as the reaction goes.", "The gas expands and takes up more space."], "why": "Only nuclear changes create new elements. Color and temperature changes can happen in chemical or physical changes."}, {"id": "8.PS2.1-r01", "standard": "8.PS2.1", "kind": "recall", "prompt": "Two objects with the same type of charge will", "correct": "repel each other", "distractors": ["attract each other", "have no force between them", "cancel each other's charge"], "why": "Like charges repel. Opposite charges attract."}, {"id": "8.PS2.1-r02", "standard": "8.PS2.1", "kind": "recall", "prompt": "A positive charge and a negative charge will", "correct": "attract each other", "distractors": ["repel each other", "not affect each other", "both become neutral"], "why": "Opposite charges attract. They do not instantly become neutral just by being near each other."}, {"id": "8.PS2.1-r03", "standard": "8.PS2.1", "kind": "recall", "prompt": "As two charged objects move farther apart, the electric force between them", "correct": "gets weaker", "distractors": ["gets stronger", "stays the same", "changes from attract to repel"], "why": "Electric force shrinks with distance. Distance does not change attract into repel; that depends on the charges."}, {"id": "8.PS2.1-r04", "standard": "8.PS2.1", "kind": "recall", "prompt": "Increasing the amount of charge on two objects makes the force between them", "correct": "stronger", "distractors": ["weaker", "zero", "change direction"], "why": "More charge means a stronger electric force at the same distance."}, {"id": "8.PS2.1-r05", "standard": "8.PS2.1", "kind": "recall", "prompt": "The north pole of one magnet is brought near the north pole of another. They will", "correct": "repel", "distractors": ["attract", "stick together", "have no force"], "why": "Like magnetic poles repel. North attracts south."}, {"id": "8.PS2.1-r06", "standard": "8.PS2.1", "kind": "recall", "prompt": "A north pole and a south pole will", "correct": "attract", "distractors": ["repel", "cancel out and vanish", "have no force"], "why": "Opposite poles attract."}, {"id": "8.PS2.1-r07", "standard": "8.PS2.1", "kind": "recall", "prompt": "A magnetic field is strongest", "correct": "near the poles of the magnet", "distractors": ["in the exact middle of the magnet", "far away from the magnet", "only inside the magnet"], "why": "Field lines bunch together near the poles, where the field is strongest."}, {"id": "8.PS2.1-r08", "standard": "8.PS2.1", "kind": "recall", "prompt": "Electric and magnetic forces are called non-contact forces because they", "correct": "act across a distance without touching", "distractors": ["only work when objects touch", "need air to travel through", "only act on metal objects"], "why": "Fields let these forces act at a distance. They do not need contact or air."}, {"id": "8.PS2.1-r09", "standard": "8.PS2.1", "kind": "recall", "prompt": "An electric field is", "correct": "a region where a charge feels a force", "distractors": ["a wire that carries current", "the spark you see from static", "a type of magnet"], "why": "A field is the region around a charge where other charges feel a push or pull."}, {"id": "8.PS2.1-r10", "standard": "8.PS2.1", "kind": "recall", "prompt": "Rubbing a balloon on hair moves", "correct": "electrons from one object to the other", "distractors": ["protons from the hair to the balloon", "neutrons into the balloon", "magnetism into the balloon"], "why": "Only electrons move easily between objects. Protons stay in the nuclei."}, {"id": "8.PS2.1-r11", "standard": "8.PS2.1", "kind": "recall", "prompt": "A balloon gains extra electrons. Its charge is now", "correct": "negative", "distractors": ["positive", "neutral", "magnetic"], "why": "Electrons are negative, so extra electrons make the balloon negative."}, {"id": "8.PS2.1-r12", "standard": "8.PS2.1", "kind": "recall", "prompt": "Which change would make the magnetic force on a paper clip weaker?", "correct": "moving the magnet farther away", "distractors": ["using a stronger magnet", "moving the magnet closer", "using two magnets together"], "why": "Magnetic force weakens with distance and grows with magnet strength."}, {"id": "8.PS2.1-r13", "standard": "8.PS2.1", "kind": "recall", "prompt": "Magnetic field lines go", "correct": "from the north pole to the south pole outside", "distractors": ["from the south pole to the north pole outside", "in straight lines away from both poles", "only in the space between two magnets"], "why": "By convention, field lines outside a magnet run north to south."}, {"id": "8.PS2.1-r14", "standard": "8.PS2.1", "kind": "recall", "prompt": "Iron filings around a bar magnet show", "correct": "the shape of the magnetic field", "distractors": ["the electric charge of the magnet", "the magnet's temperature", "which pole is heavier"], "why": "Filings line up along field lines, making the field pattern visible."}, {"id": "8.PS2.1-r15", "standard": "8.PS2.1", "kind": "recall", "prompt": "A charged balloon sticks to a neutral wall because", "correct": "it causes the charges in the wall to shift", "distractors": ["the wall is negatively charged", "the wall is magnetic", "gravity pulls the balloon to the wall"], "why": "The balloon's charge pushes or pulls the wall's electrons, leaving the nearby surface oppositely charged, so they attract."}, {"id": "8.PS2.1-r16", "standard": "8.PS2.1", "kind": "recall", "prompt": "A compass needle points north because it", "correct": "lines up with Earth's magnetic field", "distractors": ["is pulled by the North Star", "is attracted by electric charges", "is pulled toward the North Pole by gravity"], "why": "A compass is a small magnet that aligns with Earth's magnetic field."}, {"id": "8.PS2.1-r17", "standard": "8.PS2.1", "kind": "recall", "prompt": "Doubling the distance between two charges makes the force", "correct": "much weaker (about one-fourth)", "distractors": ["twice as strong as before", "exactly the same as before", "four times stronger than before"], "why": "Electric force drops off quickly with distance. At double the distance it is about one-fourth as strong."}, {"id": "8.PS2.1-r18", "standard": "8.PS2.1", "kind": "recall", "prompt": "The strength of an electric force depends on", "correct": "the amount of charge and the distance", "distractors": ["only the color of the objects", "only the mass of the objects", "only the temperature"], "why": "Force depends on charge and distance. Mass is what matters for gravity, not electric force."}, {"id": "8.PS2.1-r19", "standard": "8.PS2.1", "kind": "recall", "prompt": "Which objects are attracted to a magnet?", "correct": "iron nails and steel paper clips", "distractors": ["aluminum cans and copper coins", "plastic spoons and glass beads", "all metals equally"], "why": "Magnets attract iron, nickel, cobalt, and steel. Most other metals, like aluminum and copper, are not attracted."}, {"id": "8.PS2.1-r20", "standard": "8.PS2.1", "kind": "recall", "prompt": "When two magnets are pushed closer together, the force between them", "correct": "gets stronger", "distractors": ["gets weaker", "stays the same", "disappears"], "why": "Magnetic force grows as distance shrinks."}, {"id": "8.PS2.1-s01", "standard": "8.PS2.1", "kind": "scenario", "prompt": "A student holds a magnet 10 cm from a paper clip, and nothing happens. At 2 cm, the clip jumps to the magnet. What does this show?", "correct": "Magnetic force increases as distance decreases.", "distractors": ["The clip became magnetic at 2 cm only.", "Magnetic force does not depend on distance.", "The magnet got stronger at 2 cm."], "why": "The magnet did not change. The closer distance made the force strong enough to move the clip."}, {"id": "8.PS2.1-s02", "standard": "8.PS2.1", "kind": "scenario", "prompt": "Balloon A and Balloon B both are rubbed on hair and now push apart. What can you conclude?", "correct": "They have the same type of charge.", "distractors": ["They have opposite charges.", "One balloon is neutral.", "They are both magnetic."], "why": "Objects that repel have like charges. Opposite charges would attract."}, {"id": "8.PS2.1-s03", "standard": "8.PS2.1", "kind": "scenario", "prompt": "A student tests a magnet on a steel paper clip, a copper penny, and an aluminum foil ball. Only the paper clip moves. Which conclusion is best?", "correct": "Magnets attract some metals but not all.", "distractors": ["Magnets attract all metals the same way.", "The penny and foil are not really metals.", "The magnet stopped working after the clip."], "why": "Copper and aluminum are metals that magnets do not attract. Steel contains iron, which is attracted."}, {"id": "8.PS2.1-s04", "standard": "8.PS2.1", "kind": "scenario", "prompt": "Two magnets: Magnet X picks up 12 clips and Magnet Y picks up 3 clips at the same distance. Which is true?", "correct": "Magnet X has a stronger magnetic field.", "distractors": ["Magnet Y has a stronger magnetic field.", "Both have the same field strength.", "The clips caused the difference."], "why": "At the same distance, picking up more clips means a stronger field."}, {"id": "8.PS2.1-s05", "standard": "8.PS2.1", "kind": "scenario", "prompt": "Charges A and B are 2 cm apart and attract. B is moved to 8 cm away. What happens to the force?", "correct": "It still attracts but is much weaker.", "distractors": ["It changes to a repelling force.", "It stays the same strength.", "It becomes much stronger."], "why": "Distance changes how strong the force is, not whether it attracts or repels."}, {"id": "8.PS2.1-s06", "standard": "8.PS2.1", "kind": "scenario", "prompt": "A charged rod is brought near tiny bits of paper, and they jump to the rod. The paper was neutral. Why?", "correct": "The rod shifted charges in the paper.", "distractors": ["The paper had a tiny hidden magnet in it.", "Gravity from the rod pulled the paper up.", "The paper was already strongly charged."], "why": "Charged objects can attract neutral objects by shifting charges within them."}, {"id": "8.PS2.1-s07", "standard": "8.PS2.1", "kind": "scenario", "prompt": "A student says, \"Magnets only work when they touch something.\" Which evidence disproves this?", "correct": "A magnet moves a clip through a sheet of paper.", "distractors": ["A magnet sticks firmly to a fridge door.", "Two magnets snap together when touching.", "A magnet feels heavy when you hold it."], "why": "The clip moves without contact, showing a magnetic field acts at a distance."}, {"id": "8.PS2.1-s08", "standard": "8.PS2.1", "kind": "scenario", "prompt": "An investigation measures the force between two charged spheres at 1, 2, and 3 cm. What is the independent variable?", "correct": "the distance between the spheres", "distractors": ["the force between the spheres", "the color of the spheres", "the size of the table"], "why": "The variable the investigator changes on purpose is distance. Force is what gets measured."}, {"id": "8.PS2.1-s09", "standard": "8.PS2.1", "kind": "scenario", "prompt": "Iron filings around two magnets curve from one magnet to the other. What does this pattern show?", "correct": "Opposite poles face each other and attract.", "distractors": ["Like poles face each other and repel.", "The magnets have no field.", "The magnets are electrically charged."], "why": "Field lines that connect between magnets show opposite poles attracting. Like poles push the lines apart."}, {"id": "8.PS2.1-s10", "standard": "8.PS2.1", "kind": "scenario", "prompt": "A balloon rubbed on wool sticks to a wall for 10 minutes, then falls. What is the most likely reason?", "correct": "The extra charge slowly leaked away.", "distractors": ["The wall became a magnet.", "The balloon got heavier as it sat.", "The balloon gained more charge."], "why": "As charge leaks away into the air, the attraction gets weaker until gravity wins."}, {"id": "8.PS2.2-r01", "standard": "8.PS2.2", "kind": "recall", "prompt": "An electromagnet is made by", "correct": "running current through a coil of wire", "distractors": ["rubbing a nail on wool many times", "heating a bar magnet over a flame", "freezing a piece of iron in ice"], "why": "Current through a coil creates a magnetic field. Rubbing builds static charge, not an electromagnet."}, {"id": "8.PS2.2-r02", "standard": "8.PS2.2", "kind": "recall", "prompt": "Increasing the current in an electromagnet makes it", "correct": "stronger", "distractors": ["weaker", "lose its poles", "stop working"], "why": "More current makes a stronger magnetic field."}, {"id": "8.PS2.2-r03", "standard": "8.PS2.2", "kind": "recall", "prompt": "Adding more loops of wire to an electromagnet's coil makes it", "correct": "stronger", "distractors": ["weaker", "turn off", "change into a battery"], "why": "More turns of wire add up to a stronger field."}, {"id": "8.PS2.2-r04", "standard": "8.PS2.2", "kind": "recall", "prompt": "Putting an iron core inside the coil of an electromagnet", "correct": "makes the magnet stronger", "distractors": ["makes the magnet weaker", "removes the magnetic field", "turns the current off"], "why": "Iron concentrates the magnetic field, making the electromagnet stronger."}, {"id": "8.PS2.2-r05", "standard": "8.PS2.2", "kind": "recall", "prompt": "When the current to an electromagnet is turned off,", "correct": "its magnetic field mostly goes away", "distractors": ["it becomes a stronger magnet", "it becomes a permanent magnet", "its field stays exactly the same"], "why": "Electromagnets can be switched off. That is their big advantage over permanent magnets."}, {"id": "8.PS2.2-r06", "standard": "8.PS2.2", "kind": "recall", "prompt": "An electric motor changes", "correct": "electrical energy into motion", "distractors": ["motion into electrical energy", "heat into electrical energy", "light into electrical energy"], "why": "Motors turn electrical energy into motion. Generators do the reverse."}, {"id": "8.PS2.2-r07", "standard": "8.PS2.2", "kind": "recall", "prompt": "A generator changes", "correct": "motion into electrical energy", "distractors": ["electrical energy into motion", "electrical energy into light only", "heat into motion"], "why": "Generators spin a coil and magnet to make current."}, {"id": "8.PS2.2-r08", "standard": "8.PS2.2", "kind": "recall", "prompt": "Moving a magnet in and out of a coil of wire", "correct": "produces an electric current in the wire", "distractors": ["stops all current already in the wire", "turns the magnet into plain iron", "makes the coil of wire heavier"], "why": "A changing magnetic field near a coil produces current. This is how generators work."}, {"id": "8.PS2.2-r09", "standard": "8.PS2.2", "kind": "recall", "prompt": "Reversing the direction of current in an electromagnet", "correct": "switches its north and south poles", "distractors": ["makes it twice as strong", "turns it into a permanent magnet", "has no effect"], "why": "Current direction sets which end is north."}, {"id": "8.PS2.2-r10", "standard": "8.PS2.2", "kind": "recall", "prompt": "A wire carrying electric current", "correct": "has a magnetic field around it", "distractors": ["has no magnetic field", "becomes a permanent magnet", "only makes heat"], "why": "Any current produces a magnetic field around the wire."}, {"id": "8.PS2.2-r11", "standard": "8.PS2.2", "kind": "recall", "prompt": "One advantage of an electromagnet over a permanent magnet is that it", "correct": "can be turned on and off", "distractors": ["is always stronger", "does not need any electricity", "never makes heat"], "why": "Being able to switch it off lets cranes pick up and drop scrap metal."}, {"id": "8.PS2.2-r12", "standard": "8.PS2.2", "kind": "recall", "prompt": "In a motor, a coil spins because", "correct": "magnetic forces push and pull on the coil", "distractors": ["gravity pulls the coil down each turn", "heat makes the coil expand and turn", "static charge builds up on the coil"], "why": "Current in the coil makes it a magnet, which is pushed and pulled by nearby magnets."}, {"id": "8.PS2.2-r13", "standard": "8.PS2.2", "kind": "recall", "prompt": "Which device uses an electromagnet?", "correct": "a doorbell", "distractors": ["a candle", "a flashlight bulb only", "a plastic ruler"], "why": "A doorbell uses an electromagnet to pull a striker against a bell."}, {"id": "8.PS2.2-r14", "standard": "8.PS2.2", "kind": "recall", "prompt": "Which material makes the best core for an electromagnet?", "correct": "iron", "distractors": ["plastic", "wood", "glass"], "why": "Iron is easily magnetized and strengthens the field. Plastic, wood, and glass do not."}, {"id": "8.PS2.2-r15", "standard": "8.PS2.2", "kind": "recall", "prompt": "A generator at a power plant spins because of", "correct": "steam, water, or wind turning a turbine", "distractors": ["electricity flowing into it from homes", "the Sun's magnetic field reaching it", "batteries stored inside of it"], "why": "Something must provide motion; the generator turns that motion into electrical energy."}, {"id": "8.PS2.2-r16", "standard": "8.PS2.2", "kind": "recall", "prompt": "Spinning a generator faster usually", "correct": "produces more electric current", "distractors": ["produces less current", "stops the current", "reverses the poles of the magnet"], "why": "Faster changes in the magnetic field produce more current."}, {"id": "8.PS2.2-r17", "standard": "8.PS2.2", "kind": "recall", "prompt": "An electromagnet with no current through it acts like", "correct": "a coil of wire with no magnetic field", "distractors": ["a strong permanent magnet", "a battery that stores energy", "a generator that makes current"], "why": "No current means no magnetic field from the coil."}, {"id": "8.PS2.2-r18", "standard": "8.PS2.2", "kind": "recall", "prompt": "A speaker uses an electromagnet to", "correct": "make a cone vibrate and create sound", "distractors": ["store electrical energy for later", "make light for the room", "cool the air around it"], "why": "Changing current makes the electromagnet push and pull a cone, producing sound waves."}, {"id": "8.PS2.2-r19", "standard": "8.PS2.2", "kind": "recall", "prompt": "Which change would make an electromagnet WEAKER?", "correct": "using fewer coils of wire", "distractors": ["adding more coils of wire", "adding an iron core", "using more current"], "why": "Fewer coils means a weaker field."}, {"id": "8.PS2.2-r20", "standard": "8.PS2.2", "kind": "recall", "prompt": "Electricity and magnetism are related because", "correct": "currents make magnetic fields", "distractors": ["magnets create static charges", "they are the same as gravity", "both are kinds of light only"], "why": "Current creates magnetic fields, and changing magnetic fields create current."}, {"id": "8.PS2.2-s01", "standard": "8.PS2.2", "kind": "scenario", "prompt": "A student wraps 10 loops of wire around a nail and picks up 4 paper clips. With 20 loops, she picks up 9. What does the data show?", "correct": "More loops make a stronger electromagnet.", "distractors": ["Fewer loops make a stronger magnet.", "The number of loops does not matter.", "The nail got heavier with more loops."], "why": "Doubling the loops more than doubled the clips held, showing more coils make the magnet stronger."}, {"id": "8.PS2.2-s02", "standard": "8.PS2.2", "kind": "scenario", "prompt": "An electromagnet holds 5 clips. The battery is replaced with a weaker one. What will most likely happen?", "correct": "It will hold fewer clips.", "distractors": ["It will hold more clips.", "It will hold the same number.", "It will repel the clips."], "why": "A weaker battery gives less current, so the magnetic field is weaker."}, {"id": "8.PS2.2-s03", "standard": "8.PS2.2", "kind": "scenario", "prompt": "A scrapyard crane uses an electromagnet to lift cars and drop them in a pile. Why not use a permanent magnet?", "correct": "The crane must turn the magnet off to drop cars.", "distractors": ["Permanent magnets cannot lift any metal.", "Permanent magnets are always too weak.", "Electromagnets do not use electricity."], "why": "Switching off the current releases the load. A permanent magnet would not let go."}, {"id": "8.PS2.2-s04", "standard": "8.PS2.2", "kind": "scenario", "prompt": "A student moves a magnet into a coil connected to a meter. The needle moves. When the magnet stops, the needle returns to zero. Why?", "correct": "Current flows only while the field changes.", "distractors": ["The magnet ran out of magnetic energy.", "The coil became a permanent magnet.", "The meter only works for one second."], "why": "A still magnet does not change the field in the coil, so no current is made."}, {"id": "8.PS2.2-s05", "standard": "8.PS2.2", "kind": "scenario", "prompt": "Which test would show whether an iron core strengthens an electromagnet?", "correct": "Count clips held with and without the core, same coils and current.", "distractors": ["Count clips held with more coils and a bigger battery at once.", "Use a plastic core and a stronger battery.", "Measure the nail's length only."], "why": "To test one variable, change only the core and keep coils and current the same."}, {"id": "8.PS2.2-s06", "standard": "8.PS2.2", "kind": "scenario", "prompt": "A motor spins too slowly. Which change would most likely make it spin faster?", "correct": "Increase the current through the coil.", "distractors": ["Remove the magnets from the motor.", "Use a coil made of plastic instead.", "Reduce the current through the coil."], "why": "More current makes the magnetic forces in the motor stronger."}, {"id": "8.PS2.2-s07", "standard": "8.PS2.2", "kind": "scenario", "prompt": "A generator in a wind turbine stops making electricity on a calm day. Why?", "correct": "Without wind, the turbine doesn't spin.", "distractors": ["Wind provides the electrons for the current.", "The magnets turn off when there is no wind.", "Calm air blocks the generator's magnetic field."], "why": "Generators need motion to make current. No wind means no spinning."}, {"id": "8.PS2.2-s08", "standard": "8.PS2.2", "kind": "scenario", "prompt": "An electromagnet's north end attracts a compass's south end. The battery is flipped around. What happens next?", "correct": "That end now repels the compass's south end.", "distractors": ["That end now attracts the compass more strongly.", "Nothing changes, because poles stay the same.", "The electromagnet turns off completely."], "why": "Reversing current swaps the poles, so the end becomes south and repels the compass's south end."}, {"id": "8.PS2.2-s09", "standard": "8.PS2.2", "kind": "scenario", "prompt": "A student says, \"A motor and a generator are the same thing.\" What is the most accurate response?", "correct": "They use the same parts but change energy in opposite ways.", "distractors": ["Yes, they are exactly the same and do the same job.", "No, because generators do not use any magnets.", "No, because motors do not use any coils of wire."], "why": "Motors turn electrical energy into motion; generators turn motion into electrical energy."}, {"id": "8.PS2.2-s10", "standard": "8.PS2.2", "kind": "scenario", "prompt": "Two electromagnets: A has 30 coils and 1 battery; B has 30 coils and 2 batteries. Which statement is best?", "correct": "B is stronger because it has more current.", "distractors": ["A is stronger because it has less current.", "They are the same because coils match.", "B is weaker because batteries cancel out."], "why": "With the same coils, more current (more batteries in series) makes a stronger field."}, {"id": "8.PS2.3-r01", "standard": "8.PS2.3", "kind": "recall", "prompt": "Gravity between two objects is always", "correct": "attractive", "distractors": ["repulsive", "either attractive or repulsive", "zero in space"], "why": "Gravity only pulls. Electric and magnetic forces can repel, but gravity cannot."}, {"id": "8.PS2.3-r02", "standard": "8.PS2.3", "kind": "recall", "prompt": "The gravitational force between two objects depends on", "correct": "their masses and the distance between them", "distractors": ["only their sizes, not their masses", "only how fast they are moving", "only their electric charges"], "why": "More mass means more pull; more distance means less pull. Charge affects electric force, not gravity."}, {"id": "8.PS2.3-r03", "standard": "8.PS2.3", "kind": "recall", "prompt": "If the mass of one object increases, the gravitational force between it and another object", "correct": "increases", "distractors": ["decreases", "stays the same", "turns into a push"], "why": "More mass means a stronger gravitational pull."}, {"id": "8.PS2.3-r04", "standard": "8.PS2.3", "kind": "recall", "prompt": "If two objects move farther apart, the gravitational force between them", "correct": "decreases", "distractors": ["increases", "stays the same", "becomes a push"], "why": "Gravity weakens with distance but never becomes zero or a push."}, {"id": "8.PS2.3-r05", "standard": "8.PS2.3", "kind": "recall", "prompt": "Why does Earth's gravity hold the Moon in orbit?", "correct": "Earth's mass pulls on the Moon", "distractors": ["The Moon is magnetic", "The Moon is attached by air", "The Moon has no mass"], "why": "Earth's large mass pulls the Moon toward it, keeping it in orbit."}, {"id": "8.PS2.3-r06", "standard": "8.PS2.3", "kind": "recall", "prompt": "Astronauts float on the space station because", "correct": "they and the station are falling around Earth", "distractors": ["there is no gravity at all in space", "the station has a magnet that holds them", "they have lost their mass in orbit"], "why": "Gravity is still strong at the station's height. Everything falls around Earth together, so astronauts float."}, {"id": "8.PS2.3-r07", "standard": "8.PS2.3", "kind": "recall", "prompt": "Your weight on the Moon is less than on Earth because", "correct": "the Moon has less mass", "distractors": ["the Moon has no gravity", "you have less mass on the Moon", "the Moon is closer to the Sun"], "why": "Your mass stays the same. The Moon's smaller mass gives a weaker pull."}, {"id": "8.PS2.3-r08", "standard": "8.PS2.3", "kind": "recall", "prompt": "Mass is", "correct": "the amount of matter in an object", "distractors": ["the pull of gravity on an object", "the same as volume", "how fast an object moves"], "why": "Weight is the gravitational pull; mass is the amount of matter."}, {"id": "8.PS2.3-r09", "standard": "8.PS2.3", "kind": "recall", "prompt": "Weight is", "correct": "the force of gravity on an object", "distractors": ["the amount of matter in an object", "the space an object takes up", "always the same everywhere"], "why": "Weight changes with the planet's gravity; mass does not."}, {"id": "8.PS2.3-r10", "standard": "8.PS2.3", "kind": "recall", "prompt": "The Sun's gravity keeps the planets", "correct": "in orbit around it", "distractors": ["stuck in one place", "moving away from it", "spinning on their axes"], "why": "The Sun's huge mass pulls on the planets, holding them in orbit."}, {"id": "8.PS2.3-r11", "standard": "8.PS2.3", "kind": "recall", "prompt": "Which pair has the STRONGEST gravitational pull between them?", "correct": "two large masses close together", "distractors": ["two small masses close together", "two large masses far apart", "two small masses far apart"], "why": "Large masses and short distance both increase gravitational force."}, {"id": "8.PS2.3-r12", "standard": "8.PS2.3", "kind": "recall", "prompt": "Ocean tides on Earth are mainly caused by", "correct": "the Moon's gravity", "distractors": ["Earth's magnetic field", "wind blowing across the ocean", "the Sun's light"], "why": "The Moon's pull on Earth's oceans causes the regular rise and fall of tides."}, {"id": "8.PS2.3-r13", "standard": "8.PS2.3", "kind": "recall", "prompt": "Gravity acts on objects", "correct": "even when they are not touching", "distractors": ["only when they touch", "only on Earth", "only on large planets"], "why": "Gravity is a non-contact force that acts across space."}, {"id": "8.PS2.3-r14", "standard": "8.PS2.3", "kind": "recall", "prompt": "A small object like a pencil has gravity that is", "correct": "real but very weak", "distractors": ["zero", "stronger than Earth's", "repulsive"], "why": "Every mass has gravity, but small masses have extremely weak pull."}, {"id": "8.PS2.3-r15", "standard": "8.PS2.3", "kind": "recall", "prompt": "Jupiter has more gravity than Earth because Jupiter has", "correct": "much more mass", "distractors": ["a faster spin", "more moons", "a colder surface"], "why": "More mass means stronger gravity."}, {"id": "8.PS2.3-r16", "standard": "8.PS2.3", "kind": "recall", "prompt": "Which is the best evidence that gravity acts at a distance?", "correct": "The Moon orbits Earth without touching it", "distractors": ["A ball rolls slowly across a floor", "A magnet sticks firmly to a fridge", "A book rests on top of a desk"], "why": "The Moon is far away but still pulled into orbit."}, {"id": "8.PS2.3-r17", "standard": "8.PS2.3", "kind": "recall", "prompt": "If a planet had twice Earth's mass but the same size, your weight there would be", "correct": "greater than on Earth", "distractors": ["less than on Earth", "the same as on Earth", "zero"], "why": "More mass at the same distance means a stronger pull."}, {"id": "8.PS2.3-r18", "standard": "8.PS2.3", "kind": "recall", "prompt": "Your mass on Mars compared with Earth would be", "correct": "the same", "distractors": ["less", "greater", "zero"], "why": "Mass does not change between planets. Only weight changes."}, {"id": "8.PS2.3-r19", "standard": "8.PS2.3", "kind": "recall", "prompt": "Gravity pulls objects toward", "correct": "the center of the planet", "distractors": ["the nearest wall", "down toward the ground in one direction everywhere", "the sky"], "why": "Gravity pulls toward the center of the mass."}, {"id": "8.PS2.3-r20", "standard": "8.PS2.3", "kind": "recall", "prompt": "Why don't you feel the gravitational pull of the person next to you?", "correct": "Their mass is too small to notice", "distractors": ["People have no gravity", "Gravity only acts on planets", "Their gravity pushes you away"], "why": "Everyone has mass, so everyone has gravity, but it is tiny compared to Earth's."}, {"id": "8.PS2.3-s01", "standard": "8.PS2.3", "kind": "scenario", "prompt": "A probe travels away from Earth toward Mars. What happens to Earth's gravitational pull on the probe?", "correct": "It gets weaker as the distance increases.", "distractors": ["It gets stronger as distance increases.", "It suddenly drops to zero in space.", "It turns into a push."], "why": "Gravity weakens with distance but never fully disappears or becomes a push."}, {"id": "8.PS2.3-s02", "standard": "8.PS2.3", "kind": "scenario", "prompt": "A student weighs 450 N on Earth and 75 N on the Moon. What is the best explanation?", "correct": "The Moon has less mass, so its gravity is weaker.", "distractors": ["The student lost a lot of mass on the Moon.", "The Moon has no gravity at all.", "The student is farther from the Sun there."], "why": "The student's mass is the same. The Moon's weaker gravity gives a smaller weight."}, {"id": "8.PS2.3-s03", "standard": "8.PS2.3", "kind": "scenario", "prompt": "Planet A and Planet B are the same size. Planet A has 3 times the mass. Where would an object weigh more?", "correct": "Planet A", "distractors": ["Planet B", "They would weigh the same", "Neither, objects have no weight in space"], "why": "More mass at the same size means stronger gravity."}, {"id": "8.PS2.3-s04", "standard": "8.PS2.3", "kind": "scenario", "prompt": "A student says, \"There is no gravity on the space station, which is why astronauts float.\" Which reply is correct?", "correct": "Gravity is still there; they float because they're falling.", "distractors": ["Correct, gravity stops once you are above the air.", "Correct, space has no mass, so it has no gravity.", "The station has magnets that hold them in place."], "why": "At the station's height, gravity is about 90% as strong as on the ground. Free fall makes them float."}, {"id": "8.PS2.3-s05", "standard": "8.PS2.3", "kind": "scenario", "prompt": "Two moons orbit a planet. Moon X is closer than Moon Y. They have equal mass. Which feels the stronger pull from the planet?", "correct": "Moon X", "distractors": ["Moon Y", "They feel equal pulls", "Neither feels any pull"], "why": "Closer distance means stronger gravitational force."}, {"id": "8.PS2.3-s06", "standard": "8.PS2.3", "kind": "scenario", "prompt": "Data: Mercury, Earth, Jupiter. Jupiter has the most mass and the strongest surface gravity. Which conclusion fits?", "correct": "More mass is linked to stronger gravity.", "distractors": ["Distance from the Sun sets gravity.", "Gravity depends on a planet's color.", "Smaller planets have stronger gravity."], "why": "The data link greater mass to greater gravity."}, {"id": "8.PS2.3-s07", "standard": "8.PS2.3", "kind": "scenario", "prompt": "A student drops a feather and a hammer on the Moon, where there is no air. What happens?", "correct": "They hit the ground at the same time.", "distractors": ["The hammer falls much faster.", "The feather floats away.", "Neither falls because there is no air."], "why": "With no air resistance, gravity makes all objects fall at the same rate. Gravity does not need air."}, {"id": "8.PS2.3-s08", "standard": "8.PS2.3", "kind": "scenario", "prompt": "Why does the Moon not fly off into space?", "correct": "Earth's gravity keeps pulling it toward Earth.", "distractors": ["The Moon is too heavy to move away.", "Air pushes the Moon back toward Earth.", "The Sun pushes the Moon toward Earth."], "why": "Gravity provides the pull that bends the Moon's path into an orbit."}, {"id": "8.PS2.3-s09", "standard": "8.PS2.3", "kind": "scenario", "prompt": "If the Moon were moved twice as far from Earth, what would happen to their gravitational pull?", "correct": "It would be weaker.", "distractors": ["It would be stronger.", "It would stay the same.", "It would become a push."], "why": "Greater distance means weaker gravitational force."}, {"id": "8.PS2.3-s10", "standard": "8.PS2.3", "kind": "scenario", "prompt": "An object has a mass of 10 kg on Earth. It is taken to Jupiter. Which is true?", "correct": "Its mass is 10 kg but its weight is greater.", "distractors": ["Its mass and weight are both greater.", "Its mass is greater, weight is the same.", "Its mass and weight are both less."], "why": "Mass stays the same. Jupiter's stronger gravity increases the weight."}, {"id": "8.PS2.4-r01", "standard": "8.PS2.4", "kind": "recall", "prompt": "A frame of reference is", "correct": "the viewpoint used to describe motion", "distractors": ["the speed of an object that moves", "the force acting on an object", "the mass of the moving object"], "why": "Motion is always described relative to something, called a frame of reference."}, {"id": "8.PS2.4-r02", "standard": "8.PS2.4", "kind": "recall", "prompt": "You sit on a moving bus. Compared with the bus, you are", "correct": "not moving", "distractors": ["moving fast", "moving backward", "speeding up"], "why": "In the bus's frame, you stay in the same spot."}, {"id": "8.PS2.4-r03", "standard": "8.PS2.4", "kind": "recall", "prompt": "You sit on a moving bus. Compared with the road, you are", "correct": "moving", "distractors": ["not moving", "moving backward", "floating"], "why": "Relative to the road, you move along with the bus."}, {"id": "8.PS2.4-r04", "standard": "8.PS2.4", "kind": "recall", "prompt": "Motion is relative, which means", "correct": "it depends on what you compare it to", "distractors": ["it is the same for everyone", "it can only be measured on Earth", "objects never truly move"], "why": "Different observers can describe the same motion differently."}, {"id": "8.PS2.4-r05", "standard": "8.PS2.4", "kind": "recall", "prompt": "A passenger on a train drops a ball. To the passenger, the ball falls", "correct": "straight down", "distractors": ["backward in a curve", "forward in a curve", "upward"], "why": "The passenger and ball move together, so it looks straight down."}, {"id": "8.PS2.4-r06", "standard": "8.PS2.4", "kind": "recall", "prompt": "A person on the platform watches the ball dropped on the moving train. The ball's path looks", "correct": "curved forward with the train", "distractors": ["straight down, the same as the passenger sees", "curved backward, behind the train", "perfectly still in the air"], "why": "The ball keeps the train's forward motion, so from the ground it moves forward as it falls."}, {"id": "8.PS2.4-r07", "standard": "8.PS2.4", "kind": "recall", "prompt": "A reference point is", "correct": "an object used to compare position or motion", "distractors": ["always the Sun, for every kind of motion", "the fastest-moving object in view", "any object that is moving"], "why": "A reference point is what you measure from. It is usually treated as not moving."}, {"id": "8.PS2.4-r08", "standard": "8.PS2.4", "kind": "recall", "prompt": "Which is the best reference point to tell if a car is moving?", "correct": "a tree beside the road", "distractors": ["a passenger inside the car", "the car's steering wheel", "another car moving at the same speed"], "why": "The tree is fixed to the ground. Objects moving with the car would make it seem still."}, {"id": "8.PS2.4-r09", "standard": "8.PS2.4", "kind": "recall", "prompt": "Two cars drive side by side at the same speed. To each driver, the other car seems", "correct": "not to be moving", "distractors": ["to be moving fast forward", "to be moving backward", "to be speeding up"], "why": "With the same velocity, they stay in the same spot relative to each other."}, {"id": "8.PS2.4-r10", "standard": "8.PS2.4", "kind": "recall", "prompt": "You walk forward at 1 m/s on a train moving at 20 m/s. To someone on the ground, you move at", "correct": "21 m/s", "distractors": ["20 m/s", "19 m/s", "1 m/s"], "why": "Moving in the same direction, speeds add: 20 + 1 = 21 m/s."}, {"id": "8.PS2.4-r11", "standard": "8.PS2.4", "kind": "recall", "prompt": "You walk toward the back of a train at 1 m/s. The train moves at 20 m/s. To the ground, you move at", "correct": "19 m/s forward", "distractors": ["21 m/s forward", "1 m/s backward", "20 m/s forward"], "why": "Opposite directions subtract: 20 − 1 = 19 m/s forward."}, {"id": "8.PS2.4-r12", "standard": "8.PS2.4", "kind": "recall", "prompt": "From Earth, the Sun seems to move across the sky because", "correct": "Earth is rotating", "distractors": ["the Sun orbits Earth daily", "clouds move the Sun", "the Sun is falling"], "why": "Earth spins, so from our frame of reference the Sun appears to move."}, {"id": "8.PS2.4-r13", "standard": "8.PS2.4", "kind": "recall", "prompt": "An object's position is described", "correct": "relative to a reference point", "distractors": ["without any reference point", "only by its speed", "only by its mass"], "why": "Position always needs a reference, like \"3 m left of the door.\""}, {"id": "8.PS2.4-r14", "standard": "8.PS2.4", "kind": "recall", "prompt": "Which statement about two observers describing the same motion is true?", "correct": "Both can be correct from their own frame", "distractors": ["Only the faster one is correct", "Only the one on the ground is correct", "Neither can describe motion"], "why": "Each description is correct for that observer's frame."}, {"id": "8.PS2.4-r15", "standard": "8.PS2.4", "kind": "recall", "prompt": "A parked car is moving relative to", "correct": "the Sun", "distractors": ["the road", "the parking lot", "the curb"], "why": "Relative to the ground, the car is still. Relative to the Sun, Earth carries it along."}, {"id": "8.PS2.4-r16", "standard": "8.PS2.4", "kind": "recall", "prompt": "Velocity includes", "correct": "speed and direction", "distractors": ["only speed", "only distance", "only time"], "why": "Direction matters, so velocity can change even when speed stays the same."}, {"id": "8.PS2.4-r17", "standard": "8.PS2.4", "kind": "recall", "prompt": "On a moving escalator, a person standing still is moving relative to", "correct": "the building's floor", "distractors": ["the step they stand on", "their own backpack", "the handrail moving with them"], "why": "They move with the escalator but change position relative to the floor."}, {"id": "8.PS2.4-r18", "standard": "8.PS2.4", "kind": "recall", "prompt": "A pilot flying at the same speed beside another plane sees it as", "correct": "nearly still", "distractors": ["moving very fast", "moving backward fast", "falling"], "why": "Matching velocity makes the other plane appear still."}, {"id": "8.PS2.4-r19", "standard": "8.PS2.4", "kind": "recall", "prompt": "A bird flies 5 m/s against a 5 m/s headwind. Compared with the ground, the bird", "correct": "stays in place", "distractors": ["moves 10 m/s forward", "moves 5 m/s forward", "moves 10 m/s backward"], "why": "5 m/s forward minus 5 m/s back = 0 relative to the ground."}, {"id": "8.PS2.4-r20", "standard": "8.PS2.4", "kind": "recall", "prompt": "Why do we usually use the ground as a reference point?", "correct": "It seems still to most people on Earth", "distractors": ["It is the only correct reference point", "It is always moving the fastest", "It has no mass, so it can't move"], "why": "The ground is convenient, not the only correct reference point."}, {"id": "8.PS2.4-s01", "standard": "8.PS2.4", "kind": "scenario", "prompt": "Maria sits in a moving car and sees a tree \"move backward.\" What best explains this?", "correct": "In her frame, the car is still.", "distractors": ["The tree is actually moving backward.", "The car is moving backward on the road.", "Her eyes are playing tricks on her."], "why": "From inside the car, she uses the car as her reference, so the ground and tree seem to move."}, {"id": "8.PS2.4-s02", "standard": "8.PS2.4", "kind": "scenario", "prompt": "Jake on a train tosses a ball straight up. His friend on the platform sees the ball move forward in an arch. Who is correct?", "correct": "Both, because motion depends on the frame.", "distractors": ["Only Jake, because he is closer to the ball.", "Only the friend, because the ground is still.", "Neither, because the ball didn't really move."], "why": "Each describes the motion correctly from their own frame of reference."}, {"id": "8.PS2.4-s03", "standard": "8.PS2.4", "kind": "scenario", "prompt": "Two trains sit at a station. One starts moving, and a passenger on the other feels like her train is moving. Why?", "correct": "Without a fixed reference, motion is hard to tell.", "distractors": ["Her train is actually moving out of the station.", "Both trains started moving at the same time.", "Gravity pushed her train backward a little."], "why": "She compared to the other train instead of the ground, so it seemed her train moved."}, {"id": "8.PS2.4-s04", "standard": "8.PS2.4", "kind": "scenario", "prompt": "A boat moves 4 m/s downstream in a river flowing 2 m/s. What is the boat's speed relative to the shore?", "correct": "6 m/s", "distractors": ["2 m/s", "4 m/s", "8 m/s"], "why": "Moving the same direction, speeds add: 4 + 2 = 6 m/s."}, {"id": "8.PS2.4-s05", "standard": "8.PS2.4", "kind": "scenario", "prompt": "An astronaut on the space station says the station is still. A person on Earth says it moves 7.7 km/s. Who is right?", "correct": "Both, from their own frames of reference.", "distractors": ["Only the person on Earth.", "Only the astronaut.", "Neither, because space has no motion."], "why": "Relative to the astronaut, the station is still; relative to Earth, it moves fast."}, {"id": "8.PS2.4-s06", "standard": "8.PS2.4", "kind": "scenario", "prompt": "A runner and a bicycle move east. The runner goes 3 m/s and the bike goes 8 m/s. How does the runner seem to move to the cyclist?", "correct": "5 m/s west", "distractors": ["11 m/s east", "5 m/s east", "3 m/s east"], "why": "The bike moves 5 m/s faster, so from the bike, the runner appears to fall back (west) at 5 m/s."}, {"id": "8.PS2.4-s07", "standard": "8.PS2.4", "kind": "scenario", "prompt": "A video shows a ball rolling across a table. The camera is moving with the ball. In the video, the ball looks", "correct": "still while the table moves", "distractors": ["faster than it really is", "still and the table is still", "moving backward through the table"], "why": "The camera moves with the ball, so the ball stays in frame while the table slides by."}, {"id": "8.PS2.4-s08", "standard": "8.PS2.4", "kind": "scenario", "prompt": "A student says, \"The Sun rises because it travels around Earth.\" What does the frame-of-reference idea suggest instead?", "correct": "Earth's spin makes the Sun appear to move.", "distractors": ["The Sun really orbits Earth daily.", "Clouds carry the Sun across the sky.", "Earth stays still and the Sun spins."], "why": "From Earth's rotating frame, the still Sun seems to rise and set."}, {"id": "8.PS2.4-s09", "standard": "8.PS2.4", "kind": "scenario", "prompt": "A plane flies 200 km/h north with a 50 km/h tailwind from the south. What is its ground speed?", "correct": "250 km/h north", "distractors": ["150 km/h north", "200 km/h north", "50 km/h north"], "why": "A tailwind adds to the plane's speed: 200 + 50 = 250 km/h."}, {"id": "8.PS2.4-s10", "standard": "8.PS2.4", "kind": "scenario", "prompt": "Two cars pass each other going opposite ways at 30 m/s each. To one driver, how fast does the other car seem to move?", "correct": "60 m/s", "distractors": ["30 m/s", "0 m/s", "15 m/s"], "why": "Opposite directions add relative speeds: 30 + 30 = 60 m/s."}, {"id": "8.PS2.5-r01", "standard": "8.PS2.5", "kind": "recall", "prompt": "Net force is", "correct": "the combined effect of all forces on an object", "distractors": ["the largest single force on an object", "the force of gravity only", "the force of friction only"], "why": "Net force adds all forces, including their directions."}, {"id": "8.PS2.5-r02", "standard": "8.PS2.5", "kind": "recall", "prompt": "When forces on an object are balanced, the net force is", "correct": "zero", "distractors": ["equal to the largest force", "always positive", "equal to the mass"], "why": "Balanced forces cancel, so the net force is zero."}, {"id": "8.PS2.5-r03", "standard": "8.PS2.5", "kind": "recall", "prompt": "An object with balanced forces on it will", "correct": "keep its current motion", "distractors": ["always stop", "always speed up", "always turn"], "why": "Zero net force means no change in motion. A moving object keeps moving at the same speed and direction."}, {"id": "8.PS2.5-r04", "standard": "8.PS2.5", "kind": "recall", "prompt": "An unbalanced force on an object causes it to", "correct": "change speed or direction", "distractors": ["stay at a constant speed", "stay completely still", "lose mass"], "why": "Only unbalanced (nonzero net) forces change motion."}, {"id": "8.PS2.5-r05", "standard": "8.PS2.5", "kind": "recall", "prompt": "The equation a = F/m shows that acceleration", "correct": "goes up with force, down with mass", "distractors": ["decreases when more force is added", "increases when more mass is added", "does not depend on mass at all"], "why": "More force = more acceleration. More mass = less acceleration for the same force."}, {"id": "8.PS2.5-r06", "standard": "8.PS2.5", "kind": "recall", "prompt": "A 10 N push right and a 4 N push left act on a box. The net force is", "correct": "6 N right", "distractors": ["14 N right", "6 N left", "4 N right"], "why": "Opposite forces subtract: 10 − 4 = 6 N toward the larger one."}, {"id": "8.PS2.5-r07", "standard": "8.PS2.5", "kind": "recall", "prompt": "A 5 N force and a 3 N force both push a cart to the right. The net force is", "correct": "8 N right", "distractors": ["2 N right", "2 N left", "5 N right"], "why": "Forces in the same direction add."}, {"id": "8.PS2.5-r08", "standard": "8.PS2.5", "kind": "recall", "prompt": "The same force is applied to a small cart and a heavy cart. Which accelerates more?", "correct": "the small cart", "distractors": ["the heavy cart", "both accelerate the same", "neither accelerates"], "why": "With equal force, less mass gives more acceleration."}, {"id": "8.PS2.5-r09", "standard": "8.PS2.5", "kind": "recall", "prompt": "A force of 20 N acts on a 5 kg object. Its acceleration is", "correct": "4 m/s²", "distractors": ["100 m/s²", "25 m/s²", "15 m/s²"], "why": "a = F/m = 20 ÷ 5 = 4 m/s²."}, {"id": "8.PS2.5-r10", "standard": "8.PS2.5", "kind": "recall", "prompt": "A hockey puck slides on ice at a steady speed with almost no friction. The net force on it is", "correct": "about zero", "distractors": ["large and forward", "equal to its weight", "increasing"], "why": "Constant speed in a straight line means no net force. A moving object does not need a forward push to keep moving."}, {"id": "8.PS2.5-r11", "standard": "8.PS2.5", "kind": "recall", "prompt": "Acceleration is a change in", "correct": "speed or direction", "distractors": ["mass only", "weight only", "size only"], "why": "Speeding up, slowing down, and turning are all acceleration."}, {"id": "8.PS2.5-r12", "standard": "8.PS2.5", "kind": "recall", "prompt": "Friction usually acts", "correct": "opposite to the direction of motion", "distractors": ["in the same direction as motion", "straight up", "only on round objects"], "why": "Friction opposes sliding, which slows objects."}, {"id": "8.PS2.5-r13", "standard": "8.PS2.5", "kind": "recall", "prompt": "A car moves at a constant 50 km/h on a straight road. The forces on it are", "correct": "balanced", "distractors": ["unbalanced forward", "unbalanced backward", "zero because it is moving"], "why": "Constant velocity means balanced forces. The engine force equals friction and air resistance."}, {"id": "8.PS2.5-r14", "standard": "8.PS2.5", "kind": "recall", "prompt": "Doubling the net force on an object (same mass) will", "correct": "double its acceleration", "distractors": ["halve its acceleration", "not change its acceleration", "double its mass"], "why": "Acceleration is directly proportional to net force."}, {"id": "8.PS2.5-r15", "standard": "8.PS2.5", "kind": "recall", "prompt": "Doubling the mass of an object (same net force) will", "correct": "halve its acceleration", "distractors": ["double its acceleration", "not change acceleration", "double the net force"], "why": "Acceleration is inversely related to mass."}, {"id": "8.PS2.5-r16", "standard": "8.PS2.5", "kind": "recall", "prompt": "A tug-of-war is a tie. The rope does not move. The forces are", "correct": "balanced", "distractors": ["unbalanced to the left", "unbalanced to the right", "zero because no one pulls"], "why": "Both teams pull hard, but the forces are equal and opposite, so net force is zero."}, {"id": "8.PS2.5-r17", "standard": "8.PS2.5", "kind": "recall", "prompt": "A ball is rolling to the right. A force pushes it to the left. The ball will", "correct": "slow down", "distractors": ["speed up", "keep the same speed", "gain mass"], "why": "A net force opposite to the motion slows the object."}, {"id": "8.PS2.5-r18", "standard": "8.PS2.5", "kind": "recall", "prompt": "The unit used to measure force is the", "correct": "newton (N)", "distractors": ["kilogram (kg)", "meter (m)", "second (s)"], "why": "Forces are measured in newtons. Kilograms measure mass."}, {"id": "8.PS2.5-r19", "standard": "8.PS2.5", "kind": "recall", "prompt": "What force is needed to accelerate a 2 kg ball at 3 m/s²?", "correct": "6 N", "distractors": ["1.5 N", "5 N", "0.67 N"], "why": "F = m × a = 2 × 3 = 6 N."}, {"id": "8.PS2.5-r20", "standard": "8.PS2.5", "kind": "recall", "prompt": "A heavy truck and a small car brake with the same force. Which takes longer to stop?", "correct": "the heavy truck", "distractors": ["the small car", "both stop at the same time", "neither will stop"], "why": "Greater mass means less deceleration for the same force."}, {"id": "8.PS2.5-s01", "standard": "8.PS2.5", "kind": "scenario", "prompt": "A box is pushed right with 12 N. Friction is 12 N left. The box was already sliding at 1 m/s. What happens?", "correct": "It keeps sliding at 1 m/s.", "distractors": ["It slows down and stops.", "It speeds up to the right.", "It starts moving left."], "why": "Balanced forces mean no change in motion, so it keeps its speed. Balanced does not mean \"stops.\""}, {"id": "8.PS2.5-s02", "standard": "8.PS2.5", "kind": "scenario", "prompt": "Cart A (1 kg) and Cart B (4 kg) are each pushed with 8 N. Which statement is true?", "correct": "A accelerates 8 m/s²; B accelerates 2 m/s².", "distractors": ["Both accelerate 8 m/s².", "A accelerates 2 m/s², and B accelerates 8 m/s².", "Both accelerate 2 m/s²."], "why": "a = F/m: 8 ÷ 1 = 8; 8 ÷ 4 = 2."}, {"id": "8.PS2.5-s03", "standard": "8.PS2.5", "kind": "scenario", "prompt": "A student says, \"If something is moving, there must be a force pushing it forward.\" Which example shows this is wrong?", "correct": "A puck glides across ice at steady speed, no push.", "distractors": ["A car speeds up when the gas pedal is pressed.", "A ball slows down as it rolls on grass.", "A box stays put on a table with no push."], "why": "Objects keep moving without a forward force if net force is zero. A force is needed to change motion, not keep it."}, {"id": "8.PS2.5-s04", "standard": "8.PS2.5", "kind": "scenario", "prompt": "A table shows: 10 N on a 2 kg cart gives 5 m/s². 20 N on the same cart gives 10 m/s². What pattern does this show?", "correct": "Doubling force doubles acceleration.", "distractors": ["Doubling force halves acceleration.", "Force has no effect on acceleration.", "Mass changed between trials."], "why": "With mass constant, acceleration rises in step with net force."}, {"id": "8.PS2.5-s05", "standard": "8.PS2.5", "kind": "scenario", "prompt": "Two teams pull a rope. Team A pulls 300 N left; Team B pulls 350 N right. What happens to the rope?", "correct": "It accelerates right with a 50 N net force.", "distractors": ["It stays still because both pull.", "It accelerates left with a 650 N net force.", "It accelerates right with a 650 N net force."], "why": "Opposite forces subtract: 350 − 300 = 50 N toward Team B."}, {"id": "8.PS2.5-s06", "standard": "8.PS2.5", "kind": "scenario", "prompt": "A rocket's engines push up with 15,000 N. Its weight is 10,000 N. What happens?", "correct": "It accelerates upward.", "distractors": ["It stays still on the pad.", "It falls downward.", "It moves up at a constant speed."], "why": "Net force is 5,000 N up, so it accelerates up."}, {"id": "8.PS2.5-s07", "standard": "8.PS2.5", "kind": "scenario", "prompt": "A shopping cart is easier to push when empty than when full. Which idea explains this?", "correct": "More mass means less acceleration for the same push.", "distractors": ["Less mass needs more force to start moving.", "The full cart has less friction than the empty one.", "The empty cart has more gravity pulling on it."], "why": "With the same force, smaller mass gives larger acceleration."}, {"id": "8.PS2.5-s08", "standard": "8.PS2.5", "kind": "scenario", "prompt": "A soccer ball rolls across grass and slows down. What is the best explanation?", "correct": "Friction from the grass acts against its motion.", "distractors": ["The ball runs out of force as it rolls.", "Gravity pushes the ball backward on grass.", "Balanced forces make the ball slow down."], "why": "Objects don't \"run out\" of force. Friction acts opposite to motion, slowing it."}, {"id": "8.PS2.5-s09", "standard": "8.PS2.5", "kind": "scenario", "prompt": "A 3 kg object accelerates at 4 m/s². A student doubles the mass and keeps the force the same. What is the new acceleration?", "correct": "2 m/s²", "distractors": ["8 m/s²", "4 m/s²", "12 m/s²"], "why": "Force = 3 × 4 = 12 N. New a = 12 ÷ 6 = 2 m/s²."}, {"id": "8.PS2.5-s10", "standard": "8.PS2.5", "kind": "scenario", "prompt": "A skydiver falls at a constant speed. Air resistance and gravity are both acting. What must be true?", "correct": "Air resistance equals the skydiver's weight.", "distractors": ["Gravity is larger than air resistance.", "Air resistance is larger than gravity.", "No forces are acting on the skydiver."], "why": "Constant speed means balanced forces, so the upward and downward forces are equal."}, {"id": "8.PS2.6-r01", "standard": "8.PS2.6", "kind": "recall", "prompt": "Newton's third law says that for every action force there is", "correct": "an equal and opposite reaction force", "distractors": ["a smaller force in the opposite direction", "a larger force in the same direction", "no reaction force unless it moves"], "why": "Forces come in equal and opposite pairs."}, {"id": "8.PS2.6-r02", "standard": "8.PS2.6", "kind": "recall", "prompt": "Action and reaction forces act on", "correct": "two different objects", "distractors": ["the same object", "only moving objects", "only heavy objects"], "why": "Because they act on different objects, they do not cancel each other out."}, {"id": "8.PS2.6-r03", "standard": "8.PS2.6", "kind": "recall", "prompt": "When you push on a wall, the wall", "correct": "pushes back on you with equal force", "distractors": ["does not push back", "pushes back with less force", "pulls you toward it"], "why": "The wall pushes back just as hard. That is why your hand feels pressure."}, {"id": "8.PS2.6-r04", "standard": "8.PS2.6", "kind": "recall", "prompt": "A swimmer pushes water backward. The water", "correct": "pushes the swimmer forward", "distractors": ["pushes the swimmer backward", "does nothing", "pulls the swimmer down"], "why": "The reaction force from the water moves the swimmer forward."}, {"id": "8.PS2.6-r05", "standard": "8.PS2.6", "kind": "recall", "prompt": "A rocket moves upward because", "correct": "it pushes gases down, and the gases push it up", "distractors": ["it pushes against the ground the whole time", "air pulls it up", "gravity pushes it up"], "why": "Rockets push exhaust out, and the exhaust pushes the rocket the opposite way. This works even in space with no air."}, {"id": "8.PS2.6-r06", "standard": "8.PS2.6", "kind": "recall", "prompt": "Why don't action-reaction pairs cancel each other?", "correct": "They act on different objects", "distractors": ["They are not equal in size", "They act in the same direction", "One of them is always zero"], "why": "Forces only cancel when they act on the same object."}, {"id": "8.PS2.6-r07", "standard": "8.PS2.6", "kind": "recall", "prompt": "When a bat hits a ball, the force on the ball is", "correct": "equal to the force on the bat", "distractors": ["greater than the force on the bat", "smaller than the force on the bat", "zero"], "why": "The pair is equal. The ball changes motion more because it has less mass."}, {"id": "8.PS2.6-r08", "standard": "8.PS2.6", "kind": "recall", "prompt": "A book rests on a table. The book pushes down on the table. The reaction force is", "correct": "the table pushing up on the book", "distractors": ["gravity pulling the book down", "the floor pushing up on the table", "the book pushing on the floor"], "why": "The pair is book-on-table and table-on-book."}, {"id": "8.PS2.6-r09", "standard": "8.PS2.6", "kind": "recall", "prompt": "When you walk, your foot pushes backward on the ground. The ground", "correct": "pushes your foot forward", "distractors": ["pushes your foot backward", "does nothing", "pulls you down"], "why": "The forward push from the ground moves you ahead."}, {"id": "8.PS2.6-r10", "standard": "8.PS2.6", "kind": "recall", "prompt": "A balloon flies across the room when air rushes out. This shows", "correct": "the air pushes the balloon the opposite way", "distractors": ["the balloon is lighter than air", "gravity stops working", "the air pulls the balloon forward"], "why": "The balloon pushes air out, and the air pushes the balloon in the opposite direction."}, {"id": "8.PS2.6-r11", "standard": "8.PS2.6", "kind": "recall", "prompt": "A small car and a large truck collide. The force on the car is", "correct": "equal to the force on the truck", "distractors": ["greater than the force on the truck", "less than the force on the truck", "zero"], "why": "Forces in a pair are always equal. The car is damaged more because its smaller mass changes motion more."}, {"id": "8.PS2.6-r12", "standard": "8.PS2.6", "kind": "recall", "prompt": "An astronaut in space throws a tool forward. The astronaut will", "correct": "move backward", "distractors": ["move forward", "stay perfectly still", "spin in place"], "why": "Pushing the tool forward means the tool pushes the astronaut backward."}, {"id": "8.PS2.6-r13", "standard": "8.PS2.6", "kind": "recall", "prompt": "Which is an action-reaction pair?", "correct": "a hammer hits a nail; the nail pushes on the hammer", "distractors": ["gravity pulls a book, and the table pushes up on it", "a car speeds up, and friction slows it down", "a ball falls, and air pushes up on it"], "why": "A true pair involves the same two objects pushing on each other."}, {"id": "8.PS2.6-r14", "standard": "8.PS2.6", "kind": "recall", "prompt": "Earth pulls on you with gravity. The reaction force is", "correct": "you pulling on Earth with equal force", "distractors": ["the floor pushing you up", "air pushing you down", "your muscles pushing you up"], "why": "You pull Earth just as hard, but Earth's huge mass means it barely moves."}, {"id": "8.PS2.6-r15", "standard": "8.PS2.6", "kind": "recall", "prompt": "A fire hose pushes back on the firefighter holding it because", "correct": "the water pushes back on the hose", "distractors": ["the hose is heavier than the water", "air pushes the hose backward", "the water pulls the hose forward"], "why": "The hose pushes water forward, so the water pushes the hose backward with an equal force. That is Newton's third law."}, {"id": "8.PS2.6-r16", "standard": "8.PS2.6", "kind": "recall", "prompt": "In an action-reaction pair, the two forces are", "correct": "equal in size and opposite in direction", "distractors": ["equal in size and the same direction", "different in size and opposite direction", "different in size and same direction"], "why": "Equal size, opposite direction, different objects."}, {"id": "8.PS2.6-r17", "standard": "8.PS2.6", "kind": "recall", "prompt": "When a person jumps off a small boat onto a dock, the boat", "correct": "moves away from the dock", "distractors": ["moves toward the dock", "stays still", "sinks"], "why": "The person pushes the boat backward as the boat pushes them forward."}, {"id": "8.PS2.6-r18", "standard": "8.PS2.6", "kind": "recall", "prompt": "Two skaters push off each other. The lighter skater", "correct": "moves away faster", "distractors": ["moves away slower", "does not move", "moves toward the other"], "why": "The forces are equal, but smaller mass means greater acceleration."}, {"id": "8.PS2.6-r19", "standard": "8.PS2.6", "kind": "recall", "prompt": "A fish swims forward by", "correct": "pushing water backward with its tail", "distractors": ["pulling water forward", "pushing against the riverbed", "floating with gravity"], "why": "The water pushes back on the fish, moving it forward."}, {"id": "8.PS2.6-r20", "standard": "8.PS2.6", "kind": "recall", "prompt": "A helicopter stays up because its blades", "correct": "push air down, and the air pushes them up", "distractors": ["pull the helicopter up with magnets", "push against the ground below them", "make the air around them lighter"], "why": "Blades push air down, and the reaction force lifts the helicopter."}, {"id": "8.PS2.6-s01", "standard": "8.PS2.6", "kind": "scenario", "prompt": "Two students on skateboards push off each other. Student A has twice the mass of Student B. What happens?", "correct": "Both feel equal force; B moves away faster.", "distractors": ["A feels more force and moves faster.", "B feels more force and moves slower.", "Only B moves because A is heavier."], "why": "The force pair is equal. B's smaller mass means a larger change in motion."}, {"id": "8.PS2.6-s02", "standard": "8.PS2.6", "kind": "scenario", "prompt": "A student says, \"Rockets can't work in space because there is no air to push against.\" Which reply is correct?", "correct": "Rockets push exhaust out, and it pushes back.", "distractors": ["Correct, rockets need air to push on.", "Rockets are pulled along by the Moon.", "Rockets use magnets to move in space."], "why": "Rockets do not push on air. They push on their exhaust gases, which push back on the rocket."}, {"id": "8.PS2.6-s03", "standard": "8.PS2.6", "kind": "scenario", "prompt": "A bug hits a car windshield. Which is true about the forces?", "correct": "The forces are equal; the bug changes motion more.", "distractors": ["The car exerts a greater force on the bug.", "The bug exerts a greater force on the car.", "Only the car exerts a force."], "why": "Equal forces, but the bug's tiny mass gives it a huge change in motion."}, {"id": "8.PS2.6-s04", "standard": "8.PS2.6", "kind": "scenario", "prompt": "A person on ice skates pushes a heavy wall. What happens to the person?", "correct": "They slide backward away from the wall.", "distractors": ["They stay still because the wall is heavy.", "The wall moves forward and they stay put.", "They slide toward the wall."], "why": "The wall pushes back on the person with equal force, so they slide backward."}, {"id": "8.PS2.6-s05", "standard": "8.PS2.6", "kind": "scenario", "prompt": "A model shows Cart A pushing Cart B with 10 N. What force does Cart B exert on Cart A?", "correct": "10 N in the opposite direction", "distractors": ["10 N in the same direction", "0 N because B was pushed", "5 N in the opposite direction"], "why": "Newton's third law: equal size, opposite direction."}, {"id": "8.PS2.6-s06", "standard": "8.PS2.6", "kind": "scenario", "prompt": "A student says a horse can't pull a cart because the cart pulls back equally, so the forces cancel. What is wrong?", "correct": "The pair acts on different objects, so it does not cancel.", "distractors": ["The cart pulls back more weakly.", "The horse pulls harder than the cart pulls back.", "Nothing, the horse can't pull the cart."], "why": "The horse moves forward because the ground pushes it. Forces only cancel on the same object."}, {"id": "8.PS2.6-s07", "standard": "8.PS2.6", "kind": "scenario", "prompt": "When a cannon fires a cannonball, the cannon rolls back slowly while the ball flies fast. Why?", "correct": "Equal forces; the cannon has much more mass.", "distractors": ["The ball gets more force than the cannon.", "The cannon gets more force than the ball.", "The cannon is not pushed at all."], "why": "Equal forces but much greater mass for the cannon means much smaller acceleration."}, {"id": "8.PS2.6-s08", "standard": "8.PS2.6", "kind": "scenario", "prompt": "An astronaut floats near the station with no rope. She throws a wrench away. What happens?", "correct": "She moves away, opposite the wrench.", "distractors": ["She stays in the same place.", "She moves along with the wrench.", "She falls straight toward Earth."], "why": "The wrench pushes her back as she pushes it forward."}, {"id": "8.PS2.6-s09", "standard": "8.PS2.6", "kind": "scenario", "prompt": "A balloon rocket on a string moves left when air rushes out the right end. Which pair of forces explains this?", "correct": "Balloon pushes air right; air pushes balloon left.", "distractors": ["Air pulls the balloon left, and the string pulls right.", "Gravity pulls the balloon left, and air pushes right.", "The string pushes the balloon left."], "why": "The balloon pushes air one way, and the air pushes the balloon the other way."}, {"id": "8.PS2.6-s10", "standard": "8.PS2.6", "kind": "scenario", "prompt": "A soccer player kicks a ball and feels her foot sting. Which explains the sting?", "correct": "The ball pushes back on her foot.", "distractors": ["Her foot pushes harder than the ball.", "Gravity pulls her foot down.", "The ball has no force on her foot."], "why": "The ball exerts an equal and opposite force back on her foot."}, {"id": "8.PS4.1-r01", "standard": "8.PS4.1", "kind": "recall", "prompt": "The amplitude of a wave is", "correct": "the height from rest position to crest", "distractors": ["the distance from one crest to the next", "the number of waves that pass each second", "how fast the wave travels through matter"], "why": "Amplitude is height from rest. Crest-to-crest distance is wavelength, a common mix-up."}, {"id": "8.PS4.1-r02", "standard": "8.PS4.1", "kind": "recall", "prompt": "Wavelength is the distance", "correct": "from one crest to the next crest", "distractors": ["from rest to the crest", "a wave travels in one second", "from the crest to the trough"], "why": "Wavelength is one full cycle, crest to crest (or trough to trough)."}, {"id": "8.PS4.1-r03", "standard": "8.PS4.1", "kind": "recall", "prompt": "Frequency is", "correct": "the number of waves passing a point each second", "distractors": ["the height of the wave from rest to crest", "the length of one wave from crest to crest", "the amount of energy in one single wave"], "why": "Frequency counts waves per second and is measured in hertz (Hz)."}, {"id": "8.PS4.1-r04", "standard": "8.PS4.1", "kind": "recall", "prompt": "Frequency is measured in", "correct": "hertz (Hz)", "distractors": ["meters (m)", "newtons (N)", "meters per second (m/s)"], "why": "1 Hz means one wave per second."}, {"id": "8.PS4.1-r05", "standard": "8.PS4.1", "kind": "recall", "prompt": "A wave with greater amplitude carries", "correct": "more energy", "distractors": ["less energy", "the same energy", "no energy"], "why": "Bigger amplitude means more energy, like louder sound or brighter light."}, {"id": "8.PS4.1-r06", "standard": "8.PS4.1", "kind": "recall", "prompt": "Waves transfer", "correct": "energy from one place to another", "distractors": ["matter from one place to another", "only water", "only air"], "why": "The medium vibrates in place; the energy is what travels."}, {"id": "8.PS4.1-r07", "standard": "8.PS4.1", "kind": "recall", "prompt": "If wave speed stays the same and frequency increases, wavelength", "correct": "decreases", "distractors": ["increases", "stays the same", "doubles in height"], "why": "Speed = frequency × wavelength. Higher frequency squeezes waves closer together."}, {"id": "8.PS4.1-r08", "standard": "8.PS4.1", "kind": "recall", "prompt": "Wave speed equals", "correct": "frequency × wavelength", "distractors": ["amplitude × frequency", "wavelength ÷ amplitude", "amplitude ÷ time"], "why": "v = f × λ."}, {"id": "8.PS4.1-r09", "standard": "8.PS4.1", "kind": "recall", "prompt": "A wave has a frequency of 5 Hz and a wavelength of 2 m. Its speed is", "correct": "10 m/s", "distractors": ["2.5 m/s", "7 m/s", "3 m/s"], "why": "v = 5 × 2 = 10 m/s."}, {"id": "8.PS4.1-r10", "standard": "8.PS4.1", "kind": "recall", "prompt": "The highest point of a transverse wave is the", "correct": "crest", "distractors": ["trough", "wavelength", "rest position"], "why": "Crest = top, trough = bottom."}, {"id": "8.PS4.1-r11", "standard": "8.PS4.1", "kind": "recall", "prompt": "The lowest point of a transverse wave is the", "correct": "trough", "distractors": ["crest", "amplitude", "frequency"], "why": "The trough is the bottom of the wave."}, {"id": "8.PS4.1-r12", "standard": "8.PS4.1", "kind": "recall", "prompt": "In a transverse wave, the medium moves", "correct": "perpendicular to the direction the wave travels", "distractors": ["in the same direction the wave travels", "in circles only", "not at all"], "why": "Up-and-down motion while the wave moves sideways makes it transverse."}, {"id": "8.PS4.1-r13", "standard": "8.PS4.1", "kind": "recall", "prompt": "In a longitudinal wave, the medium moves", "correct": "parallel to the direction the wave travels", "distractors": ["perpendicular to the direction of travel", "not at all", "only up and down"], "why": "Sound waves are longitudinal: particles push and pull in the same direction the wave travels."}, {"id": "8.PS4.1-r14", "standard": "8.PS4.1", "kind": "recall", "prompt": "Sound waves are", "correct": "longitudinal waves", "distractors": ["transverse waves", "not waves", "electromagnetic waves"], "why": "Sound is compressions and rarefactions in a medium."}, {"id": "8.PS4.1-r15", "standard": "8.PS4.1", "kind": "recall", "prompt": "A louder sound has a greater", "correct": "amplitude", "distractors": ["frequency", "wavelength", "speed"], "why": "Loudness relates to amplitude. Pitch relates to frequency."}, {"id": "8.PS4.1-r16", "standard": "8.PS4.1", "kind": "recall", "prompt": "A higher-pitched sound has a higher", "correct": "frequency", "distractors": ["amplitude", "wavelength", "mass"], "why": "Pitch is set by frequency."}, {"id": "8.PS4.1-r17", "standard": "8.PS4.1", "kind": "recall", "prompt": "In a longitudinal wave, areas where particles are crowded together are called", "correct": "compressions", "distractors": ["rarefactions", "troughs", "crests"], "why": "Compressions are crowded; rarefactions are spread out."}, {"id": "8.PS4.1-r18", "standard": "8.PS4.1", "kind": "recall", "prompt": "If you shake a rope faster without changing its tension,", "correct": "frequency increases and wavelength decreases", "distractors": ["frequency decreases and wavelength increases", "amplitude decreases", "speed doubles"], "why": "Wave speed in the rope stays the same, so more waves per second means shorter waves."}, {"id": "8.PS4.1-r19", "standard": "8.PS4.1", "kind": "recall", "prompt": "Which change would make a wave carry LESS energy?", "correct": "smaller amplitude", "distractors": ["larger amplitude", "deeper troughs", "taller crests"], "why": "Smaller amplitude means less energy."}, {"id": "8.PS4.1-r20", "standard": "8.PS4.1", "kind": "recall", "prompt": "A wave that travels 30 m in 10 s has a speed of", "correct": "3 m/s", "distractors": ["300 m/s", "20 m/s", "40 m/s"], "why": "Speed = distance ÷ time = 30 ÷ 10 = 3 m/s."}, {"id": "8.PS4.1-s01", "standard": "8.PS4.1", "kind": "scenario", "prompt": "Two waves have the same speed. Wave A has a frequency of 2 Hz; Wave B has 4 Hz. Which has the longer wavelength?", "correct": "Wave A", "distractors": ["Wave B", "They are the same", "You can't tell without amplitude"], "why": "Same speed, lower frequency means a longer wavelength. Amplitude doesn't affect wavelength."}, {"id": "8.PS4.1-s02", "standard": "8.PS4.1", "kind": "scenario", "prompt": "A student draws a wave and labels the distance from rest to crest as \"wavelength.\" What is wrong?", "correct": "That distance is the amplitude, not wavelength.", "distractors": ["That is correct, it is the wavelength.", "That distance is the frequency of the wave.", "That distance is the speed of the wave."], "why": "Rest to crest is amplitude. Wavelength is crest to crest."}, {"id": "8.PS4.1-s03", "standard": "8.PS4.1", "kind": "scenario", "prompt": "A guitarist plucks a string harder, and the note gets louder but the pitch stays the same. What changed?", "correct": "the amplitude", "distractors": ["the frequency", "the wavelength", "the wave speed"], "why": "Plucking harder increases amplitude (loudness), not frequency (pitch)."}, {"id": "8.PS4.1-s04", "standard": "8.PS4.1", "kind": "scenario", "prompt": "A water wave has a wavelength of 4 m and a frequency of 0.5 Hz. What is its speed?", "correct": "2 m/s", "distractors": ["8 m/s", "4.5 m/s", "0.125 m/s"], "why": "v = f × λ = 0.5 × 4 = 2 m/s."}, {"id": "8.PS4.1-s05", "standard": "8.PS4.1", "kind": "scenario", "prompt": "A cork floats on a pond as waves pass. The cork bobs up and down but stays in place. What does this show?", "correct": "Waves carry energy, not the water, forward.", "distractors": ["The water moves along with the wave.", "The cork is too heavy for the wave to move.", "Waves on a pond carry no energy."], "why": "The water vibrates in place while energy moves through it."}, {"id": "8.PS4.1-s06", "standard": "8.PS4.1", "kind": "scenario", "prompt": "Wave X has twice the amplitude of Wave Y. Both have the same frequency. Which is true?", "correct": "X carries more energy than Y.", "distractors": ["Y carries more energy than X.", "They carry the same energy.", "X has a shorter wavelength."], "why": "Greater amplitude means more energy. Frequency and wavelength are unchanged."}, {"id": "8.PS4.1-s07", "standard": "8.PS4.1", "kind": "scenario", "prompt": "A student shakes a spring back and forth along its length. The coils bunch up and spread out. What kind of wave is this?", "correct": "longitudinal", "distractors": ["transverse", "electromagnetic", "surface"], "why": "The coils move in the same direction as the wave, so it is longitudinal."}, {"id": "8.PS4.1-s08", "standard": "8.PS4.1", "kind": "scenario", "prompt": "A buoy rises and falls 6 times in 1 minute as waves pass. What is the frequency?", "correct": "0.1 Hz", "distractors": ["6 Hz", "60 Hz", "10 Hz"], "why": "6 waves ÷ 60 seconds = 0.1 waves per second = 0.1 Hz."}, {"id": "8.PS4.1-s09", "standard": "8.PS4.1", "kind": "scenario", "prompt": "Two speakers play notes. Speaker A has a higher frequency than speaker B. Which will a listener hear?", "correct": "A has a higher pitch.", "distractors": ["A is louder.", "B has a higher pitch.", "They sound exactly the same."], "why": "Higher frequency means higher pitch. Loudness depends on amplitude."}, {"id": "8.PS4.1-s10", "standard": "8.PS4.1", "kind": "scenario", "prompt": "A wave machine makes waves with the same amplitude but doubles the frequency. Wave speed stays the same. What happens to wavelength?", "correct": "It is cut in half.", "distractors": ["It doubles.", "It stays the same.", "It becomes zero."], "why": "Speed = f × λ. Doubling f with constant speed halves λ."}, {"id": "8.PS4.2-r01", "standard": "8.PS4.2", "kind": "recall", "prompt": "A mechanical wave needs", "correct": "a medium to travel through", "distractors": ["no medium at all", "empty space", "only light"], "why": "Mechanical waves like sound need matter (solid, liquid, or gas)."}, {"id": "8.PS4.2-r02", "standard": "8.PS4.2", "kind": "recall", "prompt": "Electromagnetic waves can travel through", "correct": "a vacuum (empty space)", "distractors": ["only solids", "only liquids", "only air"], "why": "Light crosses space from the Sun with no medium."}, {"id": "8.PS4.2-r03", "standard": "8.PS4.2", "kind": "recall", "prompt": "Sound cannot travel through", "correct": "a vacuum", "distractors": ["air", "water", "steel"], "why": "Sound needs particles to vibrate. Space has almost none."}, {"id": "8.PS4.2-r04", "standard": "8.PS4.2", "kind": "recall", "prompt": "Which is an electromagnetic wave?", "correct": "visible light", "distractors": ["sound", "an ocean wave", "a seismic wave"], "why": "Sound, ocean waves, and seismic waves are mechanical. Light is electromagnetic."}, {"id": "8.PS4.2-r05", "standard": "8.PS4.2", "kind": "recall", "prompt": "Which is a mechanical wave?", "correct": "sound", "distractors": ["radio waves", "X-rays", "visible light"], "why": "Radio, X-rays, and light are electromagnetic. Sound needs a medium."}, {"id": "8.PS4.2-r06", "standard": "8.PS4.2", "kind": "recall", "prompt": "Sound generally travels fastest through", "correct": "solids", "distractors": ["liquids", "gases", "a vacuum"], "why": "Particles are closer in solids, so sound travels faster. Sound can't travel in a vacuum at all."}, {"id": "8.PS4.2-r07", "standard": "8.PS4.2", "kind": "recall", "prompt": "Reflection happens when a wave", "correct": "bounces off a surface", "distractors": ["passes through a material", "bends into a new material", "is absorbed as heat"], "why": "An echo is reflected sound."}, {"id": "8.PS4.2-r08", "standard": "8.PS4.2", "kind": "recall", "prompt": "Refraction is when a wave", "correct": "bends as it enters a new material", "distractors": ["bounces off a smooth surface", "stops completely at the boundary", "turns into a sound wave"], "why": "Waves bend because they change speed in a new medium."}, {"id": "8.PS4.2-r09", "standard": "8.PS4.2", "kind": "recall", "prompt": "Absorption is when a material", "correct": "takes in a wave's energy", "distractors": ["bounces the wave back", "bends the wave", "speeds up the wave"], "why": "Absorbed energy often becomes heat, like sunlight warming a dark shirt."}, {"id": "8.PS4.2-r10", "standard": "8.PS4.2", "kind": "recall", "prompt": "Transmission is when a wave", "correct": "passes through a material", "distractors": ["bounces off a surface", "is absorbed completely", "stops at a boundary"], "why": "Light passing through clear glass is transmitted."}, {"id": "8.PS4.2-r11", "standard": "8.PS4.2", "kind": "recall", "prompt": "A straw in water looks bent because light", "correct": "refracts as it passes from water to air", "distractors": ["reflects off the shiny straw", "is absorbed by the water around it", "stops at the surface of the water"], "why": "Light changes speed and bends at the water-air boundary."}, {"id": "8.PS4.2-r12", "standard": "8.PS4.2", "kind": "recall", "prompt": "An echo is an example of", "correct": "reflection", "distractors": ["refraction", "absorption", "transmission"], "why": "Sound bounces off a hard surface and returns to you."}, {"id": "8.PS4.2-r13", "standard": "8.PS4.2", "kind": "recall", "prompt": "Why does a black shirt feel hotter in sunlight than a white one?", "correct": "It absorbs more light energy", "distractors": ["It reflects more light energy", "It transmits more light", "It bends more light"], "why": "Dark colors absorb more light and turn it into heat. White reflects more."}, {"id": "8.PS4.2-r14", "standard": "8.PS4.2", "kind": "recall", "prompt": "Light travels fastest in", "correct": "a vacuum", "distractors": ["water", "glass", "diamond"], "why": "Light slows down in materials. It is fastest in empty space."}, {"id": "8.PS4.2-r15", "standard": "8.PS4.2", "kind": "recall", "prompt": "Light from the Sun reaches Earth because", "correct": "light waves don't need a medium", "distractors": ["air fills space between Earth and Sun", "sound carries the light", "the Moon reflects all of it"], "why": "Space is nearly empty, but EM waves can travel through a vacuum."}, {"id": "8.PS4.2-r16", "standard": "8.PS4.2", "kind": "recall", "prompt": "A mirror mostly", "correct": "reflects light", "distractors": ["absorbs light", "transmits light", "refracts sound"], "why": "Smooth, shiny surfaces reflect most light."}, {"id": "8.PS4.2-r17", "standard": "8.PS4.2", "kind": "recall", "prompt": "A clear glass window mostly", "correct": "transmits light", "distractors": ["reflects all light", "absorbs all light", "blocks all light"], "why": "Clear glass lets most light pass through."}, {"id": "8.PS4.2-r18", "standard": "8.PS4.2", "kind": "recall", "prompt": "When light passes from air into glass at an angle, it", "correct": "bends toward the normal and slows", "distractors": ["speeds up and bends away", "stops completely", "turns into heat only"], "why": "Glass is optically denser, so light slows and bends toward the normal line."}, {"id": "8.PS4.2-r19", "standard": "8.PS4.2", "kind": "recall", "prompt": "Soft foam on studio walls is used to", "correct": "absorb sound", "distractors": ["reflect sound", "amplify sound", "refract light"], "why": "Foam absorbs sound energy to reduce echoes."}, {"id": "8.PS4.2-r20", "standard": "8.PS4.2", "kind": "recall", "prompt": "Which statement about mechanical and EM waves is correct?", "correct": "EM waves can cross a vacuum; mechanical cannot", "distractors": ["Both need a medium", "Neither can travel in water", "Mechanical waves cross a vacuum, but EM cannot"], "why": "Only EM waves can travel through empty space."}, {"id": "8.PS4.2-s01", "standard": "8.PS4.2", "kind": "scenario", "prompt": "An alarm clock ringing in a jar goes silent as air is pumped out, but you can still see it. Why?", "correct": "Sound needs a medium; light does not.", "distractors": ["Light needs a medium, but sound does not.", "The clock stopped ringing.", "The glass blocks sound but not light."], "why": "Removing air removes the medium for sound. Light, an EM wave, still crosses the vacuum."}, {"id": "8.PS4.2-s02", "standard": "8.PS4.2", "kind": "scenario", "prompt": "Astronauts on the Moon use radios to talk, even standing close together. Why?", "correct": "Sound can't cross a vacuum, but radio waves can.", "distractors": ["Radio waves are much louder than sound.", "Their helmets block light from passing.", "Sound travels too fast on the Moon to hear."], "why": "With no air, sound can't reach the other astronaut. Radio waves are EM and cross the vacuum."}, {"id": "8.PS4.2-s03", "standard": "8.PS4.2", "kind": "scenario", "prompt": "A student shines a flashlight at a glass of water at an angle. The beam bends at the surface. What is happening?", "correct": "refraction", "distractors": ["reflection", "absorption", "transmission without bending"], "why": "The light changes speed at the boundary and bends."}, {"id": "8.PS4.2-s04", "standard": "8.PS4.2", "kind": "scenario", "prompt": "A gym has hard walls and bad echoes. Which change would reduce echoes best?", "correct": "Hang soft panels to absorb sound.", "distractors": ["Paint the walls shiny white.", "Add more mirrors.", "Make the walls harder."], "why": "Soft materials absorb sound energy, so less is reflected."}, {"id": "8.PS4.2-s05", "standard": "8.PS4.2", "kind": "scenario", "prompt": "You hear thunder several seconds after seeing lightning. What does this show?", "correct": "Light travels much faster than sound in air.", "distractors": ["Sound travels faster than light.", "Light needs a medium to travel.", "Thunder happens later than lightning."], "why": "Both happen at once. Light arrives almost instantly; sound is much slower."}, {"id": "8.PS4.2-s06", "standard": "8.PS4.2", "kind": "scenario", "prompt": "A student puts an ear to a metal railing and hears a tap from far away before hearing it through the air. Why?", "correct": "Sound travels faster in solids than in air.", "distractors": ["Metal makes the sound louder, not faster.", "Sound is an electromagnetic wave.", "Air blocks sound from traveling at all."], "why": "Particles in solids are closer together, so sound travels faster."}, {"id": "8.PS4.2-s07", "standard": "8.PS4.2", "kind": "scenario", "prompt": "Light hits a brick wall. It does not pass through, and the wall warms slightly. Which two behaviors occurred?", "correct": "reflection and absorption", "distractors": ["transmission and refraction", "refraction and transmission", "transmission only"], "why": "Some light bounces off (reflection) and some energy becomes heat (absorption)."}, {"id": "8.PS4.2-s08", "standard": "8.PS4.2", "kind": "scenario", "prompt": "A student claims, \"Sound can travel through outer space if it's loud enough.\" Which response is correct?", "correct": "No. Without a medium, sound can't travel.", "distractors": ["Yes, very loud sounds can cross space.", "Yes, but only if the Sun is nearby.", "No, because light in space blocks sound."], "why": "Sound is a mechanical wave and needs particles. Amplitude does not change that."}, {"id": "8.PS4.2-s09", "standard": "8.PS4.2", "kind": "scenario", "prompt": "A ray of light enters water from air at an angle. Which statement describes what happens?", "correct": "It slows down and bends.", "distractors": ["It speeds up and stays straight.", "It stops at the surface.", "It speeds up and bends away."], "why": "Light slows in water, which bends its path."}, {"id": "8.PS4.2-s10", "standard": "8.PS4.2", "kind": "scenario", "prompt": "Sunglasses reduce glare from a lake. Which wave behavior causes the glare?", "correct": "reflection of light off the water", "distractors": ["absorption of light by the water", "refraction of sound", "transmission of sound"], "why": "Glare is light reflected off the water's surface."}, {"id": "8.PS4.3-r01", "standard": "8.PS4.3", "kind": "recall", "prompt": "An analog signal", "correct": "changes smoothly and continuously", "distractors": ["uses only the values 1 and 0", "cannot carry any sound", "is always sent without wires"], "why": "Analog signals vary continuously, like the groove of a vinyl record. Digital uses discrete values."}, {"id": "8.PS4.3-r02", "standard": "8.PS4.3", "kind": "recall", "prompt": "A digital signal", "correct": "is made of separate values, often 1s and 0s", "distractors": ["changes smoothly, like a sound wave", "cannot be stored on any device", "always loses quality each time it is copied"], "why": "Digital signals are discrete pulses, usually binary 1s and 0s."}, {"id": "8.PS4.3-r03", "standard": "8.PS4.3", "kind": "recall", "prompt": "Digital signals are more reliable than analog because", "correct": "small noise doesn't change the 1s and 0s", "distractors": ["they never use any electricity", "they are always louder than analog", "they travel faster than light"], "why": "A receiver only needs to tell a 1 from a 0, so small noise is ignored."}, {"id": "8.PS4.3-r04", "standard": "8.PS4.3", "kind": "recall", "prompt": "Digitizing a sound means", "correct": "measuring it many times a second as numbers", "distractors": ["making the sound much louder", "turning the sound into light only", "removing all of its frequencies"], "why": "Samples are taken often and turned into binary numbers."}, {"id": "8.PS4.3-r05", "standard": "8.PS4.3", "kind": "recall", "prompt": "A bit is", "correct": "a single 1 or 0", "distractors": ["a type of analog wave", "a speaker part", "eight bytes"], "why": "A bit is the smallest piece of digital information."}, {"id": "8.PS4.3-r06", "standard": "8.PS4.3", "kind": "recall", "prompt": "Copying a digital file usually", "correct": "keeps the exact same quality", "distractors": ["lowers quality each time", "adds hiss each time", "erases the original"], "why": "Digital copies can be exact because the 1s and 0s are the same."}, {"id": "8.PS4.3-r07", "standard": "8.PS4.3", "kind": "recall", "prompt": "Copying an analog tape many times usually", "correct": "adds noise and lowers quality", "distractors": ["keeps perfect quality", "turns it into digital", "makes it louder"], "why": "Each analog copy picks up noise, which builds up."}, {"id": "8.PS4.3-r08", "standard": "8.PS4.3", "kind": "recall", "prompt": "Taking more samples per second when digitizing sound", "correct": "makes the copy closer to the original", "distractors": ["makes the sound much worse", "makes the file much smaller", "has no effect on the sound"], "why": "More samples capture more detail of the original wave."}, {"id": "8.PS4.3-r09", "standard": "8.PS4.3", "kind": "recall", "prompt": "Which is an example of a digital device?", "correct": "a smartphone storing music", "distractors": ["a vinyl record player", "a liquid thermometer", "a sundial in a garden"], "why": "Smartphones store sound as binary numbers."}, {"id": "8.PS4.3-r10", "standard": "8.PS4.3", "kind": "recall", "prompt": "Which is an example of analog information?", "correct": "the groove on a vinyl record", "distractors": ["a text message stored on a phone", "a song saved as an MP3", "a photo saved as pixels"], "why": "The record's groove changes smoothly with the sound."}, {"id": "8.PS4.3-r11", "standard": "8.PS4.3", "kind": "recall", "prompt": "Noise in a signal is", "correct": "unwanted changes in a signal", "distractors": ["the loudness of the signal", "the number of bits in a file", "the frequency of light used"], "why": "Noise is interference that can blur or change the message."}, {"id": "8.PS4.3-r12", "standard": "8.PS4.3", "kind": "recall", "prompt": "Wi-Fi and cell phones send information by", "correct": "encoding digital data in radio waves", "distractors": ["using cables that run to every phone", "using only analog light", "sending sound waves to a tower"], "why": "Radio waves carry the 1s and 0s through the air."}, {"id": "8.PS4.3-r13", "standard": "8.PS4.3", "kind": "recall", "prompt": "Fiber-optic cables carry digital data using", "correct": "pulses of light", "distractors": ["sound waves", "water", "static charge"], "why": "On-off light pulses represent 1s and 0s."}, {"id": "8.PS4.3-r14", "standard": "8.PS4.3", "kind": "recall", "prompt": "Which is a disadvantage of digital signals?", "correct": "Converting analog can lose detail", "distractors": ["They can never be copied exactly", "They cannot be stored on devices", "They need no electricity to work"], "why": "Sampling captures snapshots, so tiny details between samples can be lost."}, {"id": "8.PS4.3-r15", "standard": "8.PS4.3", "kind": "recall", "prompt": "A barcode is read by a scanner as", "correct": "a pattern of digital information", "distractors": ["an analog sound wave", "a chemical signal in ink", "a magnetic field only"], "why": "The bars stand for digital codes."}, {"id": "8.PS4.3-r16", "standard": "8.PS4.3", "kind": "recall", "prompt": "More bits used per sample in digital audio means", "correct": "more detail in each sample", "distractors": ["less detail in each sample", "louder sound only", "a shorter song"], "why": "More bits allow more exact values for each sample."}, {"id": "8.PS4.3-r17", "standard": "8.PS4.3", "kind": "recall", "prompt": "Digital data can be compressed so that", "correct": "files take up less storage space", "distractors": ["signals change from digital to analog", "sound changes into light", "more noise is always added"], "why": "Compression removes repeats or unneeded detail to save space."}, {"id": "8.PS4.3-r18", "standard": "8.PS4.3", "kind": "recall", "prompt": "A digital signal received with some noise can be", "correct": "cleaned up to recover the 1s and 0s", "distractors": ["made into a perfect analog signal", "never recovered once noise is added", "recovered only if it is louder"], "why": "Since only two values are possible, the receiver can restore them."}, {"id": "8.PS4.3-r19", "standard": "8.PS4.3", "kind": "recall", "prompt": "Which describes how a phone call is sent today?", "correct": "Voice is turned into digital data, sent, and decoded", "distractors": ["The call is stored, then sent the next day", "Voice travels as an analog wave the whole way", "The sound is carried by wires as light only"], "why": "Phones digitize your voice, send it as data, and turn it back into sound."}, {"id": "8.PS4.3-r20", "standard": "8.PS4.3", "kind": "recall", "prompt": "Why do space probes send pictures back as digital data?", "correct": "Digital data resists noise over long distances", "distractors": ["Analog signals travel faster in space", "Digital data needs no energy", "Analog signals can't carry images at all"], "why": "Digital signals stay readable even when weak and noisy after traveling far."}, {"id": "8.PS4.3-s01", "standard": "8.PS4.3", "kind": "scenario", "prompt": "A song is played over an old analog radio and sounds full of static. The same song streamed digitally sounds clear. What best explains this?", "correct": "Digital receivers ignore small noise in 1s and 0s.", "distractors": ["Digital signals are always louder than analog.", "Analog radio sends sound waves through the air.", "Streaming does not use waves of any kind."], "why": "Small noise in analog changes the wave itself. A digital receiver only has to pick 1 or 0."}, {"id": "8.PS4.3-s02", "standard": "8.PS4.3", "kind": "scenario", "prompt": "A student copies a cassette tape, then copies that copy, five times. The last copy sounds worse. If she did this with a digital file, what would happen?", "correct": "Each copy would sound like the original.", "distractors": ["Each copy would sound worse than the last.", "The file would turn back into a tape.", "The file would get louder each time."], "why": "Digital copies repeat the same 1s and 0s exactly."}, {"id": "8.PS4.3-s03", "standard": "8.PS4.3", "kind": "scenario", "prompt": "A sound wave is digitized by sampling 10 times per second. It sounds choppy. What would most improve it?", "correct": "Sample many more times per second.", "distractors": ["Sample fewer times per second.", "Use an analog signal instead.", "Turn up the volume."], "why": "More samples capture the wave's shape more accurately."}, {"id": "8.PS4.3-s04", "standard": "8.PS4.3", "kind": "scenario", "prompt": "A message is sent as 1011. Noise changes the voltage slightly but each pulse is still clearly high or low. What does the receiver get?", "correct": "1011, the same message", "distractors": ["a blurry version of 1011", "nothing at all", "0100, the opposite"], "why": "Small noise doesn't flip clear highs and lows."}, {"id": "8.PS4.3-s05", "standard": "8.PS4.3", "kind": "scenario", "prompt": "A city replaces its analog TV broadcasts with digital broadcasts. Which benefit is most likely?", "correct": "Clearer pictures with less static and ghosting.", "distractors": ["TVs no longer need electricity.", "Signals travel through solid walls only.", "Broadcasts can only be in black and white."], "why": "Digital signals resist noise, giving cleaner pictures."}, {"id": "8.PS4.3-s06", "standard": "8.PS4.3", "kind": "scenario", "prompt": "A thermometer with a liquid line and a thermometer with a number display both read 72°F. Which is digital?", "correct": "the one with the number display", "distractors": ["the one with the liquid line", "both are digital", "neither is digital"], "why": "The number display shows discrete values. The liquid line changes smoothly (analog)."}, {"id": "8.PS4.3-s07", "standard": "8.PS4.3", "kind": "scenario", "prompt": "A probe near Saturn sends a weak signal to Earth. Engineers still get clear images. Why is digital helpful here?", "correct": "Weak, noisy pulses can still be read as 1s and 0s.", "distractors": ["Digital signals get stronger with distance.", "Analog signals can't travel in space.", "Digital signals do not need waves."], "why": "Even weak digital pulses can be decoded if highs and lows can be told apart."}, {"id": "8.PS4.3-s08", "standard": "8.PS4.3", "kind": "scenario", "prompt": "A student says, \"Digital music is better in every way.\" Which is a fair counterpoint?", "correct": "Sampling can miss some details of the sound.", "distractors": ["Digital files can never be copied at all.", "Digital music needs vinyl records to play.", "Digital files always sound worse than tapes."], "why": "Digitizing takes snapshots, so some detail can be lost unless sampling is high enough."}, {"id": "8.PS4.3-s09", "standard": "8.PS4.3", "kind": "scenario", "prompt": "Light pulses in a fiber-optic cable are on, off, on, on. What do they most likely represent?", "correct": "the binary code 1011", "distractors": ["an analog sound wave", "four different colors", "the speed of light"], "why": "On = 1, off = 0, so the pattern is 1011."}, {"id": "8.PS4.3-s10", "standard": "8.PS4.3", "kind": "scenario", "prompt": "An image file uses 8 bits per pixel. Another uses 24 bits per pixel. Which statement is true?", "correct": "The 24-bit image can show more colors.", "distractors": ["The 8-bit image can show more colors.", "They show the same number of colors.", "The 24-bit image is analog."], "why": "More bits per pixel allow more possible color values."}]};
